/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180514-6","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"区民委員会","time":"午後 １時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"品川区・山北町交流３０周年記念事業","agenda":"品川区・山北町交流３０周年記念事業","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"山北町との交流ということで、今後も続けてほしいと求めました。最近変わったような記憶があるのですが、今後、この交流事業がどういうふうに進められていくのかをご説明ほしいと求めました。","respondent":"伊崎地域活動課長","answer":"お尋ねは、事業の仕組みや形。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"ありがとうございました。今後、山北との交流は続けていくお考えだとは思うのですけれども、どういう方向をもって進めていくのか、その辺だけ最後に伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"土地の利用料につきましても、３年間かけまして半々の負担になるようにということで、今ちょうどその過渡期です。いろいろと事業についても、より活性化できないかというところで、話し合っているところです。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういうことは把握されているのか教えていただきたいのと、これは森林セラピー体験の運営委託費に交流３０周年記念式典のも入っているのか、この辺の予算を教えていただけますか。","respondent":"伊崎地域活動課長","answer":"病気の予防につながるようなさまざまなヘルスケアのサービスについて進めていくという方針を出しておりまして、県として取り組んでいらっしゃいます。それで、神奈川県の事業の一環として、神奈川県の山北町ですので、山北町が森林セラピーを実施すると。","id":"exchange-003"}]},{"id":"topic-02","title":"ユニバーサルスポーツフェスタの開催","agenda":"ユニバーサルスポーツフェスタの開催","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回、第１回目ということなので、この事業を始めるきっかけや動機について、またその背景についてお伺いしたいと思います。ぜひしっかり連動して進めていただきたいと思うのですけれども、そこについて伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"毎月第２・第４土曜日には、体育館で障害者スポーツフリー教室をやってあります。こういったことで、ユニバーサルスポーツということでいろいろなスポーツを広めていこうということで、やらせていただいているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、日常的な品川でのスポーツの事業の発展につなげてほしいと求めましたけれども、いかがでしょうかというのが１つです。企画が終わった後の周知という視点も大事にしてほしいと求めましたけれども、それぞれ３点、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"看護師を常に１名配置してございまして、特段、そういったスポーツフェスタをつくっていきたいなと考えているところです。こういったことの周知は当然のことですけれども、そのほかに、新たに定期的にスポーツ教室を開けるようなことを考えているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"課長から城南地区にも障害者スポーツセンターの設置を要望されているということで、会場を使えるように進めていく、そこが大事だと思うのです。城南地区の整備はもちろんのこと、品川としてもそういう視点を持って進めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"１０月以降にお休みするということで先日の委員会でご報告をさせていただきました。こういったところで、工事のある際に、こういった改修ができるものにつきましては改修していくということで考えております。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"やはりきっかけがなかなかない、本当はご家族も含めてもうちょっと参加できる場を求めたりしていて、うまくマッチングができていない。それと、今回、それを踏まえて、全体の参加者がどれぐらいで、うち障害者の方はどれぐらいが望ましいとか、目標があるかどうか、説明を求めました。","respondent":"池田スポーツ推進課長","answer":"ユニバーサルスポーツ大会、これが昨年１１月に行われた際にはおよそ１００人、２月に行われた際には７０人ほど参加されました。やはり１０人以上の方がということで、だんだんと障害をお持ちの方、高齢者の方が参加をしていただくようなことになっています。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そうしたら今度、次の質問は、定期的な運動教室とのかかわりというのですか、どっちが先でもいいです。そういう考え方をもとに、障害者団体、品川でいうと７団体あったかと思いますので、そういったところとの連携をどのようにお考えか、説明を求めました。","respondent":"池田スポーツ推進課長","answer":"もう１つ、今回も知的障害団体の会長等といろいろとお話をしながら、こういったスポーツフェスタを進めさせていただいているところです。今後もそういった障害者団体の方との協議を行っていくということを考えてあります。","id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"どうしてもお伺いしたいのですけれども、今日最後なのでお伺いしたいと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"今現在の２年生から６年生に対するまもるっち３の展開という質問のときの答弁が、今年度の新４年生も対象となっているのかということがわかりづらく、確認をさせてください。","respondent":"菅生活安全担当課長","answer":"まもるっち３につきましては、本年度はこれまでどおり新４年生につきましては電池交換のみを行うです。来年度から、新１年生と新４年生に対しまして配布する予定となっています。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2808#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":13593,"voices":46}},{"id":"h30-20180514-7","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"厚生委員会","time":"午後 １時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"平成３０年陳情第３号 荏原地域に障害者施設の整備に関する陳情","agenda":"平成３０年陳情第３号 荏原地域に障害者施設の整備に関する陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その点についてはどう考えているか、まず１点、お聞かせください。八潮寮が廃止になった理由は何なのかについても説明を求めました。","respondent":"松山障害者福祉課長","answer":"もう一点目は、廃止したグループホームですけれども、八潮寮を３月に廃止したことは聞いております。ただ、廃止した理由ですけれども、さまざまな事業所がありますので、内部の事情ということは聞いてあります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここの計画の中には、はっきりと荏原地域に不足していると明記されているわけなのです。荏原地域にまず３年間の計画ということであれば、この３年間の計画の中で、説明を求めました。","respondent":"松山障害者福祉課長","answer":"規模がどれくらいかによって異なってまいりますので、どうしても、その定員が土地の事情によって決まってくると考えております。ただし、区といたしましては、荏原地域にできるだけ多くの定員のあるものをつくっていくことはきちんと計画に明記しています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて確認させていただきたいのです。開設を推進していく、この３年の間に区としてグループホーム、それを実行していくということで確認をさせていただいてよろしいか尋ねました。","respondent":"松山障害者福祉課長","answer":"３年の計画の中でということなので、荏原地域につくっていくという方針は、区として、この計画の中で示しています。その方向性なので、できるだけ様々な、あらゆる方法を使いながら、それに向かって、私たちの課は実際に動いていきたいです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成６年の区立西大井福祉園以来、２４年間、新たな施設がつくられていない状況だという資料を私たち厚生委員はいただいたのです。それとあわせて、先ほどの区が主体でぜひとも建てていただきたい、そういう方針を持っていただきたい、そのことについてはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"もう一つは就労継続支援Ｂ型の関係ですけれども、民間頼みではだめではないかというお話でした。様々な方法を使いまして、この計画にのせているゴールに向かって努力を重ねていきたいと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"精神が２２位、他の区の状況を何区かいろいろとお伺いして、就労継続支援Ｂ型が足りないことはないという区が多いのです。ぜひとも、そこまで区としては実現に向けて頑張るのだと、改めてそこのところを確認させていただいていいかということが１点。","respondent":"松山障害者福祉課長","answer":"区民の皆様に誠実に応えるために、私としては、ゴールを目指して必死で取り組む決意です。きちんとこちらにつくると表明していますので、ホームページ等々、事業者向けにも宣伝はしていきたいと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"愛の手帳が２４.５％、身体障害が１６．６％増加しているところでは、この需要はますますこれから増えてくるのではないかと思うのです。それに向けて１カ所でもできればというのではなくて、しっかりとその実現に向けて取り組んでいただきたいと思うのですけれども、説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この陳情者の方からも、いつまでに幾つつくるという目標をしっかり立てていかないと、１カ所できればそれでいいものではないだろうと、今回、資料をいただくときにも改めて言われましたので、私は、陳情者の思いを受けてとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ロードマップをはっきりさせて、そして実現をしていってほしいという陳情者の思いですので、そこのところを私はお聞きしたい。そういうところで、改めて質問をさせていただきました。","respondent":"松山障害者福祉課長","answer":"もちろん荏原地域で可能性のあるところを当たりまして、１カ所つくればいいということではなく、できれば複数とは思っております。３年の間にできるだけ努力を重ねて、目標に近付けたいと考えています。","id":"exchange-008"},{"speaker":"若林委員","kind":"確認","question":"３年計画で、東地区に最低１カ所、これは大変高く評価されるべきと思っています。この３年間のこのぐらいまでにめどを立てないとできないとか、こっちのパターンだと、そこのスケジュール感を確認します。","respondent":"松山障害者福祉課長","answer":"物理的な整備が必要ですので、物理的な整備につきましては、両方とも時間がかかるのはそのとおりです。民設民営以上に、おそらく１年か２年以上は指定管理のほうがお時間を頂戴することになろうかと考えています。","id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"この前の第１回目の陳情審査と今日を総合すると、３年間という中では、何としてもということでよろしいのか。これは確認をさせてください。","respondent":"松山障害者福祉課長","answer":"指定管理でも民設民営でも、ありとあらゆる手法を使いまして、区として、何としてでも３年の間に荏原地域につくっていくというのは変わらないです。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"きっと努力はあるけれども、そういう具体的なロードマップはないということを１つ確認したい。そのほかにも何か、こういうところで建てられれば検討したいというようなものはあるのか尋ねました。","respondent":"松山障害者福祉課長","answer":"区全体の土地の活用を考える関係の部署では、まだ今、協議を国や東京都と進めているところだとは聞いてあります。その所管もきちんと努めているのは聞いておりますので、この計画の３年の間に、何としてでもつくりたいというのは変わるものではございません。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"第１期品川区障害児福祉計画の中にも出ておりまして、３４ページの「取組みの方向性」の中に、機能強化に向けた取組みも出ております。各団体からさきにお聞きしていたように、結論として、そこに持っていかせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"例えば平成２８年の決算特別委員会で、今年の代表質問でも、取り上げさせていただきました。方針を私たちとしては確認させていただいたということで、要望等も含めて、この陳情については不採択で結構かと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その中で、区もこの計画に書き込んで、そして、何としてでも３年の間にはつくっていく、今日はそういう答弁も課長から聞かれました。採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大倉委員","kind":"確認","question":"ゴールを見据えて、しっかりと取り組んでいくということも確認しましたし、１カ所でいいと思っていないというお話もいただきました。そういった中で、しっかりと区の中で取り組んでいっていただくということで、この陳情に関しては不採択で結構と判断しました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-02","title":"平成３０年陳情第４号 品川区公式ホームページにおける障害福祉関連ページの充実を求める陳情","agenda":"平成３０年陳情第４号 品川区公式ホームページにおける障害福祉関連ページの充実を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、相談がまず第一だと思うのですけれども、その次には施設というところがすぐに来るようにというご要望も出されているので。その家族の方はどんな情報を求めているか、どういうホームページにしてほしいかという意見をかなり持っていらっしゃる方が多いと思うのです。","respondent":"松山障害者福祉課長","answer":"一口に障害といっても幅広い方がいらっしゃいますので、それに全部、適したホームページはなかなか難しいかもしれません。お声を直接、お伺いしながら、工夫を重ねてまいります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、情報量が少ないとお聞きしているのですけれども、できる限り情報量も増やしていただきたい。できる限り開かれた区政に、ホームページで情報公開していただきたいと思うのですが、最後にこのことだけお伺いします。","respondent":"松山障害者福祉課長","answer":"１年ごと、当然ながら、区民の方にお知らせするものだと考えています。それについては、当然、ホームページ等でも考えてまいります。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"９月１日を目指してつくられているということだったのですけれども、区のつくりやすさとか、自由度が違うのでしょうか。そこら辺を伺いたいと思います。","respondent":"松山障害者福祉課長、寺嶋高齢者福祉課長","answer":"そういう形で、同じように、今後に向けて、今、つくっているところです。ただ、具体的にどういうホームページにするかはまだまだこれからですので、まだまだ工夫は必要だと考えています。 年に１回、変更点があったら、確実に年に１回の情報の更新ができる。区の一定程度の制約の中でやっているホームページと比較しますと、かなり使い勝手がいいものだと評判をいただいてあります。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その結論についてですが、自民党・子ども未来の中でも、今回、先ほどと同様に、いろいろな検討をさせていただきました。遅くても９月１日、この陳情の要望には区として応えているということで、不採択という考え方をいたしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"結論はそういうことなのですが、品川区障害者七団体の声を既にいろいろな形でお聞きしている。それを技術的にどうするかはまた別問題で、１００％やらなければいけないのですけれども、改めていただきたいという趣旨です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"かなり改善もされてきていると思うのですけれども、常にもっと改善が望まれるところですので、さらなる充実をしていってほしいと求めました。この陳情については、ぜひとも採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問","question":"当事者の声も、つくるにあたってしっかりと聞いていくということも伺いました。今後、まだまだしっかり努力をしていかなければいけないところだと思いますので、その辺は取り組んでいってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-03","title":"品川区立平塚高齢者多世代交流支援施設運営事業者の選定に係る公募","agenda":"品川区立平塚高齢者多世代交流支援施設運営事業者の選定に係る公募","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実施要領（案）の１ページ、応募資格にある事業実績の1)・2)、どんなところがあるかがあったらお聞かせください。委託料は幾らぐらいになるのかがわかったら教えていただきたいのと、丸々区の独自の負担になるのか、その点についても説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"２点目の両方実績を有することですが、そういった実績を持つ事業者にぜひ手を挙げていただき、ご応募いただければと考えています。それと、３番の委託料につきましては、今、手元にありません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区の負担の整備そのものは、もちろんそうだと思うのですけれども、運営費も全部、区の丸々負担なのでしょうか。いま一つ、ほかのところとの違いがよくわからなかったので、もう一回、教えてほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"１番の運営費に係る部分ですが、こちらは区で負担をすることを考えてあります。１階が高齢者の方を対象にする部分、２階が在宅子育て世帯の方を対象とした事業ということで、広い意味で複合施設と捉えております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、私は、社会福祉法人などの利益を目的にしていない事業者にしていただきたいと要望しておきます。議会への報告も含めて、公表をぜひしていただきたいと私は思うのですが、いかがか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"１点目の審査員に関しましては、高齢者事業を実施いたしますので、子育て部門の区の幹部職員で構成する予定です。２点目の結果の公表につきましては、決定事業者以外の提案内容等は今のところ公開する予定はございません。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、第三者も審査委員会の中に入れるべきではないかと私は思うのですけれども、その点はどうでしょうか。選定会議等で決まったら、もうちょっと早くに公表されるのが通常ではないかと思うのですけれども、ここが４カ月ある理由は何かあるのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"今のところは、繰り返しになってしまいますが、決定事業者以外の提案内容の公開の予定はございません。議会へのご報告が必要になってまいりますので、その兼ね合いで、このスケジュールを組ませていただいてあります。","id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そのときに合わせた、その施設の形態で、区が決めていくということでいいのですか。基準というのは特にないということか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"そうです。様々な要素を総合的に考えながら、その都度、決めていきたいと考えています。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問","question":"実施要領（案）を見ながら、大崎のゆうゆうプラザは社会福祉協議会に委託していて、私も、近いところにあるので、たまにお邪魔しています。委託であれだけすばらしいサービスをしてくれるのだったら、委託でいいのではないかと思うのですけれども、何でこれを指定管理にするのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"ほかの機能が一切入っていない、大崎ゆうゆうプラザとして完結しているというところで、委託という方法を選んでおります。事業の内容が１階と２階で大きく対象が異なって、１階部分と２階部分で、指定管理が最適という判断をしています。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"要するに、事業をしっかりやってもらうために指定管理にしたという理解でよろしいのですか。私はそう理解をしようと思っているのです。","respondent":"宮尾高齢者地域支援課長","answer":"入れようと考えていますので、そういったところも総合的に考えて、今回は指定管理が最適と考えしています。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、この予算を立てたときは区でやると考えていたのか。そこがいつごろから変わったのか。","respondent":"宮尾高齢者地域支援課長","answer":"この予算の事項別に掲載をするところから、指定管理の想定のもとに考えてあります。施設が１月末に竣工して、３月のオープンに向けて、２カ月分という掲載をさせていただいてあります。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"手元に資料があるもので、見てしまったのですが、要するに、２カ月分は、区の方ではなくて、施設の方の分の費用を区の予算の中で見ているということでいいか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"委員、おっしゃるとおり、運営事業者の方の人件費として掲載させていただいてあります。","id":"exchange-031"}]},{"id":"topic-04","title":"品川区高齢者住宅生活支援サービス事業の実施","agenda":"品川区高齢者住宅生活支援サービス事業の実施","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"８月１日からと、これはずっとホームページに掲載しておくということなのかどうか、教えてください。デジタルサイネージは８月１日からということで、どのような形で区民の方に告知ができるのかどうか、説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"事業が８月１日にスタートいたしまして、場合によっては、追加で広報も検討したいと考えています。いろいろな事業を限られたスペースの中で掲載という制約もあるでしょうから、広報と連携をいたしまして、対応を考えていきたいと考えています。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"ですから、場所とかも選定をしながら、チラシをつくって、ぜひとも取り組んでほしいと求めましたので、よろしくお願いいたします。７６件と伺っておりますけれども、この流れ、実際に動き出すことができる軸はどのぐらいになるのかを説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"どういった施設に置かせていただくことが有効であるか、こういったことも考えながら対応していきたいと考えています。おそらく７月ごろかとは思うのですけれども、民生委員協議会への説明とほぼ同時進行で、７月に入ってから説明させていただこうと考えています。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"私がお伺いしたいことは全ていただいたと考えています。不動産業界の方とうまいウイン・ウインの関係をつくって、継続的にできるようにぜひともお願いをして、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この９００万円の積算根拠は、どういうことで９００万円になったのかをお聞かせほしいと求めました。東京都とかからもお金が出るという仕組みがあるのか、また、区独自でこういうことをやるのかについても説明を求めました。","respondent":"宮尾高齢者地域支援課長","answer":"初めの見込みですが、今、高齢者の住宅あっ旋決定の件数なども考慮しながら、年間２０件から３０件程度を見込んです。補助金に関するお尋ねですが、東京都から、生活支援付すまい確保事業の補助金で８００万円の補助額を見込んです。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば１年間で、平成２９年度、教えてほしいと求めました。実際、こういう事業を理解してくれて協力してくれる大家の件数とかも区としては持っているのかもお聞かせほしいと求めました。","respondent":"宮尾高齢者地域支援課長","answer":"平成２９年度の高齢者住宅あっ旋事業のあっ旋が決定した方の件数は６件、６人の方へのあっ旋が決まっております。〕","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"手元にはないけれども、この大家は協力してくれるというのを区としてつかんでいるのでしょうか。二、１人の職員が二、三十件をずっと定期的に見ていくという感じのイメージになっていくと考えればいいのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"その方の置かれている状況とかに応じて、柔軟にその辺は対応が必要になってこようかと考えています。ただ、そうはいいましても、社会福祉協議会のスタッフは１人ではなく、まず、スタートの時点では、実際に２人のスタッフで対応すると聞いております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと同時に、なかなか入れない状況ですけれども、民間でなかなか入れない高齢者や高齢者世帯が入れる高齢者住宅を区でつくっていただきたい。最後に要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の説明の中で、区の独自の事業だと言われました。こういう事業があったほうがいい、そして、それには都のこの補助金が使えると考えて進んだことなのか尋ねました。","respondent":"宮尾高齢者地域支援課長","answer":"区で制度設計をさせていただいて、新規事業を立ち上げる場合には、いろいろな補助金が使えないかと職員が必ず調べます。最終的に東京都から、この補助金が使えるというところで、お話がまとまったものです。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"社会福祉協議会の体制は、２人でスタートするということなのですが、これは毎年、継続していただきたい事業の１つです。でも、毎年、事業、対象者が拡大していく中で、まだ事業前で早いのですけれども、そこら辺の考え方が心配です。","respondent":"宮尾高齢者地域支援課長","answer":"常に、より効率的な方法で、扱う件数が増えてきたから、では、すぐ人を増やしましょうということはなかなか難しいと思います。常に、より効率的で効果的な方法を探っていきながら、場合によっては人員を増やして対応というところも考えなければいけないとは思っております。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう部分においても、生活保護の方を対象に加えてくださいという主張、要望はさせていただいたのを確認させていただきたい。これは質問にならないので、効率性も含めて、しっかりそういうシステムを考えていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-05","title":"品川区立心身障害者福祉会館の指定管理者候補者の公募","agenda":"品川区立心身障害者福祉会館の指定管理者候補者の公募","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺もお聞かせほしいと求めました。それから、これから心身障害者福祉会館がどうあるべきなのか、そこら辺をまとめたものなどがあるのかについてもお聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"これまで、区全体を見据えて、障害者福祉を今後どういうようにしていったらいいかという検討はそもそもしてまいりました。在宅支援も含めた形での機能を充実させていきたいということで、区で方針を立てまして、公募することを報告しています。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、文書にしても、きちんとまとめて、あるべき姿みたいなものは出すことが必要なのではないかという思いがするのですけれども、いかがでしょうか。そのあたりも教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"要は、点ではなくて、面として捉えるということで、今回、荏原地区全体では、非常に大きな転換点だろうと考えております。建物の建て直しができませんので、よりよい事業ができるということも含めまして、ご提案をいただきたいというのが今回の趣旨です。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"職員が直接、障害者福祉を学べる現場は必要だと思うのですが、その点はいかがでしょうか。もう一つは、実施要領（案）の１ページの財務状況で、１２分の３以上の自己資金の根拠は何か規定があるのかも教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"今回、かなり民間の専門性の高い事業者、専門性のあるスキルを持った職員に携わっていただきたいという考えも持ってあります。報酬も２カ月遅れで入ってくる状況ですので、それが年間事業費の１２分の３以上の相当額ということで、それを載せしています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１２分の３以上の自己資金となると、それが幾らくらいになるのか、委託料についてお聞かせほしいと求めました。２ページの障害者自立訓練センターの1)生活介護のところの説明の文章の２行目の真ん中くらいに、かなり財政的にも大変になっていくのではないか。","respondent":"松山障害者福祉課長","answer":"ただし、特に医療的ケアで、医療ではないので、クリニックは考えておりません。平成３１年度の予算になりますので、今はそのような事業に対しての職員配置も含めて、ご提案をいただきたいのがこちらの趣旨です。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"医師が常勤で配置されているのは、実際に、他区でもいいのですけれども、そういう実例があるのでしょうか。多分、初めてなのではないかと思うのですけれども、もうちょっと詳しくイメージできるようにご説明いただけたらと思います。","respondent":"松山障害者福祉課長","answer":"ただ、この事業を行うに当たって、例えば週２日、心身障害者福祉会館に勤務させるとか、そういう形になろうかと思います。いずれにしろ、応募される法人で、人員配置も含めまして、ご提案をいただくことになっております。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"他区でもいいのですけれども、実際あったら、実例として教えていただきたいのが１つです。生活介護は定員５０名の中で、今までどおり通えなくならないのかという心配もあるのですが、そこら辺はどうか尋ねました。","respondent":"松山障害者福祉課長","answer":"１点目、通所になりますと、なかなかないと私も思っております。今いる方々も含めまして、サービスをよりよくしようというのが今回の趣旨です。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっていくという判断が、どういう需要から、どうしてそういう方向が出てきたのかを教えていただきたい。そういうのも必要になってくるのではないかと思うのですけれども、そこら辺のことについても、どう考えられているのか説明を求めました。","respondent":"松山障害者福祉課長","answer":"先ほど来、ご説明していますように、リハビリのニーズ、医療的ケアは、以前からお声は頂戴しています。３点目の知的障害の方の個別支援プログラムになろうかと思いますけれども、例えば、生産活動を含む個別支援プログラムになろうかと思います。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"生産活動も入れた形での充実をしていただきたいとご要望を受けていますので、ぜひ、よろしくお願いしたいと思います。私は、学識経験者など第三者も入れて検討していただきたいと思うのですけれども、その点についてもお願いします。","respondent":"松山障害者福祉課長","answer":"１点目ですけれども、見込みについてですが、当然ながら、かなり専門性の高いことになろうかと思いますが、全くないということではないと思います。部を越えて部課長には入っていただきながら、また、第三者として学識経験者も入れる予定です。","id":"exchange-049"}]},{"id":"topic-06","title":"品川区立健康センター指定管理者候補者の公募","agenda":"品川区立健康センター指定管理者候補者の公募","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここを利用している方にとって、サービスの低下にならない形での選定をぜひお願いしたいということを要望させていただきたいと思っています。ここにも書かれているので、利用者にとってのサービス向上をしっかりと踏まえた上で、その点だけ説明を求めました。","respondent":"川島健康課長","answer":"できるものについてはすぐ取り組んで、できないとお答えをするというところで、いろいろな取組みをしてきております。さらに区民の方へのよりよいサービスになるように努力していきたいと考えています。","id":"exchange-050"}]},{"id":"topic-07","title":"品川区第二期データヘルス計画・品川区第三期国保基本健診等実施計画","agenda":"品川区第二期データヘルス計画・品川区第三期国保基本健診等実施計画","exchanges":[{"speaker":"石田（ち）副委員長","kind":"意見","question":"先ほど最初のほうで、品川区の目標としては４０％から１％ずつ年々上げていって、平成３５年には４５％と。国の目標値との乖離は、国が現実に合っていないのか、それとも品川区の現状が低過ぎるのか、説明を求めました。","respondent":"三ッ橋国保医療年金課長","answer":"国保基本健診実施率３９.１％、国保保健指導実施率１０.２％となっておりまして、６０％というのは本当に高いと考えています。国の６０％というのはいかがなものかという議論にはなっている状況ではありますが、６０％を目指しながら、４５％としています。","id":"exchange-051"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それを伺いたいのと、６ページのところでは区の図書館とのコラボヘルスというのがあるのですが、そこを伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"６ページからは第二期データヘルス計画の新規事業の取り組みとさせていただいておりまして、例えば７ページ、受診券を発送してまいりますと。保健指導または重症化対策指導につきましては、民間の事業者と取り組みまして、委託をしております。","id":"exchange-052"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この事業の目的及び概要、こうしたところで目標等々を明らかにして、伸ばしていこうという姿勢を見える形にしているということでいいのでしょうか。２）歯科受診勧奨の効果ということで、勧奨対象者数が２,５２５人となって、効果が出たという表になっているのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"６７ページの歯科リスク保持者の分析ですけれども、生活習慣病のリスク者の中で、歯科未受診の方を対象に受診勧奨いたしております。その中で実際に受診をした方が、こちらの表としています。","id":"exchange-053"}]},{"id":"topic-08","title":"メンタルチームサポート事業","agenda":"メンタルチームサポート事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"予算書で見ると、この積算というのはどういうことから１,２９０万円になっているのかということについてもお聞かせください。同行受診、これを３名の精神保健相談員が中心にされていくことになっていくのかということもお聞かせいただきたいのと、あと。","respondent":"榎本荏原保健センター所長","answer":"次に、それから検討の会議を行うということで考えておりまして、精神障害者地域支援連絡会でありますとか個別支援全体会議でありますとか。もちろん同時に退院のときには病院に行ったりということで、複数対応が必要な方々もおりますので…","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新たに３名とはいえ、そこら辺のところをもうちょっと教えていただきたいのと、こういう支援というのはとても大事な支援だと思うのです。求められているとも思うのです。","respondent":"榎本荏原保健センター所長","answer":"精神保健相談員についてですけれども、専門非常勤ということで、非常勤の職で、週４日、３名の方にはお願いしております。１年近くかけて３保健センターで検討いたしまして、また、確保して進めていくということで行っているです。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めて、保健師の増員でこういう施策が本当に過重負担でなく回るような形でということで、保健師の増員も要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"資料の４、４月９日から個別支援を開始とあるのですけれども、もう利用されている方がいるという状況なのでしょうか。それは何人ぐらいいらっしゃるのか、いれば説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"導入検討会議を既にしている方が７件ほどございまして、そのほかに事業開始予定も含めますと、１１件ぐらいが現在動いているところです。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56227,"voices":157}},{"id":"h30-20180514-8","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"建設委員会","time":"午後 １時００分～午後 ３時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を73件整理しています。","topics":[{"id":"topic-01","title":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","agenda":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"警告文のはりつけ台数や撤去台数などをそれぞれ今わかれば、教えてほしいと求めました。それと、その結果、現在の放置状況はかなり減ったと捉えているということでよろしいのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"その後、２月からですと、約１５０件程度です。撤去台数については、２月が１台、それ以降については、撤去はありませんでした。","id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"お話を伺ってみたのですが、３月くらいからもとに戻ってきて、まあまあとまっていたのは確認しましたけれども。７７台あるといった民営のものはそのまま残って、それに今度６１台加わるということなのか、そこら辺をお伺いしたいと思います。","respondent":"古郡交通安全担当課長","answer":"民営の駐輪場については、変更はございません。ホテルについては、前回６１台ということで答弁しましたが、現在のところ５１台を設置予定ということでＪＲのほうから報告を受けております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"何台分を目指しているのかというのをお伺いしたいというのが１つと、放置禁止区域の設定の仕方についてもう少し伺いたいのですが、前回。通常、どのようなプロセスを経て指定していらっしゃるのか、伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"区の全体的なものの考え方というのを検討していきたいということで、現在、調査をしています。放置が多い箇所で、自転車がその場所に収容できることということを考えておりますので、そういった形で実施をしています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"意見を伺うということはあると思うのですけれども、そういったところに改めて声を伺ったのかどうか、伺いたいと思います。これは要望です。","respondent":"古郡交通安全担当課長","answer":"改めて町会に関して何か話をするということはしておりません。ですので、町会の方に来てもらって、撤去作業というのをやっていますので、その中で話を聞いているです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろな話をその中で聞くと思うのですけれども、どんな声を聞かれているのかということを紹介していただきたい。具体的にはどういう声が出ているのか、もっと駐輪場の整備というのが必要なのではないかとか、そういったところはいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"駐輪場が現状少ないということで、そういった声は聞こえております。放置禁止区域に関しては、苦情だとか、区域を広げてほしいということは、聞いてございません。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"今進めていただいているシェアサイクルとの関連もお伺いしたいと思うのですが、結構、シェアサイクルに乗っている方を見かけるようになりました。今後、もし具体的に五反田でのポートがここにできますということがわかっていれば、それを教えていただけますか尋ねました。","respondent":"今井土木管理課長","answer":"ただ、大崎につきましては、今、大崎エリアマネージメントと協議を進めているところですが、五反田では、まだ具体的にはないところです。民間の運営事業者のほうも、今、鋭意探している最中です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"シェアサイクルもしっかり進めていただく中で、全体として放置自転車が減っていくような方向性をぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"今回の条例に関してですけれども、まず、この条例に駅周辺ということが書いてあるのですが、駅周辺の定義、おおよそ駅から何ｍとかいった基準はあるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"駅周辺というのは、駅近くの多くの人や車、自転車等の集まる箇所を周辺としておりますので、駅ごとに周辺の道路の形状や配置が異なるということで、駅から半径何ｍといった数値化はしておりません。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"数値化は難しいと。今回、警告をしていただいたということなのですけれども、その警告をする根拠というのは、条例とか規則とかに基づいてやったものなのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"条例の中に、区域外の放置自転車等に対する措置というのが第１２条にありますので、それを根拠としてやっているところです。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情者の方が今回出されたご要望は、ぎりぎりそこを外していれば大丈夫だろうというお考えなのかもしれないと思われますので、区としては範囲を数十メートル延ばしていこうかといったお考えというのはあるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"区域ですが、新たな駐輪場が今のところできないということですので、やはりそういった区域を広げるというのは難しいと考えているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"先ほどの一番最初のお話に戻ると思うのですけれども、今、駐輪場を増やしていくということも考えていらっしゃるということで、区としては大体何台ぐらいの駐輪場があればいいとお考えなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"委託、計画が完了するまでは、条例の第１２条で引き続きしっかりと警告を進めていっていただきたいと考えております。これは要望になります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"何かお考えがあるなら教えていただきたいということと、平成３０年４月の状況と書いてありますけれども、同じところに置いてありますよね。わざわざ西口というのですか、ここまでは来ないわけですから、それも含めてあわせてお聞かせほしいと求めました。","respondent":"古郡交通安全担当課長","answer":"なかなかすぐ撤去というのが、やはり１週間置かなければいけないというところで、撤去は難しい状況です。うちのほうでいろいろな方へお願いベースでお願いをしています。","id":"exchange-013"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"とは言いながらも、お店のもの、従業員だと知っているものをまた撤去するのもいかがなものかという思いもします。それが品川区にもプラスにつながってくるわけですから、作業を実行していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大沢委員","kind":"意見","question":"陳情者の方なのですけれども、東五反田一丁目の全域ということですが、これ、町会の中の総意というか、町会の中の声があって、こういう話があって、この方が取りまとめたとか、それとも、この方個人の感覚に基づいた陳情なのか、そこら辺の説明をお願いしたいと思いますとの意見を述べました。","respondent":"古郡交通安全担当課長","answer":"町会の方から区のほうにお願いというか、来ているという状況ではございませんで、個人の方が陳情されているという形です。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"黄色い線の部分、東五反田一丁目ですけれども、その中の緑色の部分、意味があって、放置自転車禁止区域に指定されたと思う。緑色でない部分は必要と認めないから、こういうふうになったわけですけれども、最初の取り決めのときの事情というか、状況を説明を求めました。","respondent":"古郡交通安全担当課長","answer":"やはり道路に２０台、３０台とか、そういった形で指定していきたいと考えています。","id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"今、緑色の禁止エリア以外というところは、そういう状況が当初見られなかったということで考えていいわけですね。必要性がなかったとの意見を述べました。","respondent":"古郡交通安全担当課長","answer":"当時についてはそのとおりです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"陳情者の思いは、五反田駅近くで住宅にも及ぶ放置自転車を解消してほしいというものですので、それは大事な課題だと。住民合意の形成においてまだ課題がありますので、よって、趣旨採択を主張したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"結論を出すで、趣旨採択でお願いします。先ほどご質問させていただいたように、しっかりやってほしいと求めましたので、趣旨採択で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"結果は趣旨採択でお願いしたいのですが、これからの放置自転車対策を考えると、いろいろな視点を含めた形でやっていかなくてはいけないのだろうと。土地があるなら、駐輪場を分析をしながらつくっていくという形になるでしょうし、ここは地域の方々と一緒に話し合って進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]},{"id":"topic-02","title":"平成３０年６月区民住宅（空き室）入居予定者登録募集","agenda":"平成３０年６月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"１点だけなのですけれども、広報しながわ６月１１日号に掲載されて、配布期間が１週間ということなので、もう少し早く広報をできないのでしょうか。お伺いしたいと思います。","respondent":"森住宅課長","answer":"広報への掲載ですけれども、６月１１日から募集の内容が明らかになるということですので、その日付に合わせて広報を発出していくです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"配布期間が短いのかなという気がするのですけれども、もう少し申込みの受付期限に近い形で延ばすことは必要だと思うのですが、できないのか尋ねました。","respondent":"森住宅課長","answer":"募集期間についてですけれども、都営、区営、区民につきましても、大体１週間から１０日程度ということで案内をしておるところです。これにつきましては、広報等をしっかりやりまして、募集期間内に皆さんにお知らせするということで進めていきたいと考えています。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"空いていれば入れますよね。その兼ね合いはどうなっていますか尋ねました。","respondent":"森住宅課長","answer":"ただ、このうち３戸は被災者の受け入れ用として確保しております。それでも空きが出た場合は、随時募集という形で、随時受け付けているです。","id":"exchange-023"},{"speaker":"西本委員","kind":"意見","question":"ということは、たしか１００％に近い状況で入っているところもあれば、かなり入居率が低いというところもあると思うのです。区民住宅が契約が切れていて、オーナーに返されているという部分があったりするのですけれども、そこの動向はどうなっていますかとの意見を述べました。","respondent":"森住宅課長","answer":"区民住宅、特に建設型につきましては、空き室が一定程度出ているところではあります。３２戸、継続して住まわれるかどうか、その辺の状況も聞いているところです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"これは１００％入っていただければ、財政的にどのぐらいのマイナス要因として出てくるのかは、見当がついていますでしょうか。補助しなければいけないし、あとは遊ばせてしまっているというところもあると思うので、その辺の動向はどうなのか尋ねました。","respondent":"森住宅課長","answer":"アイルサイドテラスが３１％、ロビン成田は１００％入っているのですけれども、それぞれ区の持ち出しという形にはなっていると考えています。ハード面、それぞれ影響があるのかどうか、その辺を検討していきたいと考えております。","id":"exchange-025"}]},{"id":"topic-03","title":"西品川２・３丁目地区における密集住宅市街地整備促進事業の開始","agenda":"西品川２・３丁目地区における密集住宅市街地整備促進事業の開始","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"防災生活道路等の整備についてお伺いしたいのですけれども、数ある中でなぜこの青い線のルートになったのか、お伺いしたいと思います。","respondent":"高梨木密整備推進課長","answer":"その両側で消防活動を行う、ホースを出したりするといったような幅員等を鑑みまして、６ｍの幅員が必要ということで設定をしています。説明の中でも一部触れましたが、まちづくり検討会の中で検討がなされまして…","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"この地域でなぜこの道路がないといけないのかというのは、地域性に即して伺いたいので、そこら辺をもう一度伺いたいと思います。何世帯ぐらいあるというのか、そこら辺もつかんでいらっしゃるのか、伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"それにより継続してその場所に住めなくなった方への住替えの支援、住替えの支援等は、十分に行っていく予定です。今年度から新たにまた委託を使って、そういった検討を行っていく中で判断していくものと考えておりまして、把握してございません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりそこら辺、まずはしっかり説明していただかないとという思いがあるので聞いたのですけれども、そこら辺もどうですか。そこら辺は何か必要なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"まちづくり検討会の中で少々議論を進める中で、１つの理由でここというような形で決まったわけではございません。先ほどのご説明で、終盤ご説明いたしましたとおり、強制力はないといったところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"ですから、あまり６ｍあったほうが安全だよねということで進めるべきではないし、やるべきではないと私は思います。そういう２つの問題が心配されるのですけれども、共同建替えのこの２つの心配については、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"資金面等も含めて、お話し合いが積極的に行われるよう区として支援をしていくといったところで、方針に記載させていただいているところです。高層建築につきましては、また、ここでは再開発のような共同化といったところを念頭に置いて方針を立てているわけではございません。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、町会の皆さんがここを広場にしてほしいという要望があった際というのは、こういうのを整備していく必要があると私は思うのです。これに関しては、今回もこの事業を契機に積極的に行っていっていただきたいのですが、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"最後に、広場整備につきましては、特にこの地区につきましては、１人当たりの公園面積が非常に狭いということで、鋭意広場を設置していくと。引き続き防災広場、まだまだ足りないところがありますので、鋭意適地の取得に向けて取り組んでいく所存です。","id":"exchange-030"},{"speaker":"西本委員","kind":"確認","question":"再度確認という形で、どういう意見がありましたでしょうか。それから、これは１００％聞かれているのか、何割の方々のご意見をお聞きになっているのか、まずそこをお聞きします。","respondent":"高梨木密整備推進課長","answer":"建て替えたばかりなので、今は賛成できないという反対の方等々、ほぼ同数いらっしゃいます。回答があったのは、全部で１４％ほどの方からご回答いただいております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"１００％ではないにしろ、個別に丁寧にされていると思いました。先ほどお願いベースとおっしゃっていたので、建替えの際に拡幅という形でお願いするというもの、そういう理解でよろしいのか尋ねました。","respondent":"高梨木密整備推進課長","answer":"建替えの際に、しっかり幅員１０ｍを確保するラインまで下がらないと、再建築できないといったルールづくりが既になされている部分になっております。西品川２・３丁目地区は、地元の方々と継続してまちづくりについては話し合いをしてまいりますので…","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"１つは、ある程度お願いしたいところというのが、こういう色で示されているのだと思うのです。そういった場合の、それぞれどういうふうに説明をして、交渉していくのか尋ねました。","respondent":"高梨木密整備推進課長","answer":"建替え重点支援エリアにつきましては、赤色であったり、灰色であったりで示している資料があります。まとまっての共同化はいかがでしょうか、単独ではなしに、周辺の方々と一緒にまちづくりについて進めていきたいと。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"賛否、先ほど以上に反対者と賛成者と、いろいろな意見が出てくるかなということを非常に危惧します。丁寧に進めていただきたいというのもあるし、地域の住民同士の間での亀裂というか、そこは十分に気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"いながわ副委員長","kind":"確認","question":"確認というか、お伺いしたいことがあるのですけれども、東京都に了承をもらいましたという話があるではないですか。未接道というのですか、３丁目エリアですから、助成措置がとられるのかどうなのかということ。","respondent":"高梨木密整備推進課長","answer":"不燃化特区との関係なのですが、本日ご説明させていただきましたのは、不燃化特区とは別です。この２・３丁目につきましても、密集事業と特区の事業と両方が重なって、密集事業のほうが今回開始になるといったような位置づけです。","id":"exchange-035"}]},{"id":"topic-04","title":"品川区耐震改修促進計画の改定","agenda":"品川区耐震改修促進計画の改定","exchanges":[{"speaker":"横山委員","kind":"質問","question":"この数年の間でほかにどのような動きがあったのか、教えてください。新耐震木造住宅のうち、どういったものが危険度が高いというか、チェックしなければならないのかということを具体的に教えていただけたらと思います。","respondent":"長尾建築課長","answer":"１点目の、本編の３１ページの説明文にも記載しておりますが、マンション敷地売却制度という制度も導入されております。写真を使って説明されているところとしましては、あとは、そういったところをご紹介しています。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"都と国に合わせて戸数ベースで算定という話ですが、その変わった理由というのですか、なぜそのように変わったのでしょうかというのをお伺いします。内訳というのですかね、計画本冊の中でそういうのが出ているところがあれば、お示しほしいと求めました。","respondent":"長尾建築課長","answer":"住宅・建築物耐震化支援事業の実施状況に関して、平成１６年度の事業開始時からの実績、支援事業の実績ベースの件数が記載されております。建替えにつきましては、その下に「２２９」と書いておりますので、こちらが累積の件数となっております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"確認","question":"それに合わせたということでよろしいのか、確認させてください。お伺いしたいと思います。","respondent":"長尾建築課長","answer":"今回、戸数ベースでの算定方法に区の耐震改修促進計画上の耐震化率も合わせることとしております。やはり耐震化支援事業の効果もあるのですが、そういった、区が支援しているさまざまな支援策を区民の方に利用していただいて。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"「総合的に」と言ってしまうと、さらに中身をしっかり分析していただきたいという思いがありますので、今後よろしくお願いしたいということです。何でこんなに耐震化率がアップしたのかという、その分析もぜひ聞かせてほしいと求めましたが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"先ほどご覧いただいた計画の本編の５２ページの表の中で、マンションに関しては、改修実績として、累積で６件となっております。これまでの耐震化の支援に加えて、改修等に関しても助成を拡充することで予定をしておりますので、促進を図っていきたいと考えております。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"マンションは改修は６棟ということですけれども、建替えというのは多分ゼロだと思うのですけれども、それを確認したいのです。そこら辺というのは、今回の計画でどのように考えていっているのか、伺いたいと思います。","respondent":"長尾建築課長","answer":"共同住宅の排水管、設備に関する耐震化の話ですけれども、こちらの計画の中に具体的に排水管に関しての記載というのはございません。主に耐震改修の話の中では、建築物の構造の部分がメーンになってきますので、そこを中心にした対策となっております。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際、新しくできるマンションというのは、基本的にそこでとどまってくださいというのが区の方針ではないですか。そういうことだと思うので、ぜひ計画に具体的な対策をとっていただきたいのですが、その辺はいかがか尋ねました。","respondent":"長尾建築課長","answer":"マンションに限らず、全ての建築物に関して建物のインフラとしては共通する課題だと思いますので、国や都の取組みなども研究しながら、今後、検討してまいりたいと思います。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"資料１と２がついておりますが、改定の趣旨はわかりました。いろいろ変わっているということもあって、資料１と２の使い方、これはどういう目的でこういう資料になっているのかをお聞きしたいのです。","respondent":"長尾建築課長","answer":"概要版には載せ切れていない施策もありますので、そういったところを詳細に説明する際は、本編というところでの使い分けになるかと考えます。一般の区民の方へのご説明としては、まずは概要版で導入編といいますか、概要を説明するということを想定しております。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"だから、それを行政が区民の皆さんに説明するのはすごく難しいではないですか。そういう工夫があったら、さらに活用していただけるのではないかと思ったのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"概要を載せて、もっと簡単にしたものも活用しながら、個別にご相談に応じているところです。助成内容が変わったことに対しては説明をしながら、より支援事業を活用して耐震化を図っていくということでご協力いただいてきておりますので。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"不動産業の方々に対して、いろいろこういうのが今回できましたという説明会とか、あとはもっと要望です。もう少し要望を聞いていただいて、協力をいただきたいという思いもぜひ、ご検討を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"額も出しているところだと思うのですが、そういった具体的な記述がないですので、何でなのかという感じ。そこら辺、見当たらないのですが、いかがか尋ねました。","respondent":"長尾建築課長","answer":"木造住宅の耐震化支援ということで、一般の診断支援、耐震補強設計支援というふうにありますが。状況に適した支援といいますか、というところもつなげていくところは考えておりますので、全てを記載するというふうにはしておりません。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"そこら辺、ぜひ工夫できる余地があれば、工夫していただいたほうがいいかと思います。意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]},{"id":"topic-05","title":"しながわＥＣＯフェスティバル２０１８の開催","agenda":"しながわＥＣＯフェスティバル２０１８の開催","exchanges":[{"speaker":"横山委員","kind":"質問","question":"２月の環境講演会と同様の形で行われるというお話だったのですけれども、前回の２月のときには、集まっている状況があったのでしょうか。今回新たに追加になった理由とか、そういったものが何かありましたら、説明を求めました。","respondent":"小林環境課長","answer":"今年２月に行われました環境講演会でのフードドライブの実施の結果ですが、約７２kgの食品を提供いただいたところです。特に大きな変更はございません。","id":"exchange-047"},{"speaker":"西本委員","kind":"質問","question":"つながっているわけではなくて、真ん中に多目的広場があるものですから、結構移動距離が長くなってしまうというのがあると思うのです。そうなるともったいないし、残念な結果になってしまうので、何か工夫はありますか尋ねました。","respondent":"小林環境課長","answer":"今年度から新たにヘリポート部分のところでも実施しますが、今回、変更となったことをしっかりお示しするというところがまず１点です。そういった方をうまく活用しながら、トラブル、あるいは混乱がないような誘導のほうを進めてまいりたいと考えております。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、区役所側のところの、多分、そこが総合受付になるのですかね。そこが一番誘導しやすい部分なのかと思いますので、工夫を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"当然ながら、案内板のところにも、フードドライブが少しわかるような形で案内をぜひお願いしたいと思います。２回目を行っていきますけれども、フードドライブの実施というところの考え方をお伺いしたいと思うのですが、いかがか尋ねました。","respondent":"小林環境課長","answer":"その実施状況等々をしっかり見きわめた上で進めてまいりたいと考えております。来年２月に予定していますが、今年の２回の実績を経験した上で、取組みをしっかりと研究したいと考えているところです。","id":"exchange-050"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"ブースの４８から７０のもったいないグループというのですか、テントをつくって、そのままそこで飲食を販売したりというのがあると思うのです。そういうのも踏まえて今回は運営していただきたいという思いがありますけれども、どうお考えか尋ねました。","respondent":"小林環境課長","answer":"多言語対応のタブレット等を用意して、外国人の方がお越しになっても、不自由ないような対応は基本的にしていきたいと考えているところです。その辺はしっかり対応したいと考えています。","id":"exchange-051"},{"speaker":"いながわ副委員長","kind":"意見","question":"６番のところに、誰といったらいいのか、外国の人が増加しているのか。この辺をどう捉えているのかだけ、一言でいいのでとの意見を述べました。","respondent":"小林環境課長","answer":"来られた方が非常に増えてきているというところでございまして、１０年前と比較しますと、昨年度は約３万１,５００人の方が集まってあります。１０年前と比較しますと、約１万人超増えているところですので、今回拡充しています。","id":"exchange-052"},{"speaker":"筒井委員","kind":"質問","question":"２点ほどありまして、電気自動車乗車体験と燃料電池車乗車体験は、具体的にどういった形で行われるのか。２点目として、人権尊重都市としてのかかわり、今回のブースに特に人権尊重都市２５周年にかかわるような催しとかはあるのか尋ねました。","respondent":"小林環境課長","answer":"台数につきましては、昨年同様、それぞれ１台ずつです。２５周年を記念するというところで、そういったところで、「記念」ということで掲載しています。","id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"簡単に質問します。以前にも伺いましたけれども、そのようなものに対する危機管理体制というのを区のほうでどのように持っているのか、説明を求めました。","respondent":"小林環境課長","answer":"前回の環境講演会でも実施させていただきましたが、まずは受け付ける場面で、それぞれの品物を職員がまずは検品いたします。フードバンクにおいても最終的にはもう一度検品して、最終的にお使いになるか、ならないかというところを判断すると聞いているところです。","id":"exchange-054"}]},{"id":"topic-06","title":"都市計画道路補助１６３号線整備に伴う大井町線橋梁架替工事の今後の予定","agenda":"都市計画道路補助１６３号線整備に伴う大井町線橋梁架替工事の今後の予定","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"１点だけ確認させてください。これは図の現況と平成３０年６月から平成３２年３月のものと、２通りあるように見えているのですけれども、新しくなるのか尋ねました。","respondent":"多並道路課長","answer":"Ａ３の見開きのほうの資料に描かせていただいているものは、今現在のものに重ねて事業範囲を描かせていただいていますので、今の状況ということです。そこの詳細は、また最終的には工事を進める段階で協議していくということで、今のところ聞いているところです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"現状どう品川区としては捉えているかということと、それが今回のガード下の工事で解消される見通しがあるのかどうか、伺いたいと思います。","respondent":"多並道路課長","answer":"赤信号になっても、それが少なくとも今は当時の調査で最大１８０ｍあるということで、今のようなことが起こっているのだろうと思っています。補助２６号線と１６３号線の交差点の信号の、そういうことがないように都と警視庁と協議しながら進めていくというのが、現段階の考えで…","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"お伺いしたいのは、１つはスケジュールの点で、事業認可がいつぐらいになるのかというのを伺いたい。今回の施工区間に関してはもう行われたものなのか、それは施工区間ごとに行われるものなのか、そこら辺もお伺いいたします。","respondent":"多並道路課長","answer":"今予定しておりますのは、ここの区間約１００ｍの事業認可を取得する予定を今、ＪＲと協議を進めているところです。認可と説明会の考え方ですけれども、施工区間ごとで認可となりますから、その区間ごとに説明会を行っていくというものです。","id":"exchange-057"},{"speaker":"安藤委員","kind":"確認","question":"だから進むのですかという確認と、１００ｍというのは、どうなのですかね。最後に１６３号線、６５ｍから残りの部分ですけれども、お伺いしたいと思います。","respondent":"多並道路課長","answer":"その後、認可をとった後については、事業と工事の両方の説明ということで、平成２７年７月に行っております。近隣の方を対象として、工事のスケジュールについて説明をする場をまた設けておりまして、これが全部で４回ほど行ったところです。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"１００ｍの部分のところに関しては、そういった立ち退き対象になるようなところというのは発生するのでしょうか。それだけわかればお伺いしたいと思います。","respondent":"多並道路課長","answer":"今の１００ｍの場所につきましても、おおむね１００ｍと言いましたけれども、現時点ではそこまでは固まっておりません。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"ガード下はわかるのですけれども、きれいにした崖の部分がありますよね。あそこに関しては、立ち退きは発生しないということでよろしいのか尋ねました。","respondent":"多並道路課長","answer":"今、委員ご指摘のとおり、あそこの擁壁の部分については、事業範囲に入らないことで、今のところ考えております。","id":"exchange-060"},{"speaker":"新妻委員","kind":"質問・要望","question":"当然ながら歩道に車椅子の方も余裕を持って通ることが可能だということを１点、確認させていただきたいのと、完成した後の自転車の動線ですかね。自転車に対しての何か対策があるのかということを確認させてください。","respondent":"多並道路課長","answer":"このような形を予定していますので、十分車椅子の方はご利用いただけるようなスペースは、今度はかなり設けられます。現時点では、まだ東京都から示されていないという状況です。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"幅員１６ｍと書いてあるところ、左上の図なのですけれども、これ、品川区役所の階段のところにかかっているのですが、この道は将来、先ほど言われた湘南新宿ラインがかかっている道とつながるといった理解でよろしいのか尋ねました。","respondent":"多並道路課長","answer":"６５ｍ、今かかっている、赤色の部分からずっと真っ直ぐ左のほうに行って、湘南新宿ラインがあるほうまで１６ｍの幅員になるような形で確保されるということにはなっています。","id":"exchange-062"},{"speaker":"筒井委員","kind":"質問","question":"そうしたら、区役所の階段部分のところも将来的には削るようにするということでよろしいのか尋ねました。","respondent":"多並道路課長","answer":"大井町線の下と今度のＪＲの高架下、ここの整備を先行させようということで、まずはこちらを整備していこうと考えています。それ以降については、まだその後ということで、またしかるべきタイミングで行っていきたいと考えています。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"もう一点なのですけれども、別紙のほうで、中を開いていただいて、断面図のところなのですけれども、現況と完成後を比べてみますと、ピンク色で支柱というのですか、かなり地中深く埋め込まれているのですけれども、これは耐震というか、そういった関係で強化したという理解でよろしいのか尋ねました。","respondent":"多並道路課長","answer":"耐震性はもちろんですけれども、どちらかというと、橋台を兼ねるというのが一番大きな理由です。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"概要のところで、水色の部分が２カ所あって、１つは、「品川区総合庁舎」という看板があるところなのですけれども、本来、ここは道路になるべきところにあれが置いてあったのか尋ねました。","respondent":"多並道路課長","answer":"現時点では、おっしゃるとおりです。道路になるところにあったということです。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"それはどのような歴史の流れがあって、そういう形になったのか、説明を求めました。","respondent":"多並道路課長","answer":"平成９年に都市計画変更ということで、平成９年のときにかかる計画になってしまったので、このような形になってしまったと。そういうところです。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、都道ですけれども、水色の横長の階段部分なのですが、ここは計画に入っていないですけれども、本来であれば、使っていいような状態なのか尋ねました。","respondent":"多並道路課長","answer":"今の階段の下の水色の部分につきましては……。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"水色ではなくて、今回の工事範囲にも入っていない、６５ｍ以外の階段部分の下、どこら辺まで水色の概念というか、範囲に含まれるのか尋ねました。","respondent":"多並道路課長","answer":"その手前までの、石垣があって、桜の木があるあたりです。あそこが今回の対象とさせていただいて、引っ込めするという判断です。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"１つだけお伺いします。仮歩行者通路というのができるのですけれども、完成した後、これがなくなるという理解でよろしいのか尋ねました。","respondent":"多並道路課長","answer":"完成後はなくなる予定ですけれども、ここについては、東急の土地ですので、また高架下の部分については東急がいろいろ考えられるかと思います。","id":"exchange-069"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"４０ｃｍ高くなっているということの理由をお知らせいただきたいのと、その別紙の裏というのですか、３２ｍ。非常に不自然な感じになるのではないかと思うので、その辺はどうお考えかというのを、簡潔でいいので。","respondent":"多並道路課長","answer":"４.５ｍと書いてあるのですけれども、最終的に今現時点で４.７ｍ確保するということで、予定しています。まず、今のご指摘があった花壇側のほうのところまでは今回整備する予定はないのですけれども、図面でいうと右のほうに曲げる形で今考えています。","id":"exchange-070"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"これは要望なので、お伝えします。今のは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ですので、ぜひしっかり報告を委員会でしていただきたいと要望するのですが、いかがでしょうか。いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"先日、５月１０日、リニア中央新幹線の大深度地下使用に係る説明会が開催されました。中身につきまして、必要であるということであれば、委員会等でまた報告をさせていただければと思います。","id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"議会としてもどういう計画なのかというのはきちんと把握する必要があると思いますので、私はぜひ報告すべき内容だと考えていますので、ご検討ほしいと求めました。","respondent":"たけうち委員長","answer":"報告に加えるか加えないかは、一応我々正副で決定します。出てきたときにどうするかというのは、新たな体制の中で検討していただくことだと思いますけれども、ご意見として承っておきます。","id":"exchange-073"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":50167,"voices":183}},{"id":"h30-20180514-9","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"文教委員会","time":"午後 １時００分～午後 ３時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度新入学学校別増減要因一覧","agenda":"平成３０年度新入学学校別増減要因一覧","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最初に、今回の増減の傾向といいますか、どういった形で増減しているのかというところを教えてほしいと求めました。","respondent":"篠田学務課長","answer":"それともう１つは、現在、学校の改築が大分進んできておりまして、その改築による影響も若干見られるように感じております。浜川小学校など、これから改築に向かうような学校については、若干減るような傾向が出てきているというようなことが見てとれるところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そこで、選択制と指定校変更の役割の違いを伺いたいと思います。指定校変更している方の理由についても、あわせて伺いたいと思います。","respondent":"篠田学務課長","answer":"学校選択制と指定校変更の役割ですけれども、学校選択制はそもそも１年生、それぞれの学校の特徴等を踏まえて学校を選べるというものです。必ずしも一概には言えないのですけれども、最終的には教育委員会が認めたものを指定校変更として認めるです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"チャンスが２回あるというわけではないということは私もわかっているつもりですけれども、地域の教育力を弱めていくというところで廃止にすべきだと言ってきましたけれども、そういったことはできないのか伺いたいと思います。","respondent":"篠田学務課長","answer":"お子さん方、あるいは保護者の方に、きちんとその学校の特徴を把握していただいて選択していただくという教育的な観点から行っている制度です。これに対して指定校変更というのは…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり地域からもつながりが弱まっているという声も出ているわけですから、そういったところはしっかりと受けとめていっていただきたいと思うのです。この間、そういったところでいきますと、改めて教育的観点でやっているというところをもう少し詳しくご説明ほしいと求めました。","respondent":"篠田学務課長","answer":"これまでの教育的な効果を踏襲しつつ、さらに新しいものをつくっていくということで、隣接校からの選択といった形で提言がされています。積極的に学校の取り組みを外に対してアピールしていく…","id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"やはり選択制は地域とのつながりも壊しますので、学校間の格差も固定化されてしまいます。ちょっと言葉は不適切かもしれませんけれども、やはり選択制はやめていくべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"しかし、このように何校にもわたって３０％を大きく超える方が選ばないという状況があるということに対して、私は非常に心配するのです。そういう点で教育委員会はどう思っているのか、まず、その２点を伺いたいと思います。","respondent":"篠田学務課長","answer":"タブレットを全員に配付するなど学校のＩＣＴに係る支援ですとか、あるいは教員の加配をするとか、さまざまな形で支援をしております。今後も引き続きそういった形の取り組みは続けてまいりますので、学校自体をなくしていくということを考えているものではございません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"やっぱりそれをどういうふうに見るのかというところを伺っておかないといけないと思います。いかがか尋ねました。","respondent":"篠田学務課長","answer":"学校に対する支援や、さまざまな形で考えられるもの、これから慎重に検討を進めていくところではありますけれども。したがいまして、あくまで入学希望が少なくなってきてしまっている学校に対してどういった支援をしていけるのかというのは。","id":"exchange-007"},{"speaker":"南委員","kind":"意見","question":"やっぱり親の責任、地域の責任にするのではなくて、教育委員会としての責任をもっときちんと出すべきです。どういうふうに支援をしていくとか言っているけれども、あえてそういうことを言わせていただくと、中延小学校についてはどういうふうに見ていますかとの意見を述べました。","respondent":"篠田学務課長","answer":"一昨年度は１３名でございました。昨年度は７名多かったですので、ご家庭がありますから、そういった意味で結果としてこういった形が起きているのかと考えているところです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"事情を抱えている家庭が中延小学校周辺で、よその地域より多いということは考えられないのではないでしょうか。そのやる姿勢があるのかどうか、そこを含めてこの質問は終わりにしたいと思います。","respondent":"篠田学務課長","answer":"一般論としまして、小規模になってしまうと、小規模校は一般的には選択がされづらくなってしまうという傾向があるのは率直なところだと思います。そういった状況から脱却するために、教育委員会としましても引き続き最大限…","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ私もしっかりと受けとめていきますので、よろしくお願いしたいと思いますけれども、そういう考え方だけはとらないでほしいと求めました。その点、答弁を聞きたいと思います。","respondent":"篠田学務課長","answer":"教育委員会の基本的な考え方として、子どもの数が少なくなっていくので、学校をなくす方向で整備をしていくということを前提とした取り組みは今後もしていく予定はございません。","id":"exchange-010"},{"speaker":"渡部委員","kind":"意見","question":"これから１０年後、２０年後において、品川区の学校はこういうふうに必要になっていくのだということまで示していくべきではないかと思う。だったら、いわゆる行政施設はどういうふうにあるべきかということを考えていかなければならないし、その辺の考え方を説明を求めました。","respondent":"篠田学務課長","answer":"当面１０年、あるいはそれ以上にわたって増えていくというふうに認識していますので、そういった中では。この先、教育委員会の考え方としましては、就学人口等の推移も見ながらバランスのよい配置を考えていく必要があるだろうと考えているところです。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"これからの建物はまた６０年とかもつわけですから、果たして６０年後に必要なのかと言ったら、それはわからないですね。私たちも会派として要望をずっと入れていますけれども、さまざまその辺は考えて、これからも進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"平成３１年度品川区立学校教育職員採用候補者選考日程","agenda":"平成３１年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"逆に、東京都職員に受験し合格してお辞めになってしまった方などがいらっしゃったら教えてください。なぜお尋ねしたかというと、学校の運営に一生懸命意欲を持ってなされるような立場になられる方がどれぐらいいらっしゃるか知りたいからです。","respondent":"熊谷指導課長","answer":"今年度は２７名ということで予定しておりましたが、１名、平成２５年採用の教員が長崎に帰ってしまいました。ですので、今年度の採用は３名となっております。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"いろいろな事情があって主幹や主任を受験される方もいらっしゃると思いますけれども、さっきもお話ししたように、学校の中のリーダーになっていこうと思われる方が多いように伺っているのですが、そういうところもお話ししていただければと思いました。","respondent":"熊谷指導課長","answer":"やはり現段階で２６名ということで、都の主幹教諭選考、主任教諭選考よりもかなり厳しくしています。育成をしながら次の主幹教諭、主任教諭、また副校長を育てていきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどもお話ししたように、学校の中のリーダーになっていっていただける先生方と思うので、引き続き、育成などについて、教育委員会のほうでもバックアップしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-03","title":"品川区立公共図書館・学校図書館システム再構築による休館","agenda":"品川区立公共図書館・学校図書館システム再構築による休館","exchanges":[{"speaker":"南委員","kind":"質問","question":"システムを変更する目的というか、使い勝手をよくするだとか、そういうところがよくわからなかったので、何のためのシステム再構築なのかを説明を求めました。","respondent":"横山品川図書館長","answer":"平成２５年度から５年間のリース期間を終え、システムパッケージがリース期間満了となりました。なので、新しい技術を取り入れた図書館システムに対応するための準備も兼ねまして、利用者の利便性が図られるよう構築を進めたいと考えています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"利便性が高くなるというふうに期待をして待っていればいいということか尋ねました。","respondent":"横山品川図書館長","answer":"そのようなシステムになるように調整をしてまいります。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"なかなか周知が行き届かないということもあるかと思いますので、そういったところをどうやってやっていかれるのか伺いたいと思います。というのは、返却ポストとか、そういったところは利用できるのか、そこも伺いたいと思います。","respondent":"横山品川図書館長","answer":"町会の集まり等でも、できる限りご案内を差し上げる予定です。返却ポストにつきましては、機器とはまた別ですので、こちらのほうで返却をお受けする予定です。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の方が間違えて来ないようにしっかりと周知をしてほしいと求めました。先ほども少しご説明があったのですが、利用者の目線ではどのような変更が予想されているのか、また検討されているのかを伺いたいと思います。","respondent":"横山品川図書館長","answer":"検索しても本の書名と作者しかわからなかったのが、表紙の絵が出てくるだとか、少しわかりやすいような表示にできると予定しています。こちらも確定しましたら、またご案内できればと思ってあります。","id":"exchange-019"}]},{"id":"topic-04","title":"平成３０年４月入園申込状況等","agenda":"平成３０年４月入園申込状況等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"７０６名ということで、なぜ減ったのか、理由を伺いたいと思います。不承諾数が今、７０６人、待機児童数が１９人ということで、この差し引き６８７人の方がどこへ行ったのか、この内訳を教えてほしいと求めました。","respondent":"大澤保育支援課長","answer":"最終的には区外保育園への申込者や、書類不備や要件を満たさなかった方を除いて最終的な数値が出しますので、そこで誤差が生まれたものです。育児休業中の方のうち一定期間の育休を延長する方が４６名、合計で６８７名となり…","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"繰り上げて入園したというのはどういったことなのか、ちょっとよくわからなかったので、そこをもう少しご説明ほしいと求めました。認証等の方が２６８名というお話でしたけれども、企業型に行った方、認可外に行った方がどれだけいらっしゃったのかお伺いします。","respondent":"大澤保育支援課長","answer":"入園が決まった方の割合から考えますと、１割以上が辞退ということで、そういう中で数としてかなり大きな動きが出てくるです。幼稚園等が４名、企業主導型の利用を確認できた方が４名、保育料の助成のある認可外を利用されることが確認できた方が３９名となっております。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"待機児童数が少なくなったことについて区の分析を伺いたいと思います。昨年と今年の違いは何だと考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"もう１つは、地区ごとに２０園前後になったということで、バランスよく開設できたことも大きいかと考えています。国の定義の変更につきましては、今回、待機児童から除いたというところが変更点です。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"今回、区の計算上は０歳児の待機児童がゼロになる見込みだったと思うのですけれども、ゼロにならなかった原因を伺いたいと思います。五反田地区のみという結果になっていますけれども、この２つの地区で待機児童が発生した要因をどのように考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"この０歳児人口増加そのものが影響したというふうに考えております。お考えもありますので、枠を用意したということでは、路頭に迷うような状況ではなくなったということはいえるかと考えています。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"子どもたちは４月に生まれるわけではなくて、１年間の中で生まれていきますから、いかがでしょうか。この１９名の待機児童となった方々が、その後どうされているのか、どういった対策をとってきたのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"今年度につきましても、もし近くの認可に入れなければ、近くの認証を選ぶという方も一定数いるというふうに考えております。認可外施設に預けている方が１名、お知り合いにお預けになっている方が１名、職場にご同伴されている方が２名というような状況です。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"今回、４月時点で１９名ということでゼロにできませんでしたということで終わらせずに、手立てをどう考えていらっしゃるのか伺いたいと思います。やはり待機児ゼロを目指していくということであれば、入れなかった方々への支援も必要だと思いますので、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"認証保育所や、地域によっては認可保育園に空きがありますので、そのような情報が漏れなく伝わるように周知を図っていきたいと考えています。","id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ですから、難しいところもあると思うのですけれども、その辺が待機児を発生させない基本的な考え方になっていくのではないかと思っています。今年の４月のこの数字、それから、これからの待機児の需要予測、その辺についてどういうふうに考えているのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"予測としては４％前後増加するのではないかという見込みを立てていたのですけれども、実際のところは２.６％の増ということで。新しい乳幼児人口の推計に基づいて計画を立てておりますので、これに沿ってやっていくことが大切なことではないかというふうに考えております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"それはそれとして伺いましたけれども、実際は２.６％だったから少なくなっているとは言っても、人数は増えているわけですね。８０人ぐらい、定数を大きく超えているところが随分あるのではないかと思っているので、その辺で弾力化で吸収できたという認識でいいのか尋ねました。","respondent":"大澤保育支援課長","answer":"０歳児につきましては、７９８人というのは、認証も含めて品川区子ども・子育て支援計画を立てることになっておりますので。弾力化については、区立保育園等でやっておりますので、その部分での受入枠ももちろん数の中にはカウントしております。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"千五、来年度は保育園のところでは９０６人という計画なのですが、そして保育園の園数としては１２園ぐらいつくるという予定なのでしょうか。その数字も改めて確認させていただきたいのですけれども、果たして大丈夫なのかというふうなところを改めて確認をしておきたいと思っています。","respondent":"大澤保育支援課長","answer":"私どもも３３５戸の予定と聞いておりまして、昨年度の品川区子ども・子育て計画の改訂時にその部分を組み込んだ人数で計画を立てております。平成３１年４月につきましては、委員おっしゃるとおり１２園の開設ということで、今、進めております。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、その辺について伺いたいのですが、とりわけ心配なところは、五反田保育園の３歳未満の定数が４２人に対して５６人入っています。こういう保育園は、保育士の配置はもちろん基準どおりになっているのだろうかと思うのですけれども、その辺について教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"こちらに関しましては、国が定める部屋の広さと保育士の担当としての人数は間違いなく配置をしています。できる限り定員の弾力化を進めるようにということもありますので、私どもとしては、安全を確認してそのように対応しています。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"例えば、０歳、１歳、２歳、この３クラス、この２つの園でいいですから、有資格者が何人、正規なのかどうか、その辺の資格も含めて何人配置しているのかを具体的に数字で教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"手元にあるのは総人数の数字しかございませんが、五反田保育園に関しましては、全部で１９名の保育士を配置しています。個別の詳しい内容は、申しわけありませんけれども、担任表を持ってこないとわからないので、各園そのぐらいの人数になっているところです。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"２歳児は６対１ですから、その辺を具体的に教えていただかないと、具体的な数字を教えてください。２割、３割を超えている保育園２つに限って聞き、教えていただきたい。","respondent":"佐藤保育課長","answer":"０歳に関しては３対１、１歳に関しては５対１、２歳に関しては６対１という配置で保育士が配置されております。有資格の非常勤に関しましても１０名程度配置をし、また、シフトの関係で無資格の非常勤に関しても配置をしています。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"さっき言ったように、年齢別に正規なのかどうか、それぞれで教えてください。正規でいるとは言っているけれども、有資格の１０人というのがどういう配置になっているのかわからないので、そこについて個別にお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"１歳、有資格者の１０人がクラスにどういうふうに配置されているのか、そこまで答弁を求めたいのです。ですから、ぜひ答弁を、どういう形でだったらしていただけるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"今、資料を持っていなければ、それはしようがないから、どういう形でなら教えていただけますでしょうかということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"それを約束をしていただきたいのです。私は委員長にお願いしたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、例えば五反田保育園の１歳児２２名について、この数を区としてどういうふうに認識していらっしゃるのか伺いたいと思います。弾力化を国が求めているので、保育課としてどういうふうに認識しているのか、そこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"ですので、五反田保育園の１歳児だけすごく狭い空間で少ない保育士で見ているということではありません。どこの保育園に関しましても大体同じような広さで、待機児童対策としてめいっぱい定員弾力化し対応しています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"それはスペースだとか、保育士の配置だとかは、基準をしっかりクリアするというのは区ですから当たり前だと思うのです。ですから、１クラス２２人という数字を見たときに、最善の利益をきちんと確保していただきたいというふうにあえて強く要望しておきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"東大井・八潮地域では５２名空いている状況があるというところで、空いているけれどもそこは選ばないということなのかをお聞きしたいところです。同じように、五反田も空いているけれども０歳児の待機児が出ているというのは、まずそこをお聞きしたいと思います。","respondent":"大澤保育支援課長","answer":"これは、そのご家庭のお考えで、認証が空いていてもやはり認可にこだわりがあるとか、そういうことなのだと思います。","id":"exchange-038"},{"speaker":"こんの委員","kind":"意見","question":"でも、預けたいという希望に沿うようにするとか、そうしたことは保育課ではされているのか。仕方ないですね、その辺のやりとりは、窓口あるいは申し込まれたときのやりとりはどのようにされていますかとの意見を述べました。","respondent":"佐藤保育課長","answer":"入園相談の窓口での対応だと思います。勤務先であったり、最寄りの駅であったり、その方ができるだけ認可保育園に入れるように対応しています。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問","question":"通える範囲でしょうか、第８まで希望されているというよりは、希望園を３園ぐらいまでしか書かれていないという方もいらっしゃる。やっぱり近いところが多いのか、それとも範囲を広げて選ばれることが多いのか、その辺の傾向はどうか尋ねました。","respondent":"佐藤保育課長","answer":"第６、実際に第７希望に内定が出た場合に辞退された方も、結果としてはほかの保護者の方にご迷惑がかかることもあります。その辺を考慮して、私どものほうで強く縛ったりはしませんけれども、窓口のほうで適切にさまざまなアドバイスをして対応しています。","id":"exchange-040"},{"speaker":"こんの委員","kind":"質問","question":"なぜこういうふうな質問をしたかというと、結局、なかなかうまく子どもが増える場所に園を増やすということがなかなか難しいではないですか。うまく活用していくとなると、通える手立てを何か考える必要があるのではないかと考えるのですが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"１５分でも無理ですという方もいれば、次の園でも１０分なのですけれども、ずっとこの問題はついて回るのだろうなと感じています。なかなか全部つくったところにきれいに入っていただくというのは難しいのだろうなというふうには思っています。","id":"exchange-041"},{"speaker":"こんの委員","kind":"質問","question":"ベビーカーで行くなどということを考えると、確かに国で定める３０分以内というのは、なかなか人によっては難しい。空いているところを何とか活用しながら保育需要にこたえていくという考え方は、今後必要ではないかと思いますけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"どこまで認可保育園に入りたいご希望が強いかというのは、やっぱり人によって違うのですけれども、どうしても入れなければ困るという方については、どうにかして入れるような方策は必要だというふうには考えています。","id":"exchange-042"},{"speaker":"こんの委員","kind":"確認","question":"１つの質問でかなり時間をいただいてしまったのですが、調整指数の確認ですけれども、調整指数の１２番です。これだけの園ができていますので、５番、６番の指数のあり方みたいなものはどのようにお考えか尋ねました。","respondent":"佐藤保育課長","answer":"夜間保育を実施しているところで、この辺の加点をしなくても十分需要にこたえられるようなお声を聞いているというところで廃止をしています。５番の転園に関しましては、今、兄弟姉妹がばらばらの保育園に入っているというところは１％程度かと認識しております。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"お子さん２人を連れて少し範囲を広げた園でとなるのはなかなか難しいので、保育園を選択できるような流れが今後あるといいなというふうに思います。できるだけ希望にかなう園でというところをここは調整指数というところで考えていく必要があるのではと思うのですけれども、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"お子さんが１人だけの方と、複数いる方が若干基本指数が低くて優先して入れるということが、それが本当に公平か公正かというところもあります。国からも一定そういった形で通知も来ていますので、今後さまざまな検討をして、保護者の方に提言できるようにしていきたいと思います。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つお尋ねします。ひろまち保育園は平成２８年４月から５年ということですから平成３２年まで、逆に、期間が延びていく見込みなのかというところをお尋ねします。","respondent":"大澤保育支援課長、吉田保育施設調整担当課長","answer":"初めに、１歳児の定期利用ですけれども、こちらは１４園で実施しまして、３８人の受け入れを４月１日でしております。 ひろまち保育園、ひがしやつやま保育園ですけれども、原則は５年の入園期間と考えておりまして、期間満了後はその後の転園先を確保するという形で検討しています。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望です。もう１つは、１０年は人口がある程度増えていくという状況の中で、その先のことについても検討されているのかどうかという点をお尋ねします。","respondent":"吉田保育施設調整担当課長","answer":"ひろまち保育園の件ですけれども、現状の場所での稼働期間を５年と考えておりまして、その後は、在園児については、どちらかへの転園等につきまして検討しています。","id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"意見","question":"わかりました。今後のことですので、現状では、５年で閉じた場合はそういった細かい配慮をしながら転園先を見つけていただくということをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２番目のはぐはぐキッズ中延の設置者ですが、これは区内では初めて開設されるのか、そこのところを確認させてほしいと求めました。あわせて、会社の離職率や、人件費率などがわかれば伺いたいと思います。","respondent":"大澤保育支援課長","answer":"２３区のほかの区において、認可保育園の運営を既にやっております。プリメックスキッズにつきましては、離職率が１２％、人件費率が５１％というふうに聞いております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"あわせて、各園に園庭があるのかどうか伺いたいと思います。公園が保育園の子どもたちでいっぱいになっていることが多々ありますので、そういった点も含めて、区のお考えはどうなのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"１番のチャイルドマインダー小山台東につきましては、水遊びスペースの設置を調整しています。１番から順番に、小山台東公園、２番が東中延公園、３番が旗の台広場公園、４番が谷山公園、５番がかむろ坂公園となっています。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"５１％というのがどう影響してくるのか、区としてもしっかり見ていってほしいと求めましたし、私のほうでも見ていきたいと思います。今、公園に子どもたちがあふれかえっているというところを区としてはどうされるのか、そういったことを考えていらっしゃるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"けが等があったときに、ほかの保育園の保育士に協力していただいたというようなお話も聞いてあります。できるだけ既存の施設を活用することを考えておりまして、今、保育課や教育委員会とも連携をとってあります。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお聞きしたいのですけれども、いわゆる東大井方面の開設の見通しは今後どうなのでしょうかというところを１点お聞きしたいと思います。もう１つが、あるいは八潮、勝島あたりの各地域で開設ができるとかという見通しはあるのかないのかお伺いしたいと思います。","respondent":"大澤保育支援課長","answer":"荏原地区は今年の４月に６園開設したので、荏原地区において待機児童が昨年まではすごく多かったのですけれども、落ち着いてきたと思っています。２園調整してございまして、おそらくこのままうまく開設までこぎつけるであろうとめどが立っておりますので…","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"以前、今回出てこないのは何かまだ出せない事情があるのかどうか、その辺を教えていただきたいのが１つです。屋上園庭を園庭とカウントしないで、保育者の目が届く場所、そういう位置にある園庭がある保育園はどこか、何カ所か、それを伺いたい。","respondent":"大澤保育支援課長","answer":"まだ計画承認が都のほうからおりていないということで、特に問題なく承認はとれるはずですので、今後ご報告できるかと思います。園庭につきましては、今、資料を手元に持ってきていないので、正確な数値がわかりかねます。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"さっきの保育園の職員のことと同じでいいのですけれども、あとで教えていただきたいとお願いをしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"資料にあるとおり３歳が１４人、４歳が１４人、５歳が１４人となるのでしょうか。幼児教育部門の意味もお尋ねします。","respondent":"大澤保育支援課長","answer":"空のはねこども園はたのだいですけれども、保育認定をとって区で利用調整をして利用される方が７３名で、そのほかに就労とかの要件ではなく、保育認定をとらずに、園と直接入園のお約束をして利用される方が、３歳児、４歳児、５歳児の合計で３名ということになります。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、保育園という扱いでよろしいのですか。それとも、もちろんこれは株式会社だから幼稚園ではないと思いますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"やはり土地がないから仕方がないのだということではなくて、もう少し必要な大きさの土地を確保しろと、そういう指導をするべきだと思うのです。必要であれば園庭確保分の補助金を出すことも含めて、本当に前向きに園庭確保に取り組むべきだと思うのですけれども、その辺の認識はどうか尋ねました。","respondent":"大澤保育支援課長","answer":"事業者にも少しでもということで区のほうからもお願いして、一時期よりは大分、狭いながらもお庭のある園が増えてきていると考えています。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"今回、できなかった理由と、それとあわせて区がどういった支援をやってきたのかということを伺いたいと思います。","respondent":"大澤保育支援課長","answer":"こちらは新築ではなくて、本来ですと内装工事のみの予定でございまして、早い時期に開設できるという見込みだったのですが。１０月、保育士の確保のためには４月開設がベストですという事業者の判断がございまして、４月ということになりました。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、直接的には保育士の確保が要因で時期がずれたということではないと。４月開園のほうが確保がしやすいということで延期となったということで、区の保育士確保のしやすさに変わりはないということでよろしいか尋ねました。","respondent":"大澤保育支援課長","answer":"平成３０年４月に１６園開設いたしましたけれども、保育士につきましては全園できちんとそろいましたので、特に保育士確保が理由で９月に開設できないということではなくて、ベストの時期を事業者が判断してございましたので、平成３１年４月にさせていただいたです。","id":"exchange-058"},{"speaker":"南委員","kind":"質問","question":"簡単に。今の説明だと、私も行きたいと思いますので、このチラシに書いて申し込みをした方がいいのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"お書きいただかなくても、できれば電話を１本はいただければと思います。当日でも結構ですが、前のほうのお席は事前にお申し込みがないと空いていない可能性があるということだけです。","id":"exchange-059"},{"speaker":"つる委員長","kind":"質問","question":"特に各委員からの質問については、教育委員会が子どもたちの未来のためにしっかりと尽くしていただくことをお願いして、委員長の挨拶とします。各委員、また理事者、書記の皆さん、本当に１年間ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4940#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":42800,"voices":161}},{"id":"h30-20180514-5","meetingId":"h30-cm05","date":"2018年5月14日","dateIso":"2018-05-14","committee":"総務委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"平成３０年度区政モニターの委嘱","agenda":"平成３０年度区政モニターの委嘱","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に、こんなところに区民の皆さんの視点が役立てられたという事例があったらお聞かせいただきたいのが１つ。やはり２０代、３０代、計画などがあったら説明を求めました。","respondent":"中元広報広聴課長","answer":"それともう１点、または夜に１回程度という集会を行っておりますので、なかなか参加が難しいというところが課題となっております。ただ、そこは課題と感じておりますので、今後につきまして少し意見を集約しやすいあり方というものも検討してまいりたいと考えております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"説明の中で、地区推薦の方の枠は、実際に年代別・職業別のところでどこに入っているのか、その辺の区別はつくのでしょうか。そこを説明を求めました。","respondent":"中元広報広聴課長","answer":"町会推薦で応募していただいて委嘱した方というのは、町会推薦で更新をされた方が既に８人いらっしゃいます。新規で町会推薦で入って来られたのが１３人、全体の中で５０人のうち２１人が地域からの推薦をいただいた方ということになっております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、町会推薦の方と言ったら、やはり年齢的には高い方が多いということですかね。","respondent":"中元広報広聴課長","answer":"委員おっしゃるとおり、やはり町会で活動されている方ですと、どうしても５０代、６０代の方も、お二人いらっしゃるとやはり６０代以上の方が多くなっております。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜ来てくださったのかなということで伺ったら、ふだん知る機会がないので、お嬢さんのほうがお母さんに一緒に来てもらったという形だと思うのです。もし何かお考えがあったら教えてほしいと求めました。","respondent":"中元広報広聴課長","answer":"こちらも少し住所要件等を今後検討していって、品川区のことを、地域のことを今勉強してらっしゃったりするのですね。ですので、そういうところにつきましは、いろいろ連携、所管課とも相談しながら今後検討していきたいと考えています。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり政治参加を促すということであれば、どこの区であっても、何も品川区に限るという考え方ではなくても可能なのではないかなと思います。これは要望でいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"若い方という話だったと思うのですが、まず、どのように募集をかけているのか教えていただきたいのと、年齢別の表を見て、区としてはどう現状を考えているのかというのを、まず説明を求めました。","respondent":"中元広報広聴課長","answer":"こちらの年齢別の表ですが、やはり２０代から４０代の方の人数が少ないというところは課題として捉えておりまして、課題として考えております。その辺のところもあって、年に１度は夜に開催するなどを工夫しているところなのですが…","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ですので、その情報をどう伝えていくかというのは、これに限らずですけれども、ぜひ研究して実施してほしいと求めました。仮にどうしてもその時間帯しかできないというのであれば、会社にもお願いをして、その辺は区としてどのように考えているのか説明を求めました。","respondent":"中元広報広聴課長","answer":"そういう形でほかの時間や曜日に移してどの程度行えるのかというところを、今後課題として検討していきたいと思っています。企業との連携の仕組みを、個別の対応でご協力いただけるところがあればということは、可能性はあるのかなと思っているところです。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆるＣＳＲもやっていて、実際に具体的に幾つかそういった取り組みというのを各企業とも行われているわけではないですか。ぜひ、進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"絞ってもいいですから、お考えをお聞かせ願うという工夫も、今の時期ではそういうふうにやっていかなければいけないかと思うのですね。さまざまな事業に使っていくわけですから、そういうことも工夫として、私は考えていただければありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"平成３０年度わ！しながわ魅力発信事業について","agenda":"平成３０年度わ！しながわ魅力発信事業について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"まず第一になぜなのかと思ったのと、これはどういう事をあらわすのか、いまひとつわからない。(1)と(2)のところをもう少し詳しく説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"実際に、区民と一体として進めていくというような意味合いも少し含めまして、区として広報活動の支援にシフトして実施していきたいと。いわゆる自主的に実施をしていただく方を応援していくというような方向、そういう形でシフトしていこうと考えたものです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今年も見通しというか、区の魅力を発信する、自発的に区民の皆さんが自分たちの予算で発信をするものの広報をお手伝いするということなのですか。そこのところを教えていただきたいのと、どういう基準で選定をするのか、その辺も説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"実際には４事業、昨年度は助成の上限額は２年前と全く同じだったのですけれども、それで４事業認めているところです。審査に関しましては、実際の基準といたしましては３の対象事業にそぐうものであるかどうか、こちらを判断いたしまして決定したいと考えております。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"これにかかる予算というのは具体的に、助成はしなくても予算はどれくらいかかるのでしょうか。説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"これに関しての、いわゆる事業予算的なものとしてはとってはおりません。人件費だけです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"結局、その辺のこれまでの評価と、自分たちで事業採算をとりながら発信していくという方向性が見えたと評価していると理解してよろしいのでしょうか。その辺もう少し教えていただきたいのですけれども。","respondent":"木村報道・プロモーション担当課長","answer":"実際に昨年度助成したところを基本的には同じような形で継続されるところは継続の計画を出されて、いわゆる事業継続に関しましては、そういうことがなくても引き続き事業実施していけるというような形で見ております。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"その中で集客が厳しいだろうなと思ったら案の定厳しいものもあって、だんだんこういうふうに改良されてきたのだと思うのです。で、継続の方たちはそれでいいのですけれども、その辺についてはどのようにお考えか説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"全く今まで考えもしなかった新たな取り組みという部分も、これはおもしろいね、そういう展開は我々も期待しているところではあります。実際にそういう動きも、今も出てきておりますし、これからも出てくることを期待しております。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問","question":"ただ、私も経験があるのですけれども、結構広報というのがお金がかかるのですよね。ですから、基本は事業については参加費なり何なりで自分たちで採算をとっていくということが今後前提になっていくという理解でよろしいか尋ねました。","respondent":"木村報道・プロモーション担当課長","answer":"そのご認識でよろしいかと思います。","id":"exchange-015"},{"speaker":"石田（し）委員","kind":"質問","question":"いや、本当は許可が必要だというふうになってしまうのもかわいそうなので、その辺はある程度教えてあげなければいけないのかなと。区としてその辺の認識というのはどうなのか尋ねました。","respondent":"中元広報広聴課長","answer":"そういう事務手続きもありますので、まずは建物を管理しているところにお問い合わせをいただければというところがあります。その辺のところは内部でも調整しながら、個人の部分の基準をまだあまり詰めておりませんでしたので、その検討・調整をさせていただきたいと思います。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問","question":"それこそ撮影時間も５分だったり多くても１０分だったりした場合に、それは１回１回そこの撮影許可をとる必要があるのか、少し難しいのかなと。いろいろなものがあって、その辺をあらためて、例えばその例であればどうなるのかというのを説明を求めました。","respondent":"中元広報広聴課長","answer":"区の施設だけならよろしいのですが、民間の施設であったりということもありますので、その辺は撮影される方も少し考えていただけるとありがたいなと。もちろん広報、シティプロモーション担当のほうにでもまずご相談いただきまして、個別に対応させていただければと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、このわ！今年で４年目に入るのですが、何をもって判断するのか、ご見解を説明を求めました。","respondent":"木村報道・プロモーション担当課長","answer":"こちらに関しましては、正直難しいところがありますけれども、どれだけ発信したものを見ていただいたかという統計はとれるのですね。言い方は変ですが、なかなか把握しづらいところもありますけれども、アウトプットのところで把握しているというのが現状です。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"何かこれで結果が出たのですよということは、やはり報告はしなければいけないし、また難しい問題ではないですか。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どういうものなのか、決まっているものがあったらお教えいただきたいのと、それも１つ効果があると思うのですね。あれはすごく人気があると伺ったことがあるのですが、今年度もそれも含めてどのように行っていくのかお知らせほしいと求めました。","respondent":"木村報道・プロモーション担当課長","answer":"その他の部分についても、これからまた検討してまいります。一部建設会社のほうからは、そういうところについてはぜひロゴをお使いくださいという形で行いますので、続けてまいります。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、品川区の魅力を発信ということで行ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"その後、最後は県民に焦点を当てたというやり方をしていると、いろいろな今までの試行錯誤についてのご苦労を伺ってきたのです。これをどういうふうに、具体的にどういうことをお考えになっているのか、そこをお伺いしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"現在の考え方なのですけれども、おっしゃられたように、ケーブルテレビの番組などでもご紹介しているところです。考えているのはその次世代と言うのですか、そういった数珠つなぎにつなげていこうかなという考えで、動いております。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"質問","question":"品川区が魅力あるなと思うコンテンツになるのかどうかというところで、果たしてつくれるのかどうかというところでの、意気込みを伺いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"行ってみれば楽しそうだななどというところを感じていただくというところが一番ポイントかと考えていますので、その人を掘り下げた形で特集をしながら、次へ次へとつなげていきたいと考えています。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"意見","question":"１つでも２つでも、口で言うのは簡単なのですけれども、大変なことだと思いますのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]},{"id":"topic-03","title":"男女共同参画のための品川区行動計画 第５次等の策定について","agenda":"男女共同参画のための品川区行動計画 第５次等の策定について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１つ、この辺の学識経験者の選び方、あとは公募区民というのはどのような感じで公募されてくるのですか。その辺を説明を求めました。","respondent":"島袋人権啓発課長","answer":"ジェンダー学ということで、川眞田嘉壽子教授がおられましたので、まずは進めさせていただいているところです。その後の委員に関する募集ですが、品川の広報３月１日号、こちらにマイセルフ品川プラン策定検討委員会区民委員募集の案内を出しまして。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"２０１７年に１１４位に下がったということで、私は、今までどおり本当に前進しないなという思いがすごくしているのです。その辺のところ、大もとのところを一つお伺いしたいと思うのですが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"女性の活躍の支援、誰もが活躍できる機会の拡大、こちらのほうも関係各課との取り組みを進めさせていただきたいと考えているところです。品川区におけるおのおのの計画とも整合性をとりながら品川区版を目指すように今後の策定委員会の中で検討されていくようになるかと考えてい…","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"各分野等、やはり力を合わせて、特に性別等にとらわれないという意味で実効性のある計画を立てていただきたいと思うのが１点です。東京都においても差別のところですか、品川区でも今後ぜひ考えていってほしいので、現状どのようなところなのかというのを伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"７月に多様性理解促進講座という講座をしますので、まずは区民の皆様方に知っていただくという内容での講座の取り組みを始めたいと思っています。どういったものが区として進めなければいけないところがあるのかを研究しながら進めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自分の性別に悩んだ経験のある方が１.８％、１５人いらっしゃいましたと書いてある。２２.３％男性がいますというあたりも、施策に生かしてほしいと求めましたが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"無回答は４名ということです。答弁もれがございました各区との連携、やはり動きを注視しつつ、策定委員会の中でもそのように進めていくというふうな予定でおります。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"確認になるのですけれども、この策定委員会の第１回の委員会での議論の中で、それを前提としたものになるというふうに理解してよろしいでしょうか。その辺の確認させてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"委員のおっしゃるとおりで、そのようにさせていただきたいと思います。報告書の概要版に関しましては、ホームページ上でもでき上がり次第アップを予定しているところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですからその辺を、もう少し何か、もう少し理解を広げるようなまとめ方というのも分類していただきたかったなというのがもう１点です。民間の事業所とか、そういった区民に先駆けて工夫をしていっていただきたいと思うのですけれども、その辺についてのお考えがあれば説明を求めました。","respondent":"島袋人権啓発課長","answer":"下のところに説明書きを書かせていただきまして、その件に関してのアンケートでしたので、今回はこのような形をとらせていただいております。１回目の委員会に間に合うようにお届けいたしまして、目を通していただいてから委員会に臨んでいただくというように作業を進めておりま…","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから、進んでいるようなところでも、当事者の人たちにしてみたら、なかなかやはり今の社会状況では難しいのかなと思います。基本、区内でもそういう施策を進めてほしいと求めましたので、その辺は要望でとどめします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"いろいろ漏れているところもあるかと思いますけれども、よく行われたのではないかなというふうに思いました。以上、感想だけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-04","title":"総合庁舎エレベーター改修工事請負契約について","agenda":"総合庁舎エレベーター改修工事請負契約について","exchanges":[{"speaker":"飯沼委員","kind":"確認","question":"再利用するものは利用してということで、日立ビルシステムにということで、業者推薦随意契約というのはそういうものなのですか。こういうことは、今のエレベーターは５基とも日立製で、そこの関係で行っていくということでいいのか、確認させてください。","respondent":"立木経理課長","answer":"委員のおっしゃるとおりでして、これは性質または目的が競争入札に適しないものを契約する場合にとられる手法です。５基とも日立ビルシステム製のものでして、当該事業者に契約することが最も有利ということで、このような形をとらせていただいております。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"これはご存じかどうか。日立のどこの製品がどうなのかというのはわからないのですけれども、このことと今回の工事の関係があるのかないのか、そこを説明を求めました。","respondent":"立木経理課長、小林施設整備課長","answer":"こちらのシステムが、戸開走行防止機能というものなのですけれども、一応これが今回の更新によりまして適用されるような形になります。きちんとそういったものが正しく適用されるような工事管理、そういった契約もしますので… 私のほうから少し補足なのですが、今、委員がおっしゃった１２月の報告というものにつきましては、品川区の中ではそういうエレベーター、該当しているものはございません。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大丈夫ということなので、きちんと行ってほしいと求めました。これは全体をとりかえた場合と今回の工事との費用のかかり具合は試算をされているのか、その辺を教えてほしいと求めました。","respondent":"立木経理課長","answer":"部分的に、例えばかごなどの部分とか、レールを入れかえたりとかという部分工事の場合、２億４,５００万円程度。部品供給が停止になってしまった巻き上げ機というものが主な更新なのですが、こちらが今回の１億５,０００万円ということになっております。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"今回、このように改修工事をすると、今後どのぐらい耐用年数、もつのか教えてください。以上で終わります。","respondent":"立木経理課長","answer":"実際、今回のエレベーターが製造されましたのが３０年ほど前になります。今回更新があった程度、大体２０年から３０年ぐらいの間になると思いますが、それぐらいは耐久性というのはあると考えております。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問","question":"こうして契約を結ぶに当たって、契約書に書く内容であるとか、こういった中身でという契約書を交わされるのかどうか。その契約書にどのようなことを書いて仕事を依頼するのかどうか、その辺を説明を求めました。","respondent":"島袋人権啓発課長","answer":"今、お話しさせていただいたとおりなのですけれども、まず、講演の目的に関しては、そちらのほうで詰めします。あるいは１４条の法の下の平等など、差別されない権利や、人間らしく生きる権利についてということをもとに構想をしているところです。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30283,"voices":93}},{"id":"h30-20180516-14","meetingId":"h30-cm05","date":"2018年5月16日","dateIso":"2018-05-16","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時２１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"平成３０年陳情第７号、羽田新ルート計画","agenda":"平成３０年陳情第７号、羽田新ルート計画","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここをちょっと具体的に伺いたいのですけれども、環境影響等のできる限りの軽減というのはどういうことなのか。そして、地元へのメリットの創出、これも具体的に何なのかを教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"例えば住民への丁寧な説明、住民への丁寧な説明につきましては、教室型も含めたさまざまな区民への丁寧な説明です。これは当然ながらデメリットが大きいというところで、やはりデメリットの軽減というところを強くお話ししています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、すごく雑駁にといいますか、求めて要望されたということなのでしょうか。全くなかったのか、本当に区の記録がないわけですから、ぜひもし具体的にもっとあるのであれば答えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"これを考えるのは、やはり事業主体、国策として提示している国のほうがしっかりと考えていただくです。それに突っ込んで、例えば防音対策についてどこそこの何かをどうしてほしいとか、そういった具体的なところは出てございません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、これを出したことで品川区への配慮事項が出たのだということで、当時課長がおっしゃっていたのですけれども、ではこの４月１８日に要望したことの成果が品川区への配慮事項だというふうに受けとめているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"この方策については、これは実際国のほうが運用を開始していますが、これが区が求めている最終的な答えだという受けとめ方はしてございません。さらにさまざまな対応を今後も求めていくという受けとめ方です。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのために、何をどう区が区民の代表として求めているのかが全くわからないのです。それなのに、何も残さずに区が求めた、そうしたことも今後記録なり区の方針として残していくという考えはないということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"ただ、残さなければいけない記録はしっかり残していくと。丁寧な説明、１５分という短い中でそれがしっかり伝わったですので、議事録も残していないです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区長が要望しているわけですから、その中身は何なのか、何を区長は区民のために言ってくれたのかと区民が思うのは当然のことだと思うのですね。このレベルのものの記録は必要ないということなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"これは間違いないことでございまして、それを区長が出席した会議の、全ての議事録を毎回とらなければいけないかということではないと思います。今私が申し上げた環境影響への配慮、安全管理、丁寧な説明がしっかり伝わったという議事録になろうかと思いますけれども。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、やはりこの重大な問題をほかの会派の皆さんはどうお考えなのかというのを委員会ですので、ぜひ意見をお聞きしたいなと思います。自民党、公明党、民進党の、この記録のないことについてのご意見等々を伺えたらなと思うのですが、お願いします。","respondent":"鈴木都市計画課長","answer":"今現在も伝えている、この項目について、その場で口頭でお伝えしたと。いやいやそれはこれで対応は十分なのですよとか、しっかりと丁寧な説明、記録としてはとどめていないです。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどから質疑を伺っていて、まさに公文書のあり方のことを質問されていらっしゃるのだと思います。後ほどちょっとこの内容についても質問したいのですけれども、そういうお時間はとっていただけるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり長い今質疑をされていらっしゃいますけれども、私どもも質問させていただきたいのですけれども、よろしいでしょか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回のこの件も、２年間にわたって明かされてこなかったわけです。そしてこの内容、昨年の１１月のタウンミーティングで初めて明かされたわけで、ぜひ皆さんにもその認識を持っていただきたいなと思って伺いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その中で、正直本当にわからないのでお聞きをしたいのですが、不動産価値の低下などが大変心配ですというご懸念が示されています。ここについて区としてどういう、これが果たして適正なのかどうか、ちょっとそこについて何か情報があれば教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"航空機騒音によって不動産価値が下がるといった直接的な因果関係はないという説明を国のほうはしているという状況でございまして、これも直接的に。国のほうはたしか一事例を紹介して、たしか国のほうでは一つ一つの根拠を示して…","id":"exchange-010"},{"speaker":"あくつ委員","kind":"確認","question":"さっき言ったように因果関係がはっきりしないということですから、一つの要因になる可能性はあるかと思います。１日の平均ではない、反論すべきものなのかどうかということもありますけれども、何らか国もしくは区として反応するということはあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"そういった内容に区が直接反応して、例えばテレビ局等に申し入れをするということは考えてございません。あるいは区内の不動産関係の方にご説明していただくと、そういうことは申し入れとして必要ですし、しっかりしていきたいです。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"意見","question":"先ほど申し上げたとおり、今回の問題が不安をあおっているという部分もあると思うのです。そういうことであるならば、これは区民の不安を少しでも軽減する必要があると思いますので、ぜひそういったことはお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"固定資産税の軽減の制度をとっているのだという話を聞いたという話も伺っていますので、より強い要請をしていただきたいというふうに私は思います。そういうふうに区民の方が求めるのも当たり前だなと思うのですけれども、まずお伺いしたいというのが一つと、そこら辺もあわせてお伺いします。","respondent":"鈴木都市計画課長","answer":"よくないというか、あり得ないことではありますが、直接的に何か国土交通省のこの場を切り抜いてお知らせするということは考えてございません。それから、区長ということで、副区長を含めてですけれども、この２回以外に国土交通省に出向いたということはございません。","id":"exchange-013"},{"speaker":"安藤委員","kind":"確認","question":"この４月１８日、５月１７日以外に区として公にといいますか、ではこの２回のみなのかということの確認ですね。それと、２回に分けて行った理由というのをちょっと伺ったので、そこもあわせてお伺いします。","respondent":"鈴木都市計画課長","answer":"最初から２回に分けて行きましょうかというところ、何回でもといいますか、上の方にしっかり伝えるということは重要という認識で２回行ったです。ですので、やらないということではなくて…","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"このメリットの中身は何ですかと聞かれて、その内容は国が提示すべきものと述べておりますが、言われた国も困ると思うのですよ。それは国が考えて全部提示しろということなのか、改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国へ区の基本的な考えを、スタンスをお伝えするということは今までもやってきましたし、これからもしっかりやっていきたいです。何かその場で、国のほうで考えていただくというのが区のスタンスでございまして、それはしっかり国のほうがまず考えていただくです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"５月のほうの国の記録なのですけれども、少し具体的にお伺いしますが。あるいは文書が届くとか、何かいろいろあると思うのですけれども、それはどんなことを指すのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"空き家対策について、これは当然ながら品川区をぜひしっかり見ていただいて、さまざまな課題を一緒に考えていただきたいと申し上げたところです。課長、これは当然区民の方のために仕事をしている者にとっては…","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとそこら辺はもう一度お伺いしたいのと、それと、それは何かやはり品川区の中に当日の記録があるということなのですか。私たちはそれを出してほしいと言っているのですけれども、そこら辺はいかがなのか。","respondent":"鈴木都市計画課長","answer":"それから、区の議事録を見て申し上げたわけではなくて、やはり区にしっかり目を向けていただきたいという思いでお伝えしたのではないかです。何か一緒に考えていただきたいというのを、私が何かを読んでこの場で発言したわけではございません。","id":"exchange-017"},{"speaker":"安藤委員","kind":"確認","question":"記録の問題についてもちょっと私は伺いたいのですけれども、ちょっと確認なのですけれども、さまざまな内部の打ち合わせを行ったと。つくらなかったのかどうか、それは残っていると思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長、鈴木都市計画課長","answer":"私のほうからは、環境騒音調査の実施についてのご説明をしたいと思います。昨年度の予算の中で、約８００万円使用いたしまして、環境騒音調査を実施しております。 国土交通省に出向くまでの内部の打ち合わせの状況ならびに議事録の作成ですが、これは基本的には庁内の担当者が打ち合わせを行った。ああいった対応をしていただいたというところの確認を何度かして…","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一点伺いたいのは、しかも時間も１０分から１５分ですので、普通は要望を事前に国土交通省に文書として送りますよね。今国土交通省にも追加でちょっと確認をさせていただいているのですけれども、そこら辺、そこを確認させてください。","respondent":"鈴木都市計画課長","answer":"事前に何か文書を、こういった内容を当日お願いしますよというやりとりはなかったかですが、何か文書を事前に送ったということはございません。担当レベルではあったのではないか、これは私の想定ですが、あったのではないかというふうに考えてあります。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"それと、やはり中身があって、何を言うかというのが重要なのではないですか。ですから、そこのちょっと何度伺っても会うことが重要だと答えられるその意味、考えを伺いたいというのが２点目です。","respondent":"鈴木都市計画課長","answer":"当然ながら国のほうも何をしにいらっしゃるのですかという話になりますから、それは区の考えをお伝えしたいというところのやりとりはあったです。直接会って、区の考えをしっかりお伝えすると、当然そのお伝えする内容も重要です。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"判断したというのですけれども、そもそもそんな決定をする権限というのは部長にあるのでしょうか、伺いたいと思います。重大な間違いだと思うのですけれども、いかがでしょうか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"当然ながらそういうやりとりはしています。先ほどご説明したとおり、何かそれを部長が決定するのはおかしいというお話もありましたが、それはそうではないというふうに考えております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺はどうだったのでしょうか。区長の判断という点では、当日何もなかったのか、記録を残してほしい、残すべきだ、残しておいてねという指示はなかったのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それを一つ一つ区長が指示するというところは、状況によってはあるのかもしれませんが、ないのかなです。１０分、１５分の内容で、これは部長の判断で記録としてつくらなくてもです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご要望については勉強したいとか、４月は事務的によく調整させてほしいと、ちょっとニュアンスが若干変わってくるわけなのですよ。ですから、自分たちの出した要望がどこまで伝わったのかというのは証明できないし、ほかの人に説明もできないと思うのですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"国土交通省が３月に出しました落下物対策の強化策として、落下物対策総合パッケージというのをホームページにも出しております。これについての区の評価、またもし課題があるなと思うのであれば、それを説明を求めました。","respondent":"鈴木都市計画課長","answer":"再三区のほうで要望していた内容で国のほうも検討していただいているのではないかというところで受けとめているところです。あるいはさらに内容を膨らませて、充実させて進めていくのかというところはしっかり見ながら、しっかり継続して国のほうに申し伝えていきたいです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"落下物の強化対策、ゼロにしていただきたいということでしたけれども、ならないということが私たちは明らかだということを受けとめてきました。これでは危険過ぎるし、安全対策とは言えないということをぜひ言っていただきたいなと思うのですけれども、そこら辺はいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今回３月に示された対策案の内容については、しっかり各航空会社で対策は立てて、しっかり実行していただきたい。それを進めていく中では、やはりこれができて終わりではないというふうには思ってありますので、しっかりと伝えていきたいです。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"確認","question":"それでも、これは落下物対策ですから、落下物がゼロにならないと飛んでもらっては困るわけですよね。幾ら対策を講じられても飛んでもらっては困るわけですので、それぐらいの認識が区にしっかりあるのかどうか、ちょっと確認させてください。","respondent":"鈴木都市計画課長","answer":"この案に基づいて、当然ながら区としても落下物がないようにさらに取り組みを進めていただきたいというところは今委員がおっしゃったとおりです。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"落下物ゼロを目指すのではなくて、ゼロを実現させていただかないと飛んでもらっては困りますということをしっかり言っていただきたいのです。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"安全対策、落下物対策についてのさらなる取り組みについては、これからもしっかり求めていきたいと思います。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"これが豊中市の不動産価値が下落をしているということにどうつながっているのかというのはちょっと引っかかるので、しっかりした因果関係があれば国にも何か具体的に求めていくことが当然できるのだろうなと思いつつ、ちょっと今後のために説明いただければありがたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"確認","question":"で、固定資産税の軽減策もやっているのですよということを聞いたということを都議会の質疑の中で確認をしております。現地での調査で私が確認した事実をもって、そのほうが自然なのではないかと私は認識していると、そういうことでございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"若林委員","kind":"意見","question":"なかなかこういう場で何か本当に個人的な意見で極めて関連性が高いというご意見はわかるような気もするのですけれども、その程度のお話かなと、私もまた勉強していきたいなですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"それで、私がお伺いしたいのは、ちょっと記録がないものですから、結局今ある記録といったら区長のタウンミーティングの発言なのですよね。これはどう見ても事実として認めたことと同じだと思うのですけれども、これはどう読んだら、私はご説明をお願いしたいと思うのです。","respondent":"鈴木都市計画課長","answer":"デメリットについてですが、やはり落下物の危険性あるいは騒音、環境に対する不安というところが大きなデメリットです。しっかり国のほうでも目を向けていただいて、メリットのことについて国のほうでもしっかり考えていただきたいというところをお話ししたわけです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"当時の課長が新ルートのほかに機能強化で品川の上を飛ぶ以外のルートというのは何か提示されているのですかというような旨の質問に対して。それをちょっとお伺いしたいなと改めて思います。","respondent":"鈴木都市計画課長","answer":"インバウンドを増やして、そういう必要が今後ありますという国の考え方、そこをイコールで増便計画まで理解をしていますということではございません。私も国のほうの資料をいろいろ見ましたが、さまざまなルート案の検証がされて、今示されているのがこれだです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう二重的な表現があり得るのですか。ぜひ答弁をお伺いしたい。","respondent":"鈴木都市計画課長","answer":"やはりインバウンドの増加、海外とのつながり、国際競争力の強化が必要だという基本的なところについて理解をしていますです。今国のほうで先ほどもご説明しましたが、いろいろな飛行ルート案を検討した中で、品川区の上空を飛ぶ案について今その案について示されているです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"求め続けるのでしょうけれども、まず飛ばないための努力をすべきなのではないですか。しっかりとここまで出されたら納得するというものがはっきりあるのかどうか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"委員長、この間の安藤委員と石田ちひろ委員の質疑の様子をどのように委員長としてお感じになっておられるでしょうか。要望、そういう審査はもうそろそろこれで終わりにして、効率的な委員会運営に移っていただければというふうに申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"区民の代表ですから、まさに自分の会派の委員に対しては、それこそ慎重に対応しなければいけない。ですから、円滑な運営を今後も行っていただきたい、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員長","kind":"質問","question":"区民の意見を代表として発言をするという使命を持っているわけですから、さまざま準備をしながらこういう質疑を進めているわけですから。この陳情の中身とずれているというのであれば、ずれている中身を指摘してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"改めて傍聴人より不規則な発言ならびに物音がした際には、速やかに注意をいただきたい。〔発言する者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、結局私が求めているのは、飛ぶことが前提の条件闘争なのですよ。どういうふうに反映させるべく行動するのか、この協議会に向けて何をしてくれるのか、これを教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"もう一点につきましては、この新ルート案に対してさまざまな取り組みを進めていくのは、区ではなくて国です。国がやるべきことは、やはり区民の方が不安に思っていることについてしっかり区に対して説明していただいて。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"首相は地元の理解を得て進めると言っていますけれども、地元は理解していませんということをきちんとちゃんと言ってくれるのですか。そこら辺は大事な問題なので、きちんと伺わせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"区民への丁寧な説明ですので、これまでもしてまいりましたが、この３点を国に重ねて要望していくというところが区の重要な姿勢だです。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここはどうなのか、品川区はその協議会に向けて何をしてくれるのですか。何もしないのですか、そこら辺はどうなのですか、お伺いします。","respondent":"鈴木都市計画課長","answer":"先ほどもご説明しましたが、これまで同様、地域の方にさらに説明を行っていきますというところを聞いてあります。いつぐらいにやりますということではなくて、区の要望に対して地域へのさらなる丁寧な説明を行っていきますということを国から聞いてありますので。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"観光資源をこれからどうしていくかですとか、やはり訪れていただく方々、それは羽田の新飛行ルートとは別ですから。まあ伺っていますというのだから、区民に対してもしっかりとさまざまな部分、伝えてきているのは間違いないところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"１番については、代表・一般質問等で区当局からご説明がたくさんされたということで、報告がされているのだろうという認識で理解をしております。今回は１番、２番一緒に出されておりますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"安藤委員","kind":"意見","question":"これは当然区民にとっても重大事ですので、詳しく改めて報告をすべき問題だと思います。２００４年にも浦安市で同様のことがあり、暮らしを守ることにつながるかということを鑑みますと、当然これは採択をすべき内容だと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"松永委員","kind":"意見","question":"２番に関しましては、また周知がされていない現状がありまして、また議会としても総意として２回意見書を提出している立場があります。よって、現段階ではそうした判断に至るのは難しいと考えているため、この陳情に関しては不採択としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"}]},{"id":"topic-02","title":"区有施設・公有地等活用に関すること","agenda":"区有施設・公有地等活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"介護施設ということで、介護施設というのはどのような、具体的にどういうものがあるのかというのと、あと定期借地というのは何年かというのは向こうから来ているのでしょか、そこがわかれば説明を求めました。","respondent":"柏原企画調整課長","answer":"こちらの国のほうの方針といいますか、今回のパターンで言いますと、方針が財務省のほうから出てあります。ただ、国のほうは何年ですよという言い方は今回の照会ではしてきてはございません。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"売却も要望していく、地域からの要望としては、さまざまな地域の要望が存在しているのですね。現時点として、区としては周辺住民にどんなニーズがあるかというのは把握されているか尋ねました。","respondent":"柏原企画調整課長","answer":"広場といいますか、という使い方ができないかというのは実際地元の町会の方であるとかというところからのお声は聞いているところです。個別には何の施設という例示は挙がってはおりませんけれども、区としてもいろいろなニーズがあるであろうというのは想定しています。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、貴重な土地ですので、この間も課長から行政需要というのが、いろいろ言葉が出されますけれども、本当にたくさんあると思うのですね。地域住民をはじめ、多様な区民の要望を反映した活用を検討していただきたいなと思うのですけれども、ご検討いただけないか尋ねました。","respondent":"柏原企画調整課長","answer":"手法はさまざまあると思いますので、やり方というのは検討したいと考えています。ちょっと不透明な部分がありますが、前段のご質問のニーズに関しましては、さまざま検討していきたいというふうに思ってあります。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"そういうことというのは、用途によって考えなければいけないところというのはあるのではないかなと思ったりするのですが、その点いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それから防災の観点で土地を購入する際に、国費が入ることがあるのですけれども、それが使えないかというような検討はしております。ちょっと面積が約１,６００m2ということで、比較的面積の小さい１００m2とか、調査をしなくてはいけないだろうというふうには思ってありま…","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。地元の要望というのはその際にもどういったものがあるかということで紹介をさせていただいたところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"大沢副委員長","kind":"意見","question":"副委員長を１年やらせていただきました。理事者の皆様方、ありがとうございましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6048#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":40519,"voices":121}},{"id":"h30-20180517-18","meetingId":"h30-cm05","date":"2018年5月17日","dateIso":"2018-05-17","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ２時１５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"オリンピック・パラリンピックまであと何日とあって、当然、そこにもつなげていただきたいとお願いをいたします。せっかく３つのキャラクターで応援しているわけですから、声をあてていただければと思いましたので、お願いしておきます。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今のところ考えておりますが、２分程度のものですと、そのような形でどんどん拡散していくよう取組んでいきたいと考えています。いわゆるアニメのようにできるかどうかは、予算の問題もありますが、今後研究したいと考えています。","id":"exchange-001"}]},{"id":"topic-02","title":"ホスピタリティハウスの誘致","agenda":"ホスピタリティハウスの誘致","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"もし万が一この３年限定の中で、３年ではなく、引き続きやっていきたいとなるかもしれません。そうしたことを踏まえて、ほかの場所の目星を区は別途つけていらっしゃるのか、その辺をお聞かせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そこの一画の２,０００m2程度を、２０２０年の１年間、有償でお貸ししましょうということだけ回答していただいているところです。こちらのほうは誘致の活動を進める中で、適地がほかにあれば、そこで進めていくということも可能性としてはあるとお答えします。","id":"exchange-002"},{"speaker":"新妻委員","kind":"意見","question":"ありがとうございました。全面的に誘致をするという方向で、ぜひ取り組みをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、現状、誘致活動としてどれくらい動かれているのでしょうか。それから、区はどういう国をターゲットにしているか、その辺のことについて説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば、ホスピタリティハウスを設置するような予定はありますかと、そういったことでお伺いしたことは数回あります。区内にも大使館や領事館が幾つかありますので、そういったところをまず、もともとの関係のあるところを中心に進めていきたいと考えているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、進捗状況としては、取りかかってきたという感じで、これから本格的に動いていくのか。それから、もう幾つかの国からオファーというか、いい返事が来ているのか、その辺の進捗状況はどうか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり平昌オリンピックが終わって、大体５月過ぎぐらいから各国とも、次どうしようかという感じだと業界の方からは伺っているところです。私どもとしても遅れることなく、いろいろなところにアンテナを張り情報を集めていきたいと考えています。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"いろいろと提案しているのだけれども、ではどういうふうにしていきましょうと、お互いにそういう話ができないではないですか。そんな話になってくると、区民に対して一緒にこういうことをやっていきましょうということもなかなかできないので、全体の方針を教えていただきたいとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"もうあと２年しかないだろうとお叱りを受けてしまうかもしれないのですが、にぎわいづくりの方法を何か考えていきたいと考えています。実はその後、特にいいレスポンスが今のところないので、また引き続きこちらのほうも進めて、お声をかけていきたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこをどうやるかというのも、相当魅力があることであって、それはある程度行政判断がないとできないではないですか。これでは決まらないなと思っているのが私の印象なので、お考えをぜひまとめていただきたいという要望というか、お答えがあればお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"なかなか行政の動きが遅いというお叱りも受けたのですけれども、もちろんやる気はあります。あわせて競技委員会とも相談をしながら、ぜひ盛り上げていきたいと思っていますので、どうぞよろしくお願いいたします。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、東京２０２０大会のエンブレムとかは、あるいは大会組織委員会との関係についてもあわせてお聞きできればと思います。２,０００m2ないとできないということではなく、いろいろなところでできるということでいいのか、そこも確認させてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから、２,０００m2ありきなのかということなのですが、そういうことではございません。財政規模の小さい国でしたら、もっと小さなところで小ぢんまりとやりたいというところであれば、そういったところをまた探すということになります。","id":"exchange-008"},{"speaker":"つる委員","kind":"確認","question":"今、各委員から質疑がありましたけれども、改めて確認で、ホッケー、品川区内での競技になりますけれども、今、競技場も整備しています。あそこが東京２０２０大会後、この委員会の中でもあったかと思いますけれども、そこの部分について改めて確認をさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、ホッケーだけということではございません。多目的に使えるようにというのは考えているところです。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"この委員会の中でも当然それは求めてきたところなので、要は、あそこをホッケーの聖地とするのだと。何かあれば、改めて伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ホッケーについての今後の取り組みです。ですので、今後も地道に学校やすまいるスクール等ともタイアップしながら、ホッケーの普及というのはやっていきたいと考えております。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"それだけの価値があるわけですから、区としてそれをどう活かしていくか、区として示していく部分が必要なのかなというのはすごく感じています。やはりもう少しアクセルを踏みこんでというのでしょうか、大会組織委員会や東京都との確認とか、改めてそこをお願いします。","respondent":"安藤文化スポーツ振興部長","answer":"２年しかありませんけれども、人の集まるようなイベントも含めて考えて、盛り上げていきたいと考えています。その成果についてはまだ出ていませんけれども、そのような形で、我々も一生懸命、今後とも動いていきたいと考えています。","id":"exchange-011"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"私が勘違いしているだけかもしれないけれども、前、品川区のコーナーのようなものをやると言っていませんでしたか。品川区全体でつくると言っていたような記憶があったのですが、そこは品川区としてはつくらないけれども、この場所に誘致するという考えでいいのかとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"誘致にあたり、相手国にはスペースの一部に、品川ハウスを併設することを条件にするつもりでおります。そこでは、品川区のいろいろな案内だとかを行うことを、そこから区内の観光に繋げていくような仕掛けができたらと考えています。","id":"exchange-012"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"品川ハウスという言葉がずっと出ていた中で、品川ハウス自体のイメージを区とし持っていただいて、新しく誘致していただいたところで活用していただきたいということを、お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"多目的ですよとしたときに、これでは使えないよとか、いろいろな話が出てきてしまうではないですか。この辺の整理は、やっていくべきだと私は思っているのですがどうお考えなのか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"多目的と言葉で言うけれども、多目的と言うには、非常に難しいと。それがいつの時点ではっきりするかというのはまだ不明ですけれども、またこれから大会組織委員会ともそういう話を実際にしていきたいと考えています。","id":"exchange-014"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"１年間の成果をまとめさせていただいたのと、大会組織委員会には持ち込むことができなかったのですけれども、要望書をまとめさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14177,"voices":42}},{"id":"h30-20180521-10","meetingId":"h30-cm05","date":"2018年5月21日","dateIso":"2018-05-21","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"議会構成等","agenda":"議会構成等","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"建設委員会が第１委員会室、厚生委員会が第２委員会室のほうに変わるというところに対してはそれで賛成なのですけれども、そこも含めて確認させていただけるとありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結構ですとの意見を述べました。","respondent":"久保田区議会事務局長","answer":"少しご説明をしますが、特別委員会の設置につきましては、臨時会で設置動議を提出し、設置するものということが基本とされております。ここの説明はそこを記したものでして、現在委員になっておられます委員の方から辞任願の提出をお願いするものです。","id":"exchange-002"}]},{"id":"topic-02","title":"第１回臨時会におけるオリンピック・パラリンピック推進特別委員の選任","agenda":"第１回臨時会におけるオリンピック・パラリンピック推進特別委員の選任","exchanges":[{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ確認なのですが、聞き漏れていたらすみません。今、所属している委員がそのまま来期も所属をする場合は、辞任届は出さなくていいのか尋ねました。","respondent":"久保田区議会事務局長","answer":"引き続かれる方もいらっしゃるのですけれども、正副委員長等の互選の関係等もありますので、一度、現委員の方には皆さん辞任していただきまして、新たに選任をさせていただきたいと事務局のほうでは考えております。","id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"要望が上がったとか上がっていないとかいうような話があったと思うのですが、その辺は現状どのようになっているのかというのを議長にお伺いしたいのと、その辺がどのようになっているのか教えてほしいと求めました。","respondent":"松澤議長","answer":"その件について事務局から何かありますか。いいですか。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"確認","question":"議会に関することで議長に確認をしたいことがありますので、よろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"「１期１年、計２期２年で辞職するので、何としても会派の中で候補者にしてほしい」という発言をされました。約束通り辞職をするものと我々会派全員は考えておりますが、今のお考えをお聞かせほしいと求めました。","respondent":"松澤議長","answer":"１年ごとに議長を辞するということを書いて、その都度１年ごとに、１年がたったときにまた改めて皆さんに可否を問うということになっています。私も今度、最終年度、しっかりと議長の職務をやらせていただきたいという決意を今述べておきたいと思います。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"約束をしたということは覚えていらっしゃる、ご自分でも３期３年はやらないということをおっしゃったということは覚えていらっしゃる。もう一度お答えをいただきたいのは、それから３期３年はやらないと言われたこと、そこだけ再度確認をさせてほしいと求めました。","respondent":"松澤議長","answer":"ですから、辞表というものは毎回毎回、会派の中ですけれども、こういう形で１年ごとに出しています。ですから、私は１人会派ですので、自分の会派の意思としてはもう１年しっかりと議長として任期を全うしていきたいというふうに思っているところです。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"関係改善をすることを考えられているとするのであれば、どのようにお考えなのかということを伺いたいと思いますが。その関係改善と、議会が今信頼関係が崩壊している状態、こういうことをどういうふうに捉えているのか伺いたいと思います。","respondent":"松澤議長","answer":"１２月３１日付をもって辞職したいと、１２月３１日付をもって辞職すると、１０月にお話をしました。そういうことは考えていません」、私は出る意思はありません」と言いましたら、除名という話になりました。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"それから前期が１期１年であり、ご自分の自らの口で３期３年はやらないと、議長の立場でどのようにそれはきちんと対応をされるのですか。質問内容について、議長個人のお考えで質問をされたのか、議会の考えを代表されて質問されたのか伺います。","respondent":"松澤議長","answer":"宿舎が大変に老朽化して、ここの建直しができないということを訴えられましたので、品川区の議長として一般質問を行いました。もう１つは、やはりこれも今、このときにやはり厩務員の福祉の向上のためにも直すべきではないですかという質問をさせていただきました。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えばいろいろ誰かから伺ったり、議長は３０年以上議員をされていて、いろいろな方からいろいろご意見を聞く。どういうことを質問をされても構わないのですが、確認をさせていただきたいのは、そこだけを明確にお答えほしいと求めました。","respondent":"松澤議長","answer":"大変に喜ばれました。以上がお答えになります。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"今お話を伺うと、厩務員の方々から言われて、公の競馬議会の中で質問をされた。私はやはりその辺の調査・調整はしてから質問をするべきだったと思いますが、その辺のところはどう把握をされているのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"ここでこれ以上そういう時間は使わないでいただきたい。議事進行動議も含めて出したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"議長に対して個人的にどういう発言をしたかということを言わせたり、自分はこう思うと、２人の間のやりとりにしか聞こえませんよね。やはり今の石田秀男委員の一連の発言は、そういうやりとりではないかと思うので、もっときちんと整理をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"私、個人的に品川区議会本会議で、一般質問で大井競馬場に敷地内にホテルを誘致するべきだと取り上げたことがあります。その手続きが必要だったのではないかという指摘を、意見として述べさせていただきまして、一旦終わります。","respondent":"松澤議長","answer":"私が２度目の議長になったので、やはり今思っている答えの中で質問をしていただきたい、今困っているのですというお話が来ました。移転ということも考える、今わかっているわけではありませんが、これを改めて見ていただければと考えています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"品川区の議長というのは公の代表ですから、どういう形で確認をされて行政はどう考えているのだ、ぜひ言っていただきたいです。質問をしたのであればその後の、そういうことはするべきだと私は思いますが、そういうことはしたのか尋ねました。","respondent":"松澤議長","answer":"今、そういうふうに言われましたけれども、私は質問をして、それについて回答をいただき、それは厩務員の方たちにお話をいたしました。これだけ何か責任をとらされるような不合理なことをしたようなことで今言われておりますけれども、これは大変に心外だと思っているところです。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"質問をすることは構いません。皆さんにわかりやすく説明をするのが、私は議長の職務であり役目だと思いますので、それはつけ加えておきます。","respondent":"松澤議長","answer":"宿舎と馬房は早く、今この時期、収支がプラスになっている時期に考えるべきではないかという質問をさせていただきました。それなりの考えができて答弁ができたのかなと思いますけれども、何か私が悪い質問をしたような、大変に心外に思っています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはいろいろなお考えがあるので、きちんと確認をしてくださいということは、そのとき議運で言いました。今ここで言われて、初めてのようにおっしゃるけれども、あのときでももう既にそう言っていたということは、よくご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、もうこの議論はやめていただきたい。こういうふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"渡部委員長","kind":"確認","question":"委員長として申し上げます。個人攻撃ではなく、確認をさせていただいているような発言ととれていますので、それはその部分であれば続けします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"この質疑はもうこれで終わりにしてほしいと求めました。そういうことはやはり本当に公正に、公平に運営をしていただけるように心していただきたいということをお願いさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"議会運営委員会ですから、お伺いしたいのが、いわゆる議会運営にとってどうなのかなと。誰がどうとか、全体の総意で皆でやろうというような品川区議会ですから、その点を丁寧にできることは丁寧にやっていただきたいなと。","respondent":"松澤議長","answer":"関係構築は、私は当然ながらできるものならやっていきたいと考えています。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１つお聞きしたいのは、もちろん締まっていないのは知っていますが、それから１年たった。現在どのようになっているのかというのをご説明ほしいと求めました。","respondent":"松澤議長","answer":"政活費の問題というのは議長が調査事項で見ておりますので、ここでそれをあからさまにしていいのかどうか、これは微妙なので、局長、何か意見ありますでしょうか。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今のお話で、我々も政務活動費のことは基本的に議長が最終的に話を伺って、当人といろいろな形でする。そうなってくると、議長が何度もお話をされたときに、西本議員はこの件に関しては返還をしないというふうに明言をされているのか尋ねました。","respondent":"松澤議長","answer":"この次の議運か何かで報告をしようかという話を局長としていたところですが、局長、それについて少し補足は何か言うことありますかね。どういうふうに答えていいのか、私も、個人の問題ですので、あからさまに言えない部分がありますので。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで、そういうふうに明言をされているのですかというのをお聞きしたいわけですね。法的なことを踏まえて、具体的にどういう理解をされて区長部局にどういうふうに話をされているのかというのをお聞きしているのです。","respondent":"松澤議長","answer":"政活費の問題で、議員の資格にかかわる問題なので、大変に難しい問題、取扱いが難しい。政活費そのものががちゃがちゃ、その辺については曖昧模糊の中では灰色の部分で、「私は灰色でおかしくないですよ」というのが西本議員の主張です。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"それについての議長の考え方をお聞きしたいのが１つ。至ったとしても現在は設置されていないわけでありますので、そこの設置されていない理由等もお聞かせ願いたいと思います。","respondent":"松澤議長、久保田区議会事務局長","answer":"局長のほうともお話をしながら詰めていきたいと考えています。局長から何か補足はありますか。 この間、松澤議長が大沢前議長から引き継ぎまして、ご本人と何度かお話をしました。年に一度、それについて来週、その平成２９年度の扱いについてはまた次回のときにお話ししようということで予定をしていたというものです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"確認","question":"それから、区長部局にも、今、訴訟を含めて確認をしているということでしょう。設置目的はどこですかということは、もちろんプラスの部分もある、中身をもう一度精査する。","respondent":"松澤議長","answer":"申し訳ないですけれども、第三者委員会をつくろうというふうな考えは持ち合わせていなかったですね。１年間、それぞれ傷つくことなく円満に解決したいということで、いろいろ苦労してきたところです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"今この時期までまるっきりつくらないで、お考えがなかったというのは、本当にいかがなものかと思います。そういうことをこの１年間全くお考えではなかったという、今、理解でいいのか尋ねました。","respondent":"松澤議長","answer":"その件については、立ち上げるということは考えていなかったと言われれば考えていなかったですね。今、そういうふうにサジェスチョンが出ましたので、早急に皆さんと諮って立ち上げていきたいというふうに思っているところです。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう１回そういうことがあればなどというのは、改めて初めてやりますと言うのは、職務怠慢とだけ言っておきます。これについて、議長は仕方がないと考えてらっしゃるのかどうか伺います。","respondent":"松澤議長","answer":"拍手の基準、その辺のところがどうも曖昧になっているので、少し躊躇するところがあります。暴言についてはしっかりとそれは注意をしているつもりです。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういう話でいいのですか、仕方ないのですか、考えているのですかと聞かれてから。それからこういう場でも、私は議長としてのそれが職務だと思っていますが、その辺のところを改めて伺いたいですね。","respondent":"松澤議長","answer":"議場の拍手、これを規制する場はないのですかね、方法はないのですかねというお話はさせていただいておりました。そういうお話をしていたということがわかると思いますので、局長、ひとつお答えいただけますか。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議長がしっかりそれは、簡単なことではないですか。それはだから職務怠慢ではないですかと聞いているわけでありまして……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういうことをしていけばきちんと運営がされていくと思うのですよ。ですから、それはもっともだということで一致できると思いますので、そういうふうに采配をとってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"今は１回か何回ぐらいしか開いていないですよね。そういうふうにしていただければいいのではないかと思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"こういうことは議長の職務であって、それをされていないということ、それが私はこういう混乱を招いているのだと思っています。４項目にわたって質問をさせていただきましたけれども、やはり辞職をしていただくべきだと思っていますので、意見だけ述べておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":30558,"voices":99}},{"id":"h30-20180524-8","meetingId":"h30-cm05","date":"2018年5月24日","dateIso":"2018-05-24","committee":"建設委員会","time":"午前１０時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ副委員長","kind":"意見","question":"長きにわたり、本当に委員会の円滑な進行にご協力いただいて、本当にありがとうあります。引き続きやっていくべきことはしっかりやっていって、住みやすい品川区をつくるため頑張っていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1869,"voices":10}},{"id":"h30-20180528-10","meetingId":"h30-cm05","date":"2018年5月28日","dateIso":"2018-05-28","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":6664,"voices":29}},{"id":"h30-20180529-10","meetingId":"h30-cm05","date":"2018年5月29日","dateIso":"2018-05-29","committee":"議会運営委員会","time":"午後 １時４５分～午後 ６時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"平成３０年第１回臨時会","agenda":"平成３０年第１回臨時会","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"「なぜですか？皆様にもご理解を頂き、議長不信任動議を可決して頂きますことをお願いし、提案説明としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはご確認ほしいと求めました。何度もこの前もお話ししましたが、議長ですから質問をすることは全然権利がありますし、構いませんと何度も言っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"信頼関係が崩れているのは、自民党会派であり、その関係だけではないのでしょうか。よって、自民党・子ども未来が提出した議長に対する不信任動議には、反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"最初の２期２年にこだわっているということは、３年目はやらないので、候補としてほしいとおっしゃった。それは我々から言ったことではないということだけをつけ加えさせてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"全然今は関係ないではありませんか。こんなルールを持ち込まないでほしいと求めました。","respondent":"松澤議長、久保田区議会事務局長","answer":"共産党の認識も言っていただきましたけれども、議長不信任であるとか何とかという話をされるのは、大変に心外であると思っています。１年、議会改革… 採決は前回同様、無記名投票による実施を考えているところです。可否議決の後に、一旦本会議を休憩する予定ですので、この点につきましてもご了承いただければと思います。","id":"exchange-005"}]},{"id":"topic-02","title":"ほかにございますでしょうか。よろしいでしょうか。 それでは、議事の進行につきまして、追加議事日程(3)","agenda":"ほかにございますでしょうか。よろしいでしょうか。 それでは、議事の進行につきまして、追加議事日程(3)","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほどの件に戻らせていただきたいのですが、１点だけ議長に確認をさせていただきたいのですけれども、よろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"改めて議長に確認をしたいのが、これまで第１会派自民党と関係改善をしてほしいといった中で、自民党会派にいたときは議長を１年やらせてほしいということで。","respondent":"松澤議長","answer":"これは、もう１年やってもいいですよという証左だと考えています。そんな意味で、私はもう１年、しっかりと品川区議会、頑張ってまいりたいと思います。","id":"exchange-007"},{"speaker":"本多委員","kind":"確認","question":"ただいまの事務局長の報告につきまして、議長に確認をしたいと思います。全てにおいて議会で取り上げる事件が議決をされたという重みについてどうお考えか、それと、改めてその点をお聞かせほしいと求めました。","respondent":"松澤議長","answer":"議決されましたこと、本当に私としても、青天の霹靂なのですけれども、これは議会意思がそうなったということで、これはしようがないと考えていますけれども、議長としては、１年しっかりと頑張って、議会の運営に努めてまいりますので、よろしくお願い申し上げます。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14091,"voices":51}},{"id":"h30-20180611-6","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"区民委員会","time":"午後 １時００分～午後 ３時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"戸籍住民課では証明交付係が３名増えている。この配置の考え方というのですかね、今年の主な施策というのですか、配置にかかわって伺いたいと思います。","respondent":"伊崎地域活動課長、山崎商業・ものづくり課長、提坂戸籍住民課長","answer":"今、るる担当のほうから説明したところですが、特に事業の大きな改変によって人の増減があったということはございません。あるいは… 商業・ものづくり課につきましては、先ほど説明させていただいた、事業の人数としますと増減はなくて、内訳として変更がありました。… 証明交付係が３名増えているということでございまして、平成２９年度の組織改正を受けて、合計３名の増となったものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"昨年より２０名増えているということで、一番大きいのがオリンピック・パラリンピック準備課で、先ほども３名増えていると言っておりました。昨年は多分ゼロ人だったと思うのですけれども、これが一気に１１名になったということの、配置の関係でお聞きしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２年ともう迫っている中で、より品川区の当課と派遣者との連携を深めて進めていこうということで、増えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、人数は昨年も１１名で変わらないと考えてよろしいのでしょうか。２年ということで、施策反映に向けても、今年新たに力を入れたということになるのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの区役所に勤務する者としては、正規職員２名と非常勤１名の３名が増えております。派遣者に関しては、変わりはないです。","id":"exchange-003"}]},{"id":"topic-02","title":"品川区文化芸術フォーラムの開催","agenda":"品川区文化芸術フォーラムの開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"寺田倉庫というのが、ほかのを見ているとちょっと異質な感じがするのですけれども、伺いたいと思います。オール品川で取り組んでいくということですけれども、まだ登録されていないところが新たに登録することはできるのか尋ねました。","respondent":"立川文化観光課長","answer":"こちらは昨年度準備会を実施しておりまして、そちらに約３０の団体が参加していただいているところですので、大体３０前後で開催することになります。それから、３のこれから新たに登録できるかですけれども、一応新規に協議会に加わりたいというご要望があれば…","id":"exchange-004"}]},{"id":"topic-03","title":"平成３０年度文化センター等工事による休室予定","agenda":"平成３０年度文化センター等工事による休室予定","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今回するのとは別だと思うのですが、そのときに空調の改修とかは一緒にできなかったものなのでしょうか。こういうのは計画的にやっていったほうがいいと思うので、その辺についてはいかがか尋ねました。","respondent":"立川文化観光課長","answer":"その辺が主な内容でございまして、今回どういった空調機の改修かといいますと、そのときにプールの空調機は改修しなかったです。今回のプールの空調機の改修ですが、これを改修することによりまして、現在湿度調整というのがなかなかうまくいかないところをかなり改善できるです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"意見","question":"そういう答弁なので、私の記憶違いだったのですね。わかりましたとの意見を述べました。","respondent":"立川文化観光課長","answer":"平成２８年度は、プールの消毒装置交換等工事を実施しているものです。ということでございまして、空調につきましては、今回実施するです。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"ここまではしようがないとして、これからこういうことはあり得るのですか。来年とか、「何だ、去年一緒にできたではないか」とか、そういうことがあるかないか、これは多分地域の関心事なので、その辺だけコメントをください。","respondent":"立川文化観光課長","answer":"設備によっては、突発的に故障することもございまして、計画的に改修ができない部分もあります。改修についてはなるべくまとめて実施することが、利用者の皆様のためということで、そういった方向で考えていきたいと思います。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"結果的に高くつく、あるいは本来提供すべきサービスがもっと早くできたのにとか、こういうことはあると思うのです。こういうことは現在議論の中にあるのか、少しでもあるのか、ないのかだけ説明を求めました。","respondent":"安藤文化スポーツ振興部長","answer":"そういうのは実施しますけれども、そういう考えでもって、計画的にやっているところです。そういうものを行いながら、長くもたせていこうというのが、今の私どもの考え方です。","id":"exchange-008"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"自民党として２点リクエストというか、提案したいと思います。これも２０２０大会に向けて、あるいは消費者センターの観点と両方あるかと思っていますので、その２点をリクエストしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"浅野副委員長","kind":"意見","question":"中小企業支援という観点でできないかと考えています。二、育成していかなければならないのかなという気持ちになっておりますので、中小企業支援はどうかなと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"意見","question":"いただいた所管事務調査の資料を見ると、スポーツのことについての所管事務調査があまりなかったので、オリンピック・パラリンピック推進特別委員会との仕切りの問題はありますが、そこを日常的なスポーツということでできないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"どういう手段で行くかといったときに、台風の時期ですから、飛行機はあまり。少し考えてくださればという思いで発言させていただきました。","respondent":"本多委員長","answer":"今年は９月３０日に区長選挙が予定されている関係で、または９月１０日の週、どちらかでの実施が濃厚であります。ただいま申し上げた日程の中で、２泊３日で実施するとした場合に、ご都合の悪い日がある委員はいらっしゃいますでしょうか。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2810#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":37050,"voices":81}},{"id":"h30-20180611-7","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"厚生委員会","time":"午後 １時００分～午後 ４時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"策定委員会の公開も求めてきたのですけれども、これがされるのかどうなのか、議会への報告はいつごろされるのかというのを伺いたいと思います。人を支援するわけですから、なぜ人数を減らしていくというか、軽減するということが改善できないのかということを伺いたいと思います。","respondent":"大串福祉計画課長、松山障害者福祉課長、矢木生活福祉課長","answer":"最初の１時間ほどはこちらからの説明ですとか、後半の１時間につきましては第２部という形で、そこでご意見をいただいたという形になっております。当然… 基幹相談支援センターは、障害者福祉課の中の障害者相談支援担当の９名ということで行ってあります。なので… 直近のケースワーカー１人当たりの担当世帯数ですが、４月末現在が直近でございまして、こちらについては１１１世帯ということになってあります。…","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこが組めないと、そこが２名だけになっているという現状を、区としてはどう考えているのかというのを改めて伺いたいと思います。十分な制度の調査とかも、ぜひこの人員を増やすということに力を注いでいただきたいと思うのですけれども、いかがか尋ねました。","respondent":"松山障害者福祉課長、矢木生活福祉課長","answer":"委員ご指摘の、２７０件ほどを２名でやっている計画相談なのですが、障害者の計画相談については、現状としては課題だと捉えております。今後、区だけではなく、民間の事業所等も含めまして… 答弁の繰り返しになってありますが、なかなか区全体のところでございまして、早急にどうこうということができないというのが実情です。例えば週に１度の係長会で最新の技術、研究を進めまして…","id":"exchange-002"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林委員","kind":"意見","question":"それから健康については、３歳児の視力検診について、子どもの歯科矯正について。障害児者については、福祉タクシーについてなどですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ここの充実を求める声が強い分野かと思っていまして、サービスの支給量とか、そういったことを調査できたらと。品川独自の独特なやり方というところでは、なかなか見えてこないので、そういったところも調査研究していきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"若林委員","kind":"意見","question":"支え愛・ほっとステーションの第２層協議体、今後ますます、さまざまな地域の保健関係のデータも地域ごとに分析できるという環境ができてきた。今、ほかの自治体でぼつぼつやっていますけれども、研究をしてもいいのかなという思いで何点か取り上げさせていただきましたとの意見を述べました。","respondent":"石田（秀）委員長","answer":"次回７月の委員会で提示をして、決定をしていきたいと考えていますので、ぜひよろしくお願いいたします。〔「はい」と呼ぶ者あり〕","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":63056,"voices":72}},{"id":"h30-20180611-8","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"建設委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"建設委員会副委員長を務めします、国民民主党・無所属クラブの松永よしひろです。委員会運営にしっかりと取り組んでまいりますので、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"都市環境部と防災まちづくり部ともに事業も多いですし、あと性格も違いますので、できれば事務事業概要の冊子も分かれていることですので、説明と質疑はぜひそれぞれの部ごとに行っていただけないかなと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"品川区としては、超高層によるさまざまな弊害、課題というのはどう考えているのかなと改めてお伺いしたいなと。課題というのをどういうふうに考えているのか、課題はないと考えているのか、そこら辺をお伺いしたいと思います。","respondent":"鈴木都市計画課長、稲田都市開発課長","answer":"その中でご審議いただくですので、今のところは全て公開という形ではございませんが、適宜適切にやっていきたいです。 そういう中におきましては、そういうものに対しても事前に検討して、また事後もその効果等を測っていくというようなところもあります。道路等々についてしっかりとした都市基盤を考えながら…","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はすごく大事な観点だと思うので、それぞれの事業でもしあればお伺いしたいというのが３点目です。そこら辺はいかがでしょうかというのが４点目です。","respondent":"鈴木都市計画課長、稲田都市開発課長、高梨木密整備推進課長、東野まちづくり立体化担当課長","answer":"ひいては区民、そういった方々への移転の説明ですとか意見の聴取ですとか、区民の方に説明をしていくというところで進めているところです。それから… これを皆さんが集まって建物を強化して空地をつくりながら広場や道路をつくって、防災上の安全・安心をつくっていくです。… 住民の方々にも参加していただく検討会や協議会を立ち上げて、整備計画であったりまちづくりの方向性等を議論していきたいと考えております。… これまでも中央新幹線に関する説明会等につきましては…","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺、どう考えているのかというのをお伺いしたので、そこら辺はちょっとぜひ改善していただきたいのですがいかがでしょうか。もしどうしても入れたいというのであったら、入れるメリットは何なのですかというのを具体的に聞かせていただきたいです。","respondent":"鈴木都市計画課長、稲田都市開発課長、藤田防災まちづくり部長","answer":"その計画策定に基づく審議会の設置、広く区全域にかかるようなものは広く隅々まで区民の方に届くような公表の仕方ということがあろうかと思います。… 鉄道自体も埼京線が乗り入れたり、鉄道事業者も大崎駅の対応について今後さらに議論をしながら安全な駅等にしていきたいという考えがあります。… 建設委員会としては、私どもとしてはさまざまな研修も含めて、経験を通じてのものであると考えています。総合的に勘案しての採用ということで考えてありま…","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺、目黒川の対策についての決定的なところはどういうふうに考えているのか、お伺いします。ですから、このソフト対策のみで十分なのか、課題を伺いたいと思います。","respondent":"たけうち委員長、藤田防災まちづくり部長、持田河川下水道課長、古巻防災課長","answer":"先ほどの人事の件は、基本的には総務委員会マターになりますが、建設委員会の中で可能な範囲でもしお答えがあればお願いいたします。 先ほども申し上げましたけれども、国民保護としての観点のさまざまな研修も含めて経験を通じてのものと感じているところです。最終的には… 過去にいろいろと検討がなされておりまして、もう一方で、雨が降ったときに下水道からの越流水という形で有機分の多い水が流れ込んでくると。… 先ほども事務事業概要の説明の冒頭で申し上げましたけれども…","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"これからの進め方についても確認したいので、広がったのはわかるのですが、改善も含めて検討をお願いしたいなと考えています。今こういうところになっていてというお話があってもよかったのではないかなと思うのですが、これからの仕切りについてお伺いしたいと思います。","respondent":"たけうち委員長、小林環境課長、今井土木管理課長","answer":"大体概略が固まってくる段階段階を見まして、正副で調整して必要に応じて報告はしたいと考えております。この後進めていく中で… 私からはＥＣＯフェスの件についてのご質問にお答えします。今年度から拡張してイベントを実施したところですが… シェアサイクルにおきますほかの自治体との連携ですけれども、共同事業という形で各区で連携して取り組んでいるところです。実際には…","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"行革での審査内容は、やはり皆様の情報の共有というのですか、そういうスタート時点での議論というのが必要になってくるかなと考えていますので。それを含めての報告事項、もしくは議論という形にしていただきたいなと思っていますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"}]},{"id":"topic-03","title":"立会川雨水放流管工事（東京都下水道局施工）","agenda":"立会川雨水放流管工事（東京都下水道局施工）","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点だけお願いいたします。「立会川流域の浸水被害に対するさらなる安全性の向上を図る」とあるのですけれども、詳細はどのような形で安全性が向上されるのか説明を求めました。","respondent":"持田河川下水道課長","answer":"そういったことから、設計のほうは内容を少し変更しまして、より大きな施設をつくりたいと。このために工事期間が少し長くなってしまうといった説明が区のほうにあったです。","id":"exchange-009"}]},{"id":"topic-04","title":"「震災時火災における避難場所等の指定（第８回）」の公表","agenda":"「震災時火災における避難場所等の指定（第８回）」の公表","exchanges":[{"speaker":"西本委員","kind":"質問","question":"変更になっているところに対する告知というのはどういうふうにされますか尋ねました。","respondent":"古巻防災課長","answer":"先ほどもご説明したとおり、まずホームページや広報でも掲載しますけれども、該当の町会の回覧板および掲示板で周知を行っているほかに、今現在既に行っておりますが、各町会の町会長会議等に出向きまして、防災課から直接説明をしています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"継続的な告知というかお願いを機会ごとにぜひしていただきたいですし、避難所訓練が毎年行われると思うのですね。ここはぜひ告知をしていただいて、認識度を高めてほしいと求めましたが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"周知につきましては、確かに浸透するということが重要だと考えておりますので、十分に周知が進むように繰り返し周知を進めていきたいと考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"今回８回目ということなのですけれども、これって何年に１回見直しとかそういったルールがあるのかどうか伺います。区民の声の反映というのですか、地元の自治体としての意見というのはどのように変更に反映されていくのか、そこら辺をお伺いしたいと思います。","respondent":"古巻防災課長","answer":"前回が平成２５年でしたので、ほぼ５年たった平成３０年ということで見直しがかかったと認識をしております。そういった中で地域の方からの声も含めて東京都に伝えて、地域の声をなるべく反映するような形も考えていきたいと考えております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"都有地があるのですが、そこの取得手続が済んでいないのですが、今回その目標は解消されたということになるのでしょうか。伺いたいと思います。","respondent":"古巻防災課長","answer":"基本的に東京都の被害想定に基づく震災の類型がありますので、そういった中で火災が起こる状況も勘案しながら、指定を進めていると考えております。有効面積が１人当たり１.１３平米ということで改善をして１平米以上に確保ができることになったということで報告を受けておりま…","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"もう少し伺いたいのと、どういうイメージでどういうときに広域避難場所に行くのかというのをご説明をもう一度ほしいと求めました。西大井のあたりとか戸越ですか、そこら辺、大井競馬場。","respondent":"古巻防災課長","answer":"結果としてそうなるですので、それを情報としてきちんと区民にお伝えをして避難をしていただくということが前提になろうかと思います。徐々にそういったところの避難の距離が短くなる…","id":"exchange-014"}]},{"id":"topic-05","title":"の４、その他","agenda":"の４、その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身なのですけれども、そこで児童相談所というイメージがあったものですから、なぜそこの真ん中になったのかというのをお伺いしたいと思います。どのような機能を持たせる、どういう施設を整備するという考えのもとに所管課と話し合いがあったのかということを教えてほしいと求めました。","respondent":"溝口公園課長","answer":"今後無償で寄付をいただける土地を含めて計画・検討したところですが、そういったことも考慮して今回赤いところでの整備と考えているものです。今後詳細設計を進めていく中でさまざま検討していきますが、引き続き楽しんでいただけるような公園にしていきたいと考えているもので…","id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"かなり区民に親しまれている公園ですので、なかなか実際に具体化していくとなるとさまざまな意見が出てくるのだろうなと予想はしております。そういう中で、その点でどういう形でどういうふうな方法で周知をしていきながら進めていくお考えなのかというのをお聞かせほしいと求めました。","respondent":"溝口公園課長","answer":"そういったものも考えて進めていく中で、または近隣の声、そういったものを聞きながら進めていきたいと考えております。しっかりと住民説明会、またそういったところでの区の計画に対する考え、しっかりとこの事業計画を進めていきたいと考えているところです。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは７０年代ですか、私も実は前々からおつき合いがあるところでびっくりしたのですけれども。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"そこら辺の、なぜこの公園になったのか、そこのほうをもうちょっと早い何かができなかったのだろうかなというのはちょっとあった。それをなるべく維持した形でという思いもあるものですから、そこら辺は何かご存じであればお願いいたします。","respondent":"溝口公園課長","answer":"国のほうもその５年間についてはしっかり支援をしていく。どういう形で土地を取得していくのか、または土地を取得していかないのか、そういったところもいろいろさまざま検討していたと聞いているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"ちょっと確認といいますか伺いたいのですが、少年野球場もありますし、あと向かいが品川学園ということもあります。何か相談とかしたのかどうか、それぞれについて伺えればと思います。","respondent":"溝口公園課長","answer":"学校、今後、先ほども説明会とかをやりながらということで事業を進めていきたいというお話をさせていただきました。ご意見を聞きながら事業を進めていきたいと考えていますし、所管のほうとも十分その辺は連携しながら進めていきたいと考えているところです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２６号線の開通が予定では今年度末でしょうか、道交法も変わりましたし、あとは駐輪場の問題等もまだまだあります。特に保険の問題ですとか自転車というものについての品川区、品川区議会の考え方をもう一度確認をし認識をしていく必要があるということで。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"それにもう一つ加えていただきたいのは、ここのところは今後２０２０を含めたインバウンド対策として重要な位置づけをなされるものではなかろうかと思いますので、水辺のまちづくりを自民党としてはそれにプラスをしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"交通政策というのも私たちも何度か一般質問でもやらせていただいていますが、区内の中を移動するというところが不便だという声が結構聞かれます。自転車も大事ですが、そういった意味で自転車も含めてそういった地域交通というのは私たちも調査をしていいのではないかと考えております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"インバウンド対策としても品川区の水辺を活かしたまちづくりということをぜひやっていただきたいと考えております。以上、大きくこの３項目をぜひよろしく申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"水辺の活用もぜひお願いしたいなと考えています。羽田空港の機能強化については、しっかり取り組んでいかなければならない項目ではないかと思いますので、この３つをお願したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"松永副委員長","kind":"意見","question":"２つ目は、先ほどおっしゃっていたような防災対策についてお願いしたいと思います。今後の人口動向を見据えて、ぜひその辺も含めて今後のことも考えていただければということで、公園の利活用についてということを述べしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"大沢委員","kind":"意見","question":"希望としては３日を外していただいたほうがいいと、私、自民党とあくつ委員はそういうふうに思っておりますが。は皆さんのご意見と役所の理事者の方のご都合等々いろいろなものが絡み合っておりますので、それはお任せしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"安藤委員","kind":"意見","question":"私はよく視察内容も精査して、２泊３日ありきでなくて１泊２日でも私はいいのではないかと。私はそういったことも勘案すると、１泊２日ということもありなのではないかという意見ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"大阪市の北浜テラス、包括的に河川敷を占用して飲食店等を継続して行っているというところで非常に有名なところなものですから、ここが一つ。今回、２０１１年には環境未来都市というところで選出をされていて、環境という視点で視察ということで３点挙げさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"意見","question":"やはり羽田の関係でしっかり委員会としてもどういう実態なのかというのはきちんとさまざまな角度から調査したほうがいいと思いますので。大阪市も実は飛んでいますから、ただ、大阪側のほうも影響はあると思うのですが、豊中市ということでどうかなとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"なぜかというと、ここにもありますように、以前視察が中止になった経緯がありまして、当委員会でも台風の影響で視察が中止になった経緯があります。この神戸市の防災対策についてと、同じく兵庫県の加古川市の自助・共助による防災のまちづくりについて、これを２点入れてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"松永副委員長","kind":"意見","question":"私からは、水辺のことで先ほど大阪市の北浜テラスというところもあったのですが、もう一点屋台のほうで、福岡市の屋台文化はどうかな。〔「屋台あるのかな」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"松永副委員長","kind":"提案","question":"まだありますね。平成２５年７月に福岡市屋台基本条例というのが制定されまして、ちょっとそういったところも含めて視察してはどうかということを提案しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4234#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":51683,"voices":140}},{"id":"h30-20180611-9","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"文教委員会","time":"午後 １時００分～午後 ４時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"南委員","kind":"意見","question":"日本共産党品川区議団の南恵子です。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ここはどういう状況か、改めてこの数字を伺いたいと思うのです。合計では２１.２％、そんなに大きな数字の差ではないと思うのですけれども、落ちている状況がどういうことなのか教えていただきたい。","respondent":"熊谷指導課長、大関教育総合支援センター長、篠田学務課長","answer":"昨年度の９月５日に学校働き方改革、しながわ働き方ルネサンスの実施についてという通知を全校に通知いたしました。新たに加えるところとしましては… 小学校で４６、中学校、義務教育学校の後期課程も含めまして１４９という数字になっております。それから、若干、そこの分が抑えられている状況です。 小学校・義務教育学校、前期の課程が平成２９年度は１８.３％と落ちています。それと合わせた形だったものですから、結果的には…","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうところとの関係で、学校働き方改革をどう見たらいいのかと私は感じたので、その辺の評価を伺いたいのが１つです。その辺についての見解を伺いたいと思います。","respondent":"熊谷指導課長、大関教育総合支援センター長、篠田学務課長","answer":"必要に応じて、時間単価で、報償費としてお支払いをする職員です。用事等があるので、それに応じて学校がそれぞれアシスタントを募集して… それに次ぐ内容としては、例えば学業不振が２０％台で出てきている状況で、また、同じく２０％台では友人関係の悩みなども出てまいります。… 固定ではなくて、常に見直しをする必要はあるという思いはありますけれども、現状の制度の中で必要な援助はできているものと考えています。今のとこ… 確認をいたしましたけれども、昨年度に比べて…","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"非正規がどのくらいいらっしゃるのかわからないので、ぜひ、その辺の表記をしてほしいと思うのが２点目です。例えば４２ページのいじめ防止等の対策のところも、概要をもうちょっと膨らませていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長、有馬庶務課長","answer":"基本方針、しっかりと正しい認識を深めていこうということで、さまざまな偏見をなくそうという単元があります。例えば５年生においては、そこで実際に性自認に関する内容等も出てまいりますので… 他部局の記載方法等の確認をしながら、またその辺は検討をしていきたいと思います。全体を見ながら、来年に向けて、内部でも検討はしていきたいと思います。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"図書館で取り組める状況を一歩も二歩も進めていただきたいという思いがあるので、そこを１点、お願いしたいのが１つです。ぜひ検討をしていただきたいのですが、具体的にさっきの２点は質問をしたので、数字がわかっていたら説明を求めました。","respondent":"熊谷指導課長","answer":"最初は１２名おりまして、現在７名ということで、５人が復職しています。ただ、これはメンタルだけではなくて、大きな罹患ですとか、そういった疾病も含んです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一点は、いじめの相談とかメールとか、そういった具体的な数字がわかっているのだったら、状況を教えていただきたい。","respondent":"大関教育総合支援センター長","answer":"平成２９年度は４７件の目安箱の対応をさせていただきました。延べの件数となりますけれども、１人の方で何十回というケースも含めてですが、実際には２,０００件を超える学校への支援を行ってあります。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"私、まだそんなにやっていませんけれども。直近のことは人事課に聞かないとわからないか尋ねました。","respondent":"有馬庶務課長","answer":"事務局内の職員の時間外については、我々でも把握はしています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"教職員の方ではなくて、教育委員会の事務局のところがわかれば教えていただけたらと思います。月８０時間以上の職員が何人中何人いるのかという割合でお願いします。","respondent":"熊谷指導課長、有馬庶務課長、篠田学務課長","answer":"指導課は２４名おりますけれども、４月分になりますが、８０時間超えが３名おりました。 指導課は超勤が多い傾向があるのですけれども、ほかの課はそれほど多くないとは把握しています。庶務課は今、データがないのでわかりません。 今は手元に今年度分の数字はないのですけれども、８０時間を超える職員はいなかったと記憶しています。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"今後、どのような形が考えられるか、教育委員会としてのお考えを伺いたいと思います。今年度の結果については、何らかの形で教育委員会の会議で公表した内容を示すべきだと思いますが、いかがか尋ねました。","respondent":"有馬庶務課長、熊谷指導課長","answer":"一定程度の教育に関する考え方を確認しながら、またそれを教育委員会の中でも検討していくところに大きな意味があるのではないかと考えております。子育て全般に係るものですとか、もう少し幅広くやっていくことも、今後… 校区教育協働委員会で協議しながら、そして、学校支援地域本部の力をかりながら進めていくことが重要なのではないかと考えています。今年は２年目になってまいりますので、今後の公開の仕方ですとか…","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"意見","question":"単純に何時間働いたら超勤かどうか、果たして学校がやるべきことは何なのかを地域の方々とお話ししていく場面をつくることが大切だと思っています。それから、最後の学力定着度調査は、しつこいようですけれども、ぜひ公開に向けてお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"最初のセクシュアルマイノリティの生涯教育に関して、図書館について取組みをお伺いしたので、具体的に。書籍の選択なども影響してくると思うので、その辺の取組み、あと、イベントとか何かがあったら説明を求めました。","respondent":"横山品川図書館長、大関教育総合支援センター長","answer":"昨年、ご質問がありましたＬＧＢＴの本につきましても、これを選書するという目標ではないのですが、一般選書の中にあるものがあります。定例の中で特に取り上げてしているのではないのですが、トピックスとして… 全校の教員に対して、本年度も引き継ぎ、性自認等の悩みを抱えているお子さんに早期にきちんと気付いてあげられる環境に努めてあります。いじめだけではなく、不登校等、全ての課題への支援を行っている数値を合わせたものです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に、今言っていただいた教職員の方々の研修はものすごく重要であるので、ぜひ力を入れてほしいと求めました。実際に体験しなくても理解できる大人の方はいっぱいいらっしゃるので、ぜひ図書の充実とか取組みをいろいろやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"その辺を見抜く力をどうしたらいいのかを伺っておきたいと思うし、これ以上、どこの行政区に住んでいても。ですから、改めて伺いたいし、考え方を教えていただきたい。","respondent":"高山子ども育成課長","answer":"１点目の親育ち支援事業に関連しての対応とか認識の部分、記載の親育ち支援事業につきましては、親同士の交流が深められればということでの事業です。運営者側の負担もありますので、そうした部分の調和がとれた段階で…","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今の子どもたちは、そういう場面をたくさん提供しないと、今の子どもたちに手足あるいは体全体を使った心身機能の発達は促せないわけですから。そのことは要望としてお伝えさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"２点目は、職員の健康管理の項目が見つからなかったのですが、その辺の把握がされているのかどうかが１点。超過勤務のところで、先ほどと同じ月８０時間超えの職員が何人中何人いらっしゃるのかを説明を求めました。","respondent":"福島子ども未来部長","answer":"職員の健康管理につきましても、今回は事務事業概要の説明ですので、そういった職員のことに関しては、今回のご報告ではございません。事務事業の内容についてご説明申し上げておりますので、超勤８０時間超えにつきましても、よろしくお願いいたします。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ほかの場所で伺うこととします。そこから何を何人ずつ引くと、この１９人の待機児数になるのか、基本的なところを教えてほしいと求めました。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"待機児童対策の関係で定員弾力化を進めるようにという通知も来ていますので、その考えに沿って、区も行ってあります。課内でも検討課題に上がっておりますので、今後、子ども・子育て会議等でさまざま検討してまいりたいと考えておりま… 不承諾数と待機児童数の関係ですけれども、不承諾数７０６人から転園希望の方、求職活動を休止された方、認可以外の保育施設に入られた方、特定の保育所のみを希望している方、育休を延長された方を除いて、待機児童１９名となります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"定員以外に弾力化も可能と伺ってきていると思うのですが、計測する園の面積は、保育室だけなのでしょうか。基本的なところを教えてほしいのと、私は、人手が足りないのではないかと思っているのですが、いかがか尋ねました。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"２月、３月末のパーセンテージに関しては、大きく変わっていないと認識しております。平成３０年度から、十分、回れる体制だと考えております。 ６月の申請者数は、今、数を持っていません。ゼロ歳から２歳児の認可、空きが１７５人ありますので、申し込みがあっても対応できる体制にはなってあります。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６月１日現在の数字は、多分、すぐわかると思うので、ぜひ、後で教えてほしいと求めました。率直にご意見を聞かせていただきたいし、強力に応援をいたしたいと思っていますが、いかがか尋ねました。","respondent":"佐藤保育課長","answer":"そこを２つに分けていますので、今までそれぞれ仕事を重ねてやっていた部分を完全に指導検査は指導検査と注力できるようになったのが２点目です。その辺を進めて、園長ＯＢ６名を指導検査、かなり体制としては拡充したと考えております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"済みません。６月１日のは後で教えていただけるのか尋ねました。","respondent":"佐藤保育課長","answer":"わかりました。","id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"これは文教委員会ではなくて行財政改革特別委員会なのだろうと思うのですけれども、改めて、この機会なのでできたら教えていただきたいのが１つです。〔行財政改革特別委員会の調査事項」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問","question":"例えば、先ほど他会派の中でもありましたけれども、命の教育というのでしょうか。限られた時間での発言となってしまったものですから、まだ具体性に乏しいところがあるのですが、そのような点で１点。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"私たちも視察を含めて確認している中で、命にかかわるわけですけれども、そういうところです。今までは量的な部分の緊急性があったわけですから、平成３０年度初めの数字を見ても、一定程度の数の拡大は必要だと思うのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"私的には、１つは、先ほども事務事業概要の中で質問させていただいた学校の不登校の問題です。私はそう思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"意見","question":"２つになってしまうのですが、健康という意味では、心の健康に通じると思うのですが、性の多様性を認めていく教育。私は、とても遅れている分野だと思うので、議員みずからが学んでいくことが大事ではないかと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（し）委員","kind":"提案","question":"私どもの会派からは、１つは次世代教育について。特に在宅の子育て支援についてと子どもの貧困について、ネウボラについて、このようなものがいいのではないかと提案をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"意見","question":"具体的に、例えば大阪市などでは、コミュニティ・スクールの財政的な面で進んでいるところの研究をと思ったりしました。どのような施策がこれからさらに拡大できるか、あるいは、整理していけるかを調査したいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"去年でしょうか、広島、長野連名で出されているのです。そこがいろいろおもしろいこともやっていると思って見ていましたけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"渡部委員","kind":"意見","question":"まだ確実に追いかけてはいないので、大学院の研究がおもしろいことをやっていると思って見ていました。基本的には、行きたいところというよりも、必要なところを探していただいて、ある程度、正副委員長にお任せしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、別に遠方でなくてもいいわけで、そういうところも取り上げていただいて、そういう教育行政を学んでいきたいと思っています。だから、学ぶところはあると思いますので、検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"意見","question":"結構、あちこちの県段階で、その先の具体化が進んでいるところがあるのです。具体化をしているということなので、ぜひ、進んでいるところに学びたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4942#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":53353,"voices":116}},{"id":"h30-20180611-5","meetingId":"h30-cm06","date":"2018年6月11日","dateIso":"2018-06-11","committee":"総務委員会","time":"午後 １時００分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"その辺をしっかり指導といいますか、担当所管からこうやるのですということをやられているのかどうなのかだけ確認させてください。平成２９年度の実績が、区民の悩みをまさに解決するためにこういう事業をやられているわけですから、この後は追っているのかいないのか。","respondent":"榎本総務部長、木村報道・プロモーション担当課長、中元広報広聴課長、小林施設整備課長","answer":"総務部の事務事業概要の内容に統一がとれていなくて済みません。できる限り予算額等は記載していきたいと考えています。 委員おっしゃるように、やはりそれぞれの施設で温度差が生じてあります。こういう形もあるという運用状況をまさに指導とおっしゃいましたけれども… 専門相談、１８ページに品川区の広聴・情報公開という項目を出していますが、運用状況などをまとめた記録を毎年つくらせていただいております。… 事務事業概要の９ページについては、今後、単位を千円で統一するようにいたします。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ただ、プレス発表には必ず全部予算額が出ているわけですから、やはりしっかりと予算額を載せていただきたいという思いがあります。これから来ようとしている方の中には、敷居が高いなと思っている方もいらっしゃると思うので、いろいろと考えてやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今年、策定を行う長期基本計画と、「マイセルフ品川プラン」について伺いたいと思います。あわせて策定に向けた策定委員会が始まると伺っていますけれども、どのように考えているのか伺いたいのと、それぞれ説明を伺いたいと思います。","respondent":"大野計画担当課長","answer":"策定委員会の構成につきましては検討、平成２５年度の改訂時には、区議会議員の皆様にも一定数ご参画いただいておりました。今回につきましても、人数につきましては未定となっていますけれども、参画をいただくといった方向で検討を進めているところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後、議会を含め、多様な民意が反映するような構成にしていただきたいと要望しておきたいと思います。伺いたいのは、どのように考えているのか伺いたいのと、今後の計画をあわせて伺いたい。","respondent":"島袋人権啓発課長","answer":"事業を発展させていきたいと考えているところですし、また、策定委員会の中からもいろいろなご意見等が上がってくるかと思います。そちらを生かしながら計画に反映させていきたいと思っているところです。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"１つは、概要ですから、そうなると相互に矛盾が出てきてしまう。この間、職員のいろいろな相談窓口については人事課だと思うのですけれども、その中で職員厚生係が担当と理解してよろしいのか尋ねました。","respondent":"立木経理課長、品川財政課長、黒田人事課長","answer":"こちらはまたきちんとそれぞれ連絡を取り合いまして、表記に齟齬がないように配慮してまいりたいと思います。そういった形で… どうしても予算書は事業別、片や事務事業概要は実際の業務ですので、１つの業務において２つの事業が絡み合って出てくる場合もあります。… 職員厚生係に加えまして、人権啓発課の男女共同参画担当、３つの係長が窓口です。そのほかに、そちらのほうにご相談いただきまして… 済みません、ちょっと混乱しておりまして、先ほど、答弁で誤った回答をしてございました。保育園の敷地等…","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"では、事務事業概要に書いていないのは、ここのところ事例がなかったからと理解していいのでしょうか。ごめんなさい、よく理解できていないのですけれども、貸出についても経理課というふうに思ってよろしいのか尋ねました。","respondent":"立木経理課長","answer":"貸出に関しましては、こちらのほうに記載がございませんが、特になかったということではございません。記載がないだけです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"借入と貸出が常にセットというか、同じところに表記されていると大変わかりやすいので、ぜひ検討をお願いします。で教えてほしいと求めました。","respondent":"伊藤委員長、山本情報推進課長","answer":"ほかになければ、以上で事務事業概要を終了いたします。 １０月に第３回ワークショップとして、第２回のアイデアを実現するためのアプリ開発を行い、１１月に第４回としてアプリの実証実験を行う予定です。それぞれのワークショップにつきましては…","id":"exchange-007"}]},{"id":"topic-02","title":"平成３０年度オープンデータ推進事業の実施","agenda":"平成３０年度オープンデータ推進事業の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどのご説明の中で、オープンデータを活用して６種類の試作アプリが完成したとおっしゃいましたでしょうか。その６種類の試作アプリは、それぞれどういう内容のものなのか、ご説明ほしいと求めました。","respondent":"山本情報推進課長","answer":"もう１つが、商店街の個人商店単位で、なかなか取り組みが行いにくい店舗の魅力的な情報を発信するツールです。残りの３種類ですけれども、サイコロを使いながら自分の将来を考える大人の会話のきっかけづくりのツールになります。","id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、月見橋の家が仮移転しているということでありますが、同和相談員など同和事業は廃止し、解同品川支部への総務部分室の貸出をやめ、月見橋の家は建て替え後、もとに戻さず、同和生活相談は特別扱いせずに、区民相談の各種相談事業での対応に変えるべきだと思うのですけれども、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"工事の移転後に、またもとの場所に戻るのが、今後の移転の計画です。今のところ聞いてありますのは、仮移転からまたもとに戻るという計画であるというふうに聞いております。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"人権啓発課が報告をするのであれば、内容は同和事業に関することにすべきだと私は思います。私が伺ったのは、特別扱いせずに区民相談の各種相談事業での対応に変えるべきだと思うのですけれども、いかがか尋ねました。","respondent":"榎本総務部長","answer":"今のところ、その考えはございません。前あったところに戻す予定です。","id":"exchange-010"},{"speaker":"中塚委員","kind":"提案","question":"やはり今年は作成する行政計画として、長期基本計画とマイセルフ品川がありますので、その２つを提案したいと思います。ぜひ議論を深めていきたいと思い提案したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"そういう依頼があったので、以前にも申しましたけれども、毎年確認をする必要性がそこまであるのかという疑問を持っております。それだけ述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"今回は見送ってもいいのではないかと思うのですが、皆さん、どう思われますか。相手の自治体の慮れば、この時期に行くということは、やはり差し控えたほうがいいのではないかというふうに思うのですけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"この間、私自身も含めて深められていなかったと思うので提案したいのですけれども、ＬＧＢＴなどセクシュアルマイノリティについてです。品川区議会、そして委員会としても議論を深めて理解を深められたらと思いますので、提案したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"提案","question":"近くで視察調査するということが、やはりすごく大事なことだと思うので、所管事務調査もそういうふうに提案しようと思うのです。これから大きな問題になりつつあることに対して、先々考えていくべきではないかと思うので、そういう視察を提案したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"提案","question":"新城市は市長提案なので、どうなのかなということはありますが、飯綱町は議長が提案してこの制度をつくったということです。そういう課題も含めて、ある程度、実施されているところの例を視察してみたいなと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"提案","question":"やはり所管事務調査の調査項目を１８日までにというお話がありましたけれども、それと視察というのは極力絡めたほうがよろしいのでしょうか。静岡県もそうですし、多少それでも構わないというのであれば、そういう感じの提案をどこかでしていきたいと思うのですけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"意見","question":"そうですね。後日、意見を出しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はできれば所管事務調査を深める立場で現地を確認するというのが、この間の委員会活動の姿だったし、そこは基本に置くべきなのかと思います。ただ、テーマや場所によって、さまざま今、委員のご意見やご希望もありますから、そこは正副で調整をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"意見","question":"那覇市もそうですし、札幌市もそうですし、そういうところを１つどうかなと思います。それともう１点は、例えば別府市のおくやみワンストップサービスでありますとか、そういうところもぜひ見てみたいなと思っていますとの意見を述べました。","respondent":"伊藤委員長","answer":"さまざまな観点から検討させていただきまして、次回７月の委員会で正副委員長のまとめを提示していきたいと考えていますが、６月１８日月曜日までに。〔「はい」と呼ぶ者あり〕","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":35923,"voices":118}},{"id":"h30-20180612-14","meetingId":"h30-cm06","date":"2018年6月12日","dateIso":"2018-06-12","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"横山委員","kind":"質問","question":"続いて、先行３区についてですが、そういったほかの区の状況をどういった形で品川区は把握されているのか教えてください。最後に、そちらも具体的にどういった頻度で、どういったことを話し合っていくのかというところをもう少し詳細に教えていただけたらと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"それから、大体先行３区は、五回ぐらいずつ個別に自分たちの児童相談所の運営に関する内容を協議しているというような情報を得ております。先週行いまして、次回は９月以降ということで、次回以降の日程調整をしている段階です。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問・要望","question":"もう１点、これも要望なのですけれども、東京都の児童相談所。これは要望で終わらせていただきます。","respondent":"中塚委員長","answer":"委員会運営に関するご要望については、しっかりと正副で調整して進めていきたいと思いますので、よろしくお願いいたします。ほかに、ご質疑ありますでしょうか。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"それから一応地域の環境等を考えますと、なぜ、東京都内は視察を受け入れてくれなかったのですか。福岡市、熊本市に行くということは、それなりの何か別の利点があったのか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"実は金沢市は、３の表の中にもある児童相談所設置市として、平成１８年の４月から自分たちで手を挙げて児童相談所を設置したというところで。熊本市の視察を本年度の実施予定なのですけれども、現在熊本市は政令指定都市になってありますが…","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"改めて、区としてはなぜ児童相談所の移管を積極的に進めたいのか伺いたいと思います。そういったところについて都と協議はしていらっしゃるのか伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"１点目の、母子保健から子育て支援まで一貫した施策を行うにあたり、区が実際に実施するというところのメリットはあろうかと考えています。私ども品川区のほうで児童相談所を設置した暁には、名称変更するなりということが、あるのではなかろうかです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"例えば、林試の森公園隣の公有地など別の場所という選択肢もあり得るのではないかと思うのですけれども、なぜここにしたのか。なぜここを候補地として区は考えたのかを伺いたいというふうに思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"これまで、区内における用地の検討を行ってきたのですけれども、正直区内にほかにはあまり見込めないのではないかという点が１点目。先ほど来お話がありますように、実際に私どもが児童相談所を立ち上げたとき、ケース移管時に円滑な引き継ぎというのが見込まれるのではないかと。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"施設そのものが、これまで以上の丁寧さが必要ではないかと考えておりまして、住民も含めた検討組織なども設けていく。こういった住民合意の仕組みというのをつくる必要があるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"当然、ご指摘にもありますとおり、公園の敷地を活用するということになりますので、公園の利用者や住民の方に対して区へのご理解というのは丁寧に得ていく必要があると思っておりまして、こちらは機会を捉えて丁寧に説明していくという対応を考えております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、ぜひつくったほうがいいと思うのでということを伺ったのですが、いかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"重ねてのお答えになってしまうのですけれども、まずは丁寧に説明するという所から始めてまいりたいと考えています。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"少し所管が違うところもあったということですが、まだ具体的に住民への説明などのスケジュール感はまだ今の段階では見えていないということでよろしいか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"言葉足らずで申し訳ございません。現時点で例えば何月に何をするというところまでは、まだ具体的な日程は決まっていない状況です。","id":"exchange-008"},{"speaker":"こんの委員","kind":"質問","question":"平成２９年度、平成３０年度されてきた市や県の視察を踏まえて品川区にとっていわゆる利点となる点として何を持ち帰ってきたのか。どういったことが必要だなと感じて今移管の準備をされているのか、その点をお伺いしたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"資料の２をご覧いただきたいのですが、東京都が設置している１１カ所の児童相談所のうち、一時保護所を設置しているのは実は３カ所しかございません。２点目のお尋ねは、なかなか一言でご説明申し上げるの難しいのですけれども、正直至る前の勉強段階です。","id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"視察に関しては、基本的なところをまず押さえるということは大事だなというふうには思いますので、今後はやはりこういったところを工夫している。どういう人たちが動いていくのか、研究をしているところで調査研究を重ねご準備をしてほしいと求めましたが、その辺はいかがか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"委員のご指摘も含めてしっかり対応してまいりたいと考えております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういった体制をどう構築していくのかというのも建設とともに考える。もちろん考えていらっしゃるところだと思うのですけれども、そこについて今の段階でどう考えられているのか説明を求めました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ちゃんと、いわゆるケースワークできる人材を確保・養成していくことが非常に重要なことだと考えております。動いている業務の流れを習熟していただき、区に持ち帰っていただくというようなこともやりながら、人材育成を図っていきたいと考えております。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５０人ぐらいの職員がこれだけの施設になってくると必要だということだったのですけれども、それとも５０名程度だという考えでいいのか。正規雇用の枠がなかなかないという声もあるので、こうした施設での雇用形態も重要だと思うのですが、その辺は今どのようにお考えか尋ねました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"お尋ねありました件ですけれども、児童相談所につきましては配置基準が決まっておりまして、委員が例に出されたような非常勤の方ばかりというようなことは現時点では想定していないところです。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですけれども、私はもう少し住民参加を位置づけた土地の利用ということを進めていただきたいなと思っているのです。そして説明会をしたもとでどういった施設をつくっていくかということをぜひ検討していただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"説明会的なものも考えてはありますので、そういった意味ではさまざまなご意見を伺いながら進めたいと思っています。ご意見を伺う場として、こういった議会の場だと考えていますので、こういった施設建設等々の場合は進めていきたいというふうに思ってあります。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"提案","question":"全く意見は聞いていないというふうには思っていませんし、区としての提案というのも必要なのだけれども、それをもみ合わせるというのですか。さらには地元だけではなくて、やはり広く多くの方が、区民が知って、そして、提案や意見を言えるとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"確認","question":"本体の部分、かごの部分も実際に点検をして、安全確認がとれているのか。それを１点お聞きしたいと思います。","respondent":"立木経理課長","answer":"制御盤等の更新で、扉が開いた状態で上下するようなことがないようきちんとした制御も、さらに安全性を高めたものが入るような形になっております。さらなる安全向上という面では、今回の更新によりさらにプラスされるというような形になっております。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最後に、定期的に汚水とか雑排水は高圧洗浄をかけているのかどうか。それだけ教えてほしいと求めました。","respondent":"立木経理課長","answer":"委員おっしゃるとおり、そのような清掃を行ってあります。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういう問題意識があるのですけれども、いかがでしょうかというのが１つです。庁舎本体が昭和４３年で、２００６年の第３回定例会での他党の方からの質問で、耐震工事後の耐用年数について質問があったのです。","respondent":"柏原企画調整課長、立木経理課長","answer":"なかなか一気にそういったところまでというのは、難しいかなと思ってあります。避難に関しての部分で、道路として広げるといったところも検討しておりますので、施設だけではなくそういった部分でも広げるといいますか。 当時の総務部長の答弁のとおり、大体２０年から２５年は耐震工事のときから使用可能だろうということで、当時工事をしております。それから給排水等の設備機器を更新することによりまして…","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"私たちとしましては、こうした手法というのは、自治体としてはやるべきではないと考えておりますけれども、いかがでしょうかというのが１点です。世田谷区では繰り返し繰り返し報告会、説明会も行われておりましたので、そういったものの実施を求めていきたいと思いますが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それは１つの考え方というところでそういったところを考えながら、検討素材の１つに上げるというのは考え方としてあると申し上げたところですので。そういったときにどういった手法でやっていくかというのはいろいろな自治体のやり方を見ながら今後も検討しなくてはいけないだろ…","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"非常に世田谷区の手法というのは、ほんとうに住民自治を大切にした、つくられた後も非常に愛される。そして、大変利用されるような施設になっていくような手法だと私は思っておりますので、ぜひ大いに参考にしていただければなと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば区内で大規模な民有地等があいて、区に打診があったりした場合などは、当然行財政改革特別委員会での報告をいただきたい。当然品川区としても絡んでもらいたいという思いがあるんですけれども、その辺の考え方だけ説明を求めました。","respondent":"柏原企画調整課長","answer":"活用できるもの、こういった議会の場にもご報告させていただきながら、活用について検討を深めていければというふうに思ってあります。別の所管委員会になるのかわかりませんが、検討の際には報告をさせていただいて、いろいろと議論を深められればというふうに思ってあります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区に入ってくる地方消費税の額は逆に大きく減るというのはどういう理由なのかもう少し説明していただきたいというのが１点です。国にもそういったことを求めていくべきだと思うのですけれども、やっていらっしゃることとあわせて、区の考えを伺わせてほしいと求めました。","respondent":"品川財政課長、伊東税務課長","answer":"それから従業員の配分を１２.５％から１０％に下げている。こういう算定方法で、区に対して不利な条件でこの消費税の引き上げ後も計算されるということで減額というふうになっております。 先ほどの資料２のところにもありますけれども、ある程度税制改正が必要なんじゃないかという申し出をしています。影響額として１５億円と書かせていただいておりますけれども…","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"国に要望を出していますけれども、ふるさと納税の返礼品に対して何ら罰則がないし、いろいろ政令というのですか。区はほっておくのではなく、罰則規定がないのですから、そういうふうにやって区民税を区民のために使っていくのだと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"２点ほど、お伺いをします。区民の方々に、そして、今年度どういった想定をされているのかなというところをお聞きできたらと考えています。","respondent":"伊東税務課長","answer":"平成３０年度の影響額ということで、これは予算的なところでの１５億円というふうに見ているところです。今それをしっかり読み取っていただければ、そうなるというところはわかるのかもしれませんが、直接的な形ではやっていないというのが現状です。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"そこで、流出を食いとめるという意味で周知ですとか、制度の趣旨のＰＲというところ。これからこの行財政改革特別委員会のほうでも議論のほう進めていけたらなと考えていますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この資料の２、その裏ではそうは言っても民間企業と自治体は違うのでということで、いろいろ考慮すべき行政の特質があるのですよね。行政の特質も考慮すべきだよということなので、どういうふうに、狙いや目的が何なのかを教えていただきたいのですが。","respondent":"齋藤会計管理者","answer":"説明が丁寧ではなかった部分があるかもしれませんが、場合によっては施設を単位として、どれだけ費用がかかっているかが見えることになります。ただ、活用のあり方については、まだ始まったばかりでありますけれども、各自治体も今検討をしているところであります。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"それで、また償却できないものもあるからそこは重々お考えくださいということなのでしょうけれども、我々が見ていくと、なぜお金がこれだけ残った。だからそういう収支を今度より明確に我々が見えるようになるというふうな考え方でよろしいのか尋ねました。","respondent":"齋藤会計管理者","answer":"若干ご意見と相違している部分もあるかもしれませんけれども、お聞きのところにつきましては、委員のおっしゃるとおりです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"資料の２の新公会計制度導入の意義の(2)のところですけれども、それは結局どういう効果につながっていくのかというのが気になってはいるのです。その辺の疑問や心配については、どのような見解を区はお持ちか尋ねました。","respondent":"齋藤会計管理者","answer":"負担のあり方について将来も含めてそういったものをどう考えるかという議論の素地にするということでありまして、フルコスト情報をお示しすることで、行政が説明責任を果たすというところに意味があるというふうに考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"それを議論の素地にするというのはいいのですが、自治体ですから住民福祉の向上が目的です。ですから、地方自治体の基本的な役割をしっかり見定めてちゃんと忘れないで議論していくことが必要だというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"１点だけ。全庁的に取り入れていくというようなお考えですとか、今後のスケジュール感ですとかそういったところの見通しを教えていただけたらと思います。","respondent":"山本情報推進課長","answer":"今年度は先ほど報告したとおり、教育委員会のほうと一部学校で実証実験を行うことになっております。今後全庁展開をするかを判断していきたいというふうに思っておりますので、今後のスケジュールについては、まだ決まっていないのが現状です。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"区民の個人情報さまざま多岐にわたってある中で、そういう情報などはソフトを更新したときには全部打ち直して入力するようになるのですか。それともそのままそっくり移すことができるのか尋ねました。","respondent":"山本情報推進課長","answer":"機器を更新した場合の個人情報等の授受の方法なのですけれども、手打ち等ではございませんで、システム間でバッチ処理という形で情報をシステム同士で流して処理をするという形をとっております。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問","question":"これは例えば2)番の業務システムのサーバの仮想化ということをすると、それとも、経費の削減というほうが大きいのか。その辺がわかるような、わからないような感じなので、要するにどういうことなのか説明を求めました。","respondent":"山本情報推進課長","answer":"サーバの仮想化のメリットですけれども、委員おっしゃったこと２つとも実現できるものです。仮想化をしますと、１台の物理的サーバのほうをとりあえず保守をすればいい形になりますので、職員の負担に関しても軽減されるというものになります。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"何となくイメージができました。いわゆる区民サービスの電子化というのは、それとも仕事上がさらに効率化を図るため機能アップしていくものか、その辺はどうなのか尋ねました。","respondent":"山本情報推進課長","answer":"今回ご案内したＩＣＴ活用の取り組みに関しては、あくまで生産性が向上するという形になりますので、その分短縮された時間等を区民サービスのほうにあてることができるという形になっております。","id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"要望として、例えば今年の２月から、そこで入力をしていくというような取り組みがスタートをしています。少し教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"ほかにも日進月歩でＡＩの技術だとかロボットの技術とかいろいろ進んでいます。いかに区民サービスの向上につなげられるかというのは、常に研究をしながら行政として仕事を進めていきたいというふうに思ってあります。","id":"exchange-033"},{"speaker":"松永委員","kind":"質問・要望","question":"私から１点だけ、まず参考までに教えていただきたいのですけれども、もしわかりましたら教えてほしいと求めました。","respondent":"山本情報推進課長","answer":"一部始めておりまして、効果を見まして来年度以降全庁展開するか検討していきたいというふうに考えております。実際の費用の面で行くと、ペーパレスですので、実際どういった会議で使っていくかというのをこれから検討してまいりたいと思っています。","id":"exchange-034"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"防御も必要だし、攻撃も必要だし、意見の分かれるところだと思いますが、ここは１回議会でもしっかりやっていければなというふうに思っています。とりわけこの１、２、３に関しては、思うところございましたので、発言させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"それから、国有地等については、これは今さらなのですけれども、土地の取得がまだ明確に、最終的に決まっていない２つ、３つですか。改めてといいますか、今まで議論したかなと不安になっていて、確認だけさせてほしいと求めました。","respondent":"中塚委員長","answer":"常任委員会のほうでその後の議論を深めていくものと思いますので、そこは常任委員会とよく調整をしていきたいと考えています。ほかにいかがでしょうか。","id":"exchange-036"},{"speaker":"松永委員","kind":"質問・要望","question":"これも「など」というのも、私たちはＡＩを含めて今後どういうふうな形で展開していくのかということも含めて書かせていただきました。移管にあたり、都や国から、補助金等があるのかどうかというのも調べていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"須貝委員","kind":"意見","question":"多忙であるということで、これから区として立ち上げていくならば、それを見守るというのも１つの方法論ではないかなというようなことも思いました。その辺について正副委員長で考えていただいて、進めていただければありがたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"相手もあることですし、タイミングを適切に図って、区民の意見をどう反映させていくかという仕組みというのですか。どういうふうに公有地を活用していくのかという仕組みのあり方も含めてぜひ議論の俎上にのせていただければありがたいなと思います。","respondent":"中塚委員長","answer":"ご意見につきましては、正副で十分調整させていただき、可能な限り今後の委員会運営に活かしてまいりたいと考えております。〔「なし」と呼ぶ者あり〕","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6050#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":39383,"voices":151}},{"id":"h30-20180613-18","meetingId":"h30-cm06","date":"2018年6月13日","dateIso":"2018-06-13","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、ほかの場面でやるかもしれないのですが、１つお聞きしたいのは、開催周知事業のところです。どういう体制で区が今取り組んで、どういうふうに項目づくりをして、どういうあたり方をしているのかというところだけ説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区全体の取り組みとしては、きちんと載せていないのですが、推進事業本部、区全体で行っております。そちらの協会の会長・副会長も含めまして、いつも情報交換をしながら事業は実施していて、先を見据えてやっているです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"どういう事業者の方に聞いても電通しかないと言うのですけれども、そこで、では誰が来ているのというのが非常に問われるよということが言われます。こういう人がいて、こういうこともこうだからというぐらいのところがあるかなというところだけ、最後に聞きたいとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"オリンピック・パラリンピック準備課ができたときからずっと担当している方でございまして、意思疎通もできているところではあります。部長のほうから言っていただいたりしながら、必ず品川区が１番なのだというような気持ちで挑んでいただくように、いつも声かけをしています。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"簡潔に、スポーツ大使のことをお聞かせください。オリンピックまであと２５カ月しかないのですが、まだまだ人材を登用するかどうか、その点だけ簡潔に聞かせてくださいとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長、池田スポーツ推進課長","answer":"大使という形での任命はこの３名だけとなる予定です。しかしながら、それは個別にでも情報をいただければ、ご一緒できるときがあるとまたいいかなとは思います。 今、ご説明しましたように、１番目としまして障害者スポーツ教室を行いました。先ほどもご説明ありましたように、区内で定期的に活動する団体に講師と選手を派遣して体験をしてもらい障害者スポーツの振興を図るものです。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"４番のその他のところなのですけれども、今、荏原第六中学校校庭を日本代表選手たちの練習会場に提供しているということでした。具体的に教えてほしいのですけれども、なぜ荏原第六中学校が選ばれたのかということと、そういう詳細を説明を求めました。","respondent":"池田スポーツ推進課長","answer":"ご存じのように中学校・小学校の校庭を夜間開放しているところが幾つかあるかと思います。こちらもとてもよいということでございまして、週１回、火曜日の夜７時から９時までの時間帯を練習時間として活動していただいているです。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"２点伺います。そういうのを、もっとこういうふうに引き上げてこようというような考え方というのか、そういうのはお持ちなのかどうかというのをお聞きしたい。","respondent":"池田スポーツ推進課長","answer":"陸上パラリンピックの競技であったとしても、健常者の方が実際にパラリンピックのほうにも出ているというようなことがあるとは聞いております。合意をした上で進めていくことが必要であると考えていますので…","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"これを医者がいてきちんと医療的なランクを決めて、いろいろなルールがまだ統一されていないところもあると、健常者が出てくればそれは強いですよね。健常者がどうのというのもあるから、いろいろな形がとれるのではないかなと思うので、ぜひそういうのも会わせて教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今年初めてやるというフライングディスク教室というのがありますけれども、これをやることになった経緯を教えてほしいと求めました。障害の有無に関係なく楽しめるイベントということで、どういった形になっていくのか伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"実際に募集をしてみますと、小学生から３０代の方までのお申し込みがありまして、幅広く、障害をお持ちの方に参加していただける形になりました。内容につきましてもどなたでもできるようなボッチャとかフライングディスクとか、そういったものを考えているところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、障害者スポーツチャレンジデーのほうは体験的なものを行っていくということでよろしいですかね。","respondent":"池田スポーツ推進課長","answer":"基本的には体験していただいて、スポーツを楽しんでいただくということ。は１つ、車いすテニスにつきましては、きちんとしたプレーヤーをお呼びしましてエキシビションマッチを考えているところではあります。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"新しくこの２つのものが始まるということで、さらに、障害を持っている方でもスポーツが気軽にできるよう進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"協定が結ばれたのが２０１６年４月ということだったのですけれども、荏原第六中学校の人工芝はブラインドサッカー用にそのような人工芝を選んでいるのか、それともほかの学校と同じ人工芝を使っているのかということを聞かせてくださいとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"荏原第六中学校の校庭が特殊な校庭だということではありませんで、中学校の場合は部活動があるためにショートパイルの芝が使われているとのことです。２カ所しかない、信号も１個しかないと、これも安全に来られるということで評判は大変いいところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"いつというのが抜けていたのですが、いつごろかわからないですかね。練習会場を提供しているのかというのを。","respondent":"池田スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"実際には、パートナーシップ協定を結んだ翌年の８月からになります。 スポーツだけではなく文化の面からも機運を上げていって実施をしようということで、去年６月より実施しているところです。(2)、現在１３事業にとどまっておりますので…","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"こういうことも事前、それは組織委員会がやらないと言ったとしてもやるという強い気持ちで今いらっしゃるかどうかという確認を１つしたい。金銭面が特に、助成のようなものも含めて、終わった後も継続できるような方法は何かもう既にお考えなのかどうかというのを合わせてお聞きしたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それともう１点、その後の継続のお話です。ご自分たちで自走できるような手助けと言いますか、そういったものも私ども、手を携えながらやっていくことも大事かと思っているところです。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことも含めて、非常にそういう意味の会場を有効に使うというのは１つの手だと思うので、ぜひそういうことも含めて考えていただきたいなと。もしお考えがあれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大田区との連携というお話です。どちらがやるかというのは関係なく、今後大田区とは連携をとりながら、ホッケー協会も交えていろいろな事業を展開していきたいと思います。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"この方向性はもう何年も前から議会のほうでも提案をして、関係をしていくのか、その辺について詳しくお聞きしたいと思います。これはどのくらいの規模の方が集まりそうなのか、今日は文化観光課長も来ていらっしゃるので教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"３つ目ですが、品川区の文化芸術の方向性の検討ということで、文化芸術にかかるプラン等の策定等を視野に入れたレガシーの活用方針の検討を行う。この３つを柱として協議会を進めていく考えです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それと、やはり品川区民が参加できるような文化プログラムというものをぜひ考えていただきたい。それは１つの例示ですけれども、ぜひお願いしたいと思うのですが、その辺についてご意見を伺いたいと思います。","respondent":"立川文化観光課長","answer":"文化芸術振興協議会の設置目的、また文化プログラムの実施につきましては、そういったいわゆる文化イベントということを考えております。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"しながわ文化プログラムについて１３事業だという説明が先ほどあったのですけれども、そことの関係と、明日実施される文化芸術振興協議会の今後のいろいろな検討との関係がどういうふうにリンクしていくのかがわからないので教えてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"おりている１３事業というのは、これを一緒に盛り上げていきませんかということをお声かけさせていただいて登録してくださったところがほとんどです。今後は文化観光課の文化芸術振興協議会と文化芸術フォーラムのほうと連携をしながら…","id":"exchange-016"},{"speaker":"南委員","kind":"意見","question":"皆でこの平和の祭典のオリンピックを成功させる、そういう点で、この文化プログラムというものを非常に期待して見ていきたいと思っているのですね。この４番目に書いてあるしながわ文化プログラムについては大枠しか書いていないので…","respondent":"辻オリンピック・パラリンピック準備課長","answer":"先ほどご説明申し上げました１３事業というのは、去年立ち上げまして手探り状態で始めたところもございました。そしてオリンピックを盛り上げる１つの材料と言いますか、多方面から１つに結集したいと思っているところです。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、改めてその点もお願いとし、大事に育成をしていただきたいと。力を借りながら育てていただけるようにお願いしたいということも申し上げておきたいと思います。","respondent":"熊谷指導課長","answer":"そして、この４つのテーマと４つのアクションを掛け合わせたオリンピック・パラリンピック学習を本区においても進めているところです。ホッケー、区内開催そして応援３競技体験教室の実施ですけれども、教員対象のブラインドサッカー研修会を既に６月５日に実施したところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"の授業が今現在３５時間程度確保されていましたけれども、要はオリンピック後はこの３５時間というのが確保されるのでしょうかということが１点。区内の小学校・中学校の子どもたちに対して３競技だけでいいのかというところの確認をしたいのですが、まずその２つの確認をお願いいたします。","respondent":"熊谷指導課長","answer":"２つ目のご質問ですけれども、３競技中心に取り組んでいるところですけれども、映像を見せていただいたりもしているところです。こういったものも取り組んでいるところですので、３競技を中心にほかのオリンピック・パラリンピックの種目にも各学校で取り組んでいるところです。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういうこともこの「ようい、ドン！しながわ」の中で取り組んでいくべきだと思うのですが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"しながわ」につきましては、今の段階では２０２０年大会の年までの配布ということは考えております。検討していきたいと思っているのですけれども、また、それにつきましては引き続き検討してまいりたいと考えています。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"しながわ」の内容が、私個人の思いですけれども、やはりこれから子どもたちにずっと続けて伝えていってほしいと思うのです。だからこそ、どういう教材になるかは別問題としても、その精神は引き継いでいってくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"３点にわたってここに掲げられておりますけれども、東京都にも似たような目標のようなものがあるのかどうかということと、そういったものについて少し教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"東京都のオリンピック・パラリンピック教育と重複している部分がありますので、基本的には目標はほぼ同じです。ボランティアマインドという言葉が小さいお子さんにはわかりづらいのではないかといったところでわかりやすい「おもてなし」という言葉に言いかえた…","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"あるいはアワード校についても品川区は大変にたくさんの学校がアワード校として選ばれているというところでの１つの成果と言うか、これまでの推進の１つの結果というものが出てきているわけですけれども、ご見解を最後に少し伺いたいと思います。","respondent":"熊谷指導課長","answer":"しながわ」の教材でも、保護者や地域の方に聞いてみましょう、それから一緒に歩いてみましょうというような取り組みをしています。ですので、子どもたちから大人への発信ということができたらいいなというのが、私どもの願いです。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"研修を受けた教員の受け持つ学年などは特に指定などがあったのでしょうか。どのような学年の先生でも、あとはスクールアクション「もったいない」大作戦の給食の残菜を減らす取り組みについて具体的に説明を求めました。","respondent":"熊谷指導課長","answer":"基本的にはどなたでも、特にオリンピック・パラリンピック教育を推進する教員ということで、全部で５５名の参加がございました。その中で、自分たちでできるだけ残菜をなくすにはどうしようということで、好き嫌いをなくそうとか、子どもたちが考えて取り組んでいるところです。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"」学習のことなのですけれども、そこをもう１回確認をさせていただきたい、負担になっていないということを確認させていただきたいというのと。ずっと給食が残ったままの机、その状況というのはどうなのかなという声があるのですけれども、その辺はどうお考えか尋ねました。","respondent":"いながわ委員長、熊谷指導課長","answer":"田中委員、大変申しわけないのですが、概要説明ですので、そこまで深く行かずに、それであれば、その他でご提案をしていただいて、正副で検討してまいりたいと思いますので、答えられる範囲でご答弁いただければと思います。 時数については先ほど申し上げたとおり削っておりません。そういった指導につきましては、私どものほうでもそうした子どもたちの負担となる指導にならないよう、今後とも学校への指導を行ってまいります。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、ここはスポーツ交流も含めて非常に大切だと思っているのだけれども、教育委員会としてはどう捉えられているのかというのをまずお聞きしたい。私は非常にいいことだと思っているけれども、そのことだけをまず聞きたい。","respondent":"熊谷指導課長","answer":"私自身も、教育委員会としましても、姉妹都市・友好都市との連携、そして交流と、非常に重要だと考えています。しながわ」の５年生から９年生用にも、しっかりと友好都市・姉妹都市につきましては掲載し、子どもたちへの意識を高めているところです。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"一般質問でもするかもしれない、どういうわけか、何か先細りになりつつあるのかなとすごく思っています。オリンピックを契機にと言ったらスポーツ交流をこういうふうにしていくべきで、その辺を、その辺はどうかというのを聞きたい。","respondent":"柏原企画調整課長","answer":"大切な視点であるというのは区としても認識、考えているところです。それから相手の動向とか考えも鑑みながら、どのような形がよろしいかというのは引き続き検討、考えていかなければいけないだろうというところです。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"意見","question":"私は１つの教育、どういうふうにしていったらいいのか、一歩前へ出ることが必要だと思っています。それだけ言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"つる委員","kind":"確認","question":"まず確認で、周知事業等に関連してなのですが、そういうのがあったかどうか説明を求めました。","respondent":"熊谷指導課長","answer":"海外のオリンピアンですが、陸上のエリック・ワイナイナ選手、陸上の銀メダリストだったのですが、第四日野小学校に平成２８年度、来ております。外国人のオリンピアンが延山小学校に来る予定で、まだ未定ですけれども、わかり次第ご連絡したいと考えています。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"今のワイナイナさんについても都からの派遣か尋ねました。","respondent":"熊谷指導課長","answer":"都からの派遣です。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"そういう機会をつくることというのは今後の大きな検討の中であるかどうか、教育委員会ではないかもしれませんけれども、説明を求めました。","respondent":"熊谷指導課長、安藤文化スポーツ振興部長","answer":"昨年度、そのときにトルコの代表選手と、それから浜川中学校のバスケットボール部が交流したということがあります。選手が事前に東京都を訪ねて、さまざまな練習試合等を行っていく際には… ２年前にブラインドサッカーのブラジルの選手が品川区に来て練習をしたり、皆で交流をしたとか、そういうこともやっておりました。","id":"exchange-031"},{"speaker":"つる委員","kind":"提案","question":"ということは、これまでもいろいろやっていただいている中で、あとの残り２年の中でも今後そういう企画、検討、当然相手との交渉も含めてあるということで理解をしましたので、また次の機会にいろいろ提案していきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"お伺いしたいのですけれども、ここの調査日程（案）にも載っているスポル品川大井町のことで聞きたいのですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私が１年前に所属をしていたときには、私が抜けていた１年間の間にはそれは行われていないようなのですが、ぜひ視察をしていただきたい。特にパラリンピックと文化というところの象徴的なアール・ブリュット展等の視察もぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"いながわ委員長","answer":"ご意見として賜らせていただき、正副でしっかりと協議して検討していきたいと思いますので、また次の委員会でご報告させていただきたいと思います。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"意見","question":"は区長選挙の絡みで、もしかするとこの委員会がそもそもこの時期にないのかなということもあるかもしれないです。秋ごろと聞いたのですけれども、もし無理のない範囲で可能であるならばということで、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"意見","question":"これはどうするというのが、厚生委員会からいくと今のはどうなのというのは、何でもありになってしまうと。今の文化の部分は厚生委員会の副委員長もここにいらっしゃるから、そういう意味でどこかで一線は何か考えてというのだけ言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"このスポル品川大井町のことなのですけれども、突然報道で知ったというか、区との関係性と言うか、そのあたりを少し教えてほしいのですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"そうなのですね。２０２０年には閉まる予定ということなのですけれども、情報が入ってきているのかと思って今伺ったのですけれども、ないということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"こんなコースだった、当時は５００メートルぐらいで走っていたというようなことも聞くのですが、例えば品川区でどなたでも応募できるわけですよね。聖火リレーに参画できるために情報提供をいただきたいし、区がどこまでものを言えるかというのも正副でぜひ検討してほしいと求めました。","respondent":"いながわ委員長","answer":"では、改めて正副で検討をしていきたいと思いますので、よろしくお願いいたします。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"スポル品川大井町のことで、いつ知ったかだけ、具体的に教えてほしいのですけれども。その会見の後ということ、いつということを説明を求めました。","respondent":"池田スポーツ推進課長","answer":"私が得た情報は、実際にＪＲ東日本のホームページを見ましたところでのプレスリリース資料というのが５月９日付の発表ということになっております。その前には、地域の方には説明があったかもしれませんけれども、私が正式に得た情報というのはこの５月９日ということになります。","id":"exchange-040"},{"speaker":"田中委員","kind":"確認","question":"私がと言うか、区が把握したのはいつかということを今聞いていて、区として把握したのもこのＪＲの発表の後ということになるのか確認させてください。","respondent":"池田スポーツ推進課長","answer":"事前の情報としまして、ＪＲから地域の方に事前説明等がございましたので、その地域の方に説明をいただいた資料を拝見して知ってはおりました。それは実際には４月ごろにもう地域のほうにＪＲから説明がありましたので、そこからは知っております。","id":"exchange-041"},{"speaker":"田中委員","kind":"確認","question":"その地域への説明があったのが２０１８年、今年の４月ということで、その後、そのときに地域の方からの情報を得ていたということでの確認です。いいか尋ねました。","respondent":"池田スポーツ推進課長","answer":"そのとおりです。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはお願いだけしております。我々がせっかく要望を出しに行ったときぐらいは、そういう情報を少し答えてくれるぐらいの要望は、要望事項を我々が言える機会があれば。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/125111?Template=document&Id=6536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":41430,"voices":139}},{"id":"h30-20180615-10","meetingId":"h30-cm06","date":"2018年6月15日","dateIso":"2018-06-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ３時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"始まる前に一つ確認したいのですが、よろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"改めて議長にお伺いしたいのですが、約７０年の歴史を持つ品川区議会初めてのことです。改めて議会の可決についての重みをどう考えているかということをお伺いしたいのですが、いかがか尋ねました。","respondent":"松澤議長","answer":"重みでしょうか。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"我々としては、はっきりとしたものを求めたのですけれども、そのことに対する見解はいかがですか。松澤議長のもとでは、議会は開けませんということを求めたわけでありますけれども、そのことに関しての思いはいかがか尋ねました。","respondent":"松澤議長","answer":"議会が開けませんということでしょうか。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"改めて確認しますけれども、議会で可決された内容ですよ。他人事ではないか尋ねました。","respondent":"松澤議長","answer":"可決された内容をはっきり言っていただかないと、私としては答えようがありません。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"５月２９日の品川区議会の臨時会において、松澤利行議長に対する不信任動議が可決されました。それに対して、私としては速やかに辞任を求めたのですけれども、そのことに対してのお考えはいかがか尋ねました。","respondent":"松澤議長","answer":"地方自治法第１０８条では、議長がみずから辞意を表明しない限り、任期は４年というふうにこの新聞でも書かれております。私はそのとおりみずから辞意を表明することはございませんので、どうぞよろしくお願い申し上げます。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"ただ、今の話を聞くと、議長の不信任が可決されたという議会意思よりも、議長個人の意思が優先されると感じるのですよ。だから、法的な拘束力がないことは理解しますけれども、議会の公人としての立場からどうお考えなのか尋ねました。","respondent":"松澤議長","answer":"この新聞を見る限り、動議は法的拘束力はないというふうにも書かれております。任期は４年、議長がみずから辞意を表明しない限り任期は４年ということですので、私は辞意を表明はいたしません。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"提案","question":"あのとき、私たち自民党・子ども未来会派として動議を提案し、読み上げさせていただきました。このことに対して、議長はどうお考えなのですか、改めてお伺いしますとの意見を述べました。","respondent":"松澤議長","answer":"今述べましたとおり、何回言われましても第１０８条の中で、議長がみずから辞意を表明しない限り任期は４年と書かれております。私も法律で調べましたら、そのとおりでございましたので、私はみずから辞意を表明する意思はございません。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それをしっかり辞表を出す、これを鮮明にしていただきたいということを今言っているわけでありまして、それについてのお答えをしていただきたい。こういうところについての明確なお答えをしていただきたい。","respondent":"松澤議長","answer":"地方自治法第１０８条では、議長がみずから辞意を表明しない限り、任期は４年というふうに新聞記事にも書かれております。私はみずから辞意を表明する気はございません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話は、さっきから伊藤委員が言って、今私が話したことの答弁にはなっていないと思いますので、しっかりもう一回答弁をしていただきたい。","respondent":"松澤議長","answer":"地方自治法第１０８条では、議長がみずから辞意を表明しない限り、任期は４年と書かれております。４年間、４年間といいますけれども、残り１年間しっかりと議長として職責を全うしてまいりたいと思います。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"では、議決の重みはどこに行ってしまったのですか。我々もその提案をさせていただいて、臨時会のときでも、議長の進行ではなかなか臨時会自体も終わることができなかったとの意見を述べました。","respondent":"松澤議長","answer":"任期は４年、私は残り１年弱しっかりと議会改革、議会の正常化に向けて頑張っていきたいというふうに思っております。辞任はいたしません。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話だと、第１０８条の話ばかりで、法的なことはもちろん我々は理解してやっているわけで、そこの副議長進行も現実問題として起きてしまった。そこに議決が起きたわけですから、それはどうお考えなのか、どうお考えなのかということを説明を求めました。","respondent":"松澤議長","answer":"地方自治法第１０８条では、議長がみずから辞意を表明しない限り、任期は４年と書かれております。みずから辞意を表明することはございません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"確認","question":"確認だけしますが、先ほど来、我々の質問に対して明確なお答えがない。それはできませんと言ったこと、そういうことの責任はどうお考えなのですか、そこをお聞かせ願いたい。","respondent":"松澤議長","answer":"地方自治法第１０８条では、任期は４年、私は残る任期をしっかりと議会正常化に向けて頑張ってまいりたいと思います。みずから辞意を表明することはございません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問","question":"我々も質問をさせていただいていて、こんな状況が続くのはいいことではないと考えています。それだけはお伝えします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"その動議の中身を見て判断をどうするかという過程は既に済んでおりまして、正常化、健全化に向けてアクションを起こす必要があると考えます。ぜひほかの会派からもそれぞれ議決の重みということについて意見をいただければというふうに思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"今自民党のほうから議決の重みということについて他会派の意見を伺いたいと、これは賛成も反対もできない、棄権という態度をとらせていただきました。それが全てです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"消防団の問題も決着済みだと、自民党自身が議会を混乱させていると、そういうふうなことで不信任動議に対しても反対という態度を表明いたしました。議会の中で１９人ということで、ぎりぎり可決ということになりましたけれども…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"本多委員からお尋ねがあったので、ぜひ意思を表明していただきたいのと、議会が混乱をしております。議決されてから２週間ぐらいたっている中で、この間どのように健全化に向けて取り組んだのかというのもあわせてお聞かせほしいと求めました。","respondent":"松澤議長","answer":"残された１年弱の任期ですけれども、しっかりと頑張ってまいりたいと思っているところです。時間がないということで、後ほどゆっくりお話をしましょうということで別れて、それ以来となっているところです。","id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、質問と違うお答えは控えていただきたいのがまず１点。その意思の確認をしているわけであって、それとももう少し議長として何かお考えがあるのか、そこをもう一度説明を求めました。","respondent":"松澤議長","answer":"おっしゃったとおり、今の幹事長の理解で、いいと思います。これから正常化に向けては、各幹事長とお話をしながら正常化に向けて頑張ってまいりたいと思っています。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"今は幹事長が議運の委員長ですから、ちょっと確認もしていませんが、２週間アプローチはゼロだと思っています。これからまたやっていきますというお話だけれども、では今までの２週間どうされていたのですか、伺います。","respondent":"松澤議長","answer":"動かずに待っていなさいという意見もございましたので、私はそちらのほうを尊重して動かずに待っていたところです。おとなしく向こうからアプローチするまで待っていなさいというお言葉もいただいておりますので、私はそちらのほうを尊重したところです。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問","question":"いろいろそういう行動を起こしたほうがいいのではないですかと言われて、そういう行動を起こしたと我々は思っています。この２週間、どうしてそういう結論に至ってしまったのか、改めて伺います。","respondent":"松澤議長","answer":"おかしいですか。〔「おかしいです」と呼ぶ者あり〕自民党の幹事長に正式に申し入れて、お話をする会を開いていきたいというふうに思っているところです。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"意見","question":"毎回その話で、いつもそういう話をここでされるのは構いませんが、それが一つも履行されていないということだけ言っておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-02","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"高齢者施設に関する要望というところで、都市部で逼迫すると予想される高齢者施設を計画的に整備するための支援を次のとおり要望する。(3)外国人介護人材確保のための規制緩和というところで、なかなか要望はしていますが、前に進んでいないというところで要望させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"介護保険料も３年ごとに１回の値上げがずっと負担になっているので、これも国庫負担そのものの割合を引き上げてほしいという要望です。その差し押さえの交付金制度の廃止を求める要望ということで、この交付金を廃止してほしいという要望を提案したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"児童相談所を含めて、これはしっかりと要望していかなければいけないと思っていますので、それも含めた権限と財源の移譲であります。品川区としっかりと連携をして、住民の皆様にはしっかりと各地区において説明会を開催していただきたい、以上４点挙げさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"提案","question":"我が会派は、今回この要望を提出期限までに提出することを差し控えました。項目等のことはありますが、改めて我々が提案をするというのはルール違反になるので、それはしませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"若林副委員長","kind":"質問","question":"私どもの会派、公明党会派としても、不信任の理由についての是非については判断しないということで態度表明をさせていただきました。これは紛れもなく時の議長がやられるわけですから、現議長が出されるわけですから、今までどおり議会運営委員会の中でしっかりと議論をした上で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"提案","question":"今回私たちは提案をさせていただきましたが、提案をした後、議論をこれからもすると思います。そういった意味において、今までどおり議長に最終的にはお任せしてよろしいかと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"このご要望については、ここで議論をして、議会運営委員会で判断をしていただいて結構だというふうに思います。なぜなら、しっかり要望はしていかなければいけないといった中で、私としてはここで結論を出していただいて構わないと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは当然やるべきだけれども、最終的には議長という今までの流れでいいのではないかというところのほうが多いわけですよね。〔「半々」「議長、副議長は関係ないですからね、議会運営委員会は」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ああ、そういうことなのか。〔「人数は関係ないですから」「だから、多い、少ないではないのですよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"横山委員","kind":"意見","question":"先ほど石田しんご委員のほうからお話がありましたけれども、児童相談所も含めて権限と財源の移譲をということで、こちらは今のタイミングで必ず品川区としても入れていくべきだと考えておりますので、ぜひお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"２３区共通で出していくわけですから、国有地なりをやはりしっかり各区に向かって、そういうのをやってくれというのも一つだと思います。これはたぶん出していけば、ここら辺は我々としても非常に賛同できるし、出していったほうがいいのではないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"意見書というのは全会一致で出したものなので、そこは一致できるのではないかなというふうに思います。今回２会派で出していますけれども、ぜひ羽田新ルート問題についての要望というのは出していきたいと強く要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"意見書で言っているだけです」と呼ぶ者あり〕いやいや、違う、議長会要望で。〔「出していないよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"出したと思っているけれども、２３区要望、特別区要望としては、そのときははねられた。たしか、それは出したこともあるし、というのが私の記憶、間違っていたらごめんなさい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"羽田の問題というのは、２３区全てではないのですけれども、１６区ぐらいはかかる問題なのですよね。本当にこの都心のルートですから、ちょっと皆さんの全体の認識も、ぜひ品川区のほうから提起していくというところでやっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは、それはやはりちゃんと区民に理解を求めるような形でしっかりやってくれというぐらいは、私はあってもいいような気がするけれどもな。それは、はねられるかどうかはわからないけれども、それはあってもいいと思うよ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ違うところが、最近のことということで、資産価値の低下というものが意見書には入っていなかったのですね。ちょっとこれを取り上げるかどうかというところ、これは全く一緒ではないということ、これはちょっと確認をさせていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"〔「そこは抜いてもいいということですか」と呼ぶ者あり〕そうです。私は抜いてもかまいません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5280#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":21538,"voices":102}},{"id":"h30-20180627-10","meetingId":"h30-cm06","date":"2018年6月27日","dateIso":"2018-06-27","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"突然でどういうふうに判断したらいいかよくわからないのですけれども、委員長にお聞きしたいのですが、今までもテレビ撮影とかが頭撮りで入ったことというのは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今日なぜそういうふうにテレビとかが入るのかというのがよくわからなかったので。そういう部分が……との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"それに準じて結構ではないのですかと申し上げたのです。今までどおりとは言っておりません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"意見","question":"委員会に入ったときには写真撮影、もちろん録音もあったと記憶しています。それはやはり冒頭で写真と同様にその場面を許可してはどうかということを言わせていただきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私たちとしては、写真撮影とかも別に冒頭に限らずに、開かれた議会というところでいつでも写真撮影は許可すべきだという立場にしておりますので、テレビ撮影もそういう形で言えば許可をしてもいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"}]},{"id":"topic-02","title":"平成３０年第２回定例会","agenda":"平成３０年第２回定例会","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"審議に入る前に確認したいことがありまして、質問いたします。お願いをいたします。","respondent":"松澤議長","answer":"不信任動議の可決の件についてですけれども、議会意思としてそのような不信任動議が可決されたということは、私は重く受けとめております。私といたしましては、私は残る任期、しっかりと議会改革に向けて頑張っていきたいと思っているところです。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"とすれば、公人、公の立場としての、議長の立場としてのお考えはどうでしょうかということを改めてお伺いいたします。議長としての立場をどうお考えなのか尋ねました。","respondent":"松澤議長","answer":"今私が申し述べたことの繰り返しになりますけれども、私はその理由というものが果たして議長解任決議にふさわしいのかどうか、大変に疑問に思っておりますので、しっかりと残る任期、議長として頑張ってまいりたいと思います。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"議長の思いとしては、品川区議会が公的な立場で決めた議決よりも、自分のお考えが上だということなのでしょうか。お願いいたします。","respondent":"松澤議長","answer":"先ほど申し述べさせていただきました。残る期間しっかりと議長として頑張ってまいりたいと思っているところです。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"品川区議会で、公的な場において議決されたことに対して改めて公人の立場として、どうなのでしょうか。お願いいたします。","respondent":"松澤議長","answer":"その議決された理由そのものが私にとっては大変に不本意なものであり、それが議長の不信任に至るものではないと感じておりますので、私は議長をしっかりとこれからも頑張ってまいる所存です。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"その理由で自分は議長は辞めないとお考えなのでしょうか。そこだけ確認をお願いいたします。","respondent":"松澤議長","answer":"今言われたとおり、議長不信任動議の内容には私はそぐわないのではないかと考えています。どう考えてもそれが議長不信任動議に足る問題ではないと考えておりますので、議長としてはしっかりと残る任期、頑張ってまいりたいと考えています。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"今確認ですけれども、ここに至るまで、その理由が不信任に値しないとご本人はそうお考えだと。それをまず２つ目伺います。","respondent":"松澤議長","answer":"都連に対して除名だという、いわれもないことを言われることに対しては、私は自分なりにしっかりと対応してまいりたいと思っているところです。議会意思というのは確かに重く受けとめますけれども、議長を辞めるつもりはございません。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それ以降も議運があり、またこれを聞くのは議運の中では２度目ですけれども、こういう形でまた我々もこういうふうにお聞きをしなくてはならない。それを、そこら辺の経緯はどうお考えになっているのかということも改めて伺いたいと思います。","respondent":"松澤議長","answer":"それと、約束を反故にするのはどうかということを言われましたけれども、どういう約束が反故されたのか。改めてこちらのほうからお聞きしたいと思います。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"前回と今回の不信任動議、文章があるのでそれを読んでいただければ違いはわかると思いますが、その点をどうお考えなのかということも伺いました。自民党の幹事長がそういう交渉をされてきたことについてはどうお考えで、そこら辺の点を改めてお伺いします。","respondent":"松澤議長","answer":"今いろいろ聞きましたけれども、約束、何が約束なのかというのを私は改めて聞いている。やはりそこを今おっしゃっていただかないと話が進まないです。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"では１年後に議長をされてもいいのではないですか、それでは１年任期はあるけれども、それが条件ですよと。我々会派の１１人は全員それを覚えているわけでありまして、それをどうお考えかということであります。","respondent":"松澤議長","answer":"しかし、５月３日に筆頭副団長が倒れまして、後任の団長の選出が全く大変に難しくなってまいりました。ですから、議長は辞職することはありませんし、しっかりとまた頑張ってまいりたいと思っているところです。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"ご自身が辞めると、そういうことをお考えになるのに、我々のほうが辞めるにはどうしたらいいのだということを指導しなければいけない議長なのですか。辞表は幹事長が返してきたのです」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"ではこれからやるといって何もやってないではないですかという話もこの前させていただきましたけれども、我々もしゃべりたくないと思っていますが。それに対してどうお考えかということを、最後伺ってやめます。","respondent":"松澤議長","answer":"ちょっと資料を広げますけれどもよろしいでしょうか。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"提案","question":"私どもは西本議員のものについては金額は今きちんと決まってないのであればあり方検討会やそういうところを開いてやっていくべきだという提案もさせ…これだけはお伝えいたしたいとの意見を述べました。","respondent":"松澤議長","answer":"今、政務活動費にかかわるあり方検討会というお話がございました。この件につきましても、幹事長にあり方検討会、そういう話が議運で出たので検討したいと思うがどうでしょうかというお話はさせていただきました。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは、ではここまで第三者委員会は何をどうしようと思われていたのか。これだけ混乱を招いた中で、では改めてやりますよって、それをいまさら言うことかなというのは申し伝えておきますとの意見を述べました。","respondent":"渡部委員長","answer":"後ほど議長を指名して、先ほど今日話すということをおっしゃったので、相当詳しい説明があると思いますので。〔「話すって言いませんよ」と呼ぶ者あり〕","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回の議運でも４０分以上かけてやったのではないでしょうか。もう本当にたくさんの時間を使ってこういう形で混乱させるというやり方はぜひやめていただきたいということを申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"提案","question":"我々もこのことに関して時間を費やすのは正直勘弁してほしいなと思いますが、まず１点は、具体的になぜ議長を全うしていきたいのか。これは提案ですが、そこで松澤議長がもう一度選ばれるのであれば、その点もあわせてお考えを説明を求めました。","respondent":"松澤議長","answer":"１回目、その後どのようにしたのかということですけれども、大変に難しい答えだと思います。自分としては、残る任期、議長としてしっかりと頑張ってまいりたい、そういうような意味で、私は地方自治法１０８条があるのだろうと考えています。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"提案","question":"いわゆる不信任動議が出される前の議運でも私はいろいろと議長に対して意思確認も含めてこの場で質問させていただいて。３点目の提案も含めてですが、質問に関してもそういった提案を受けてなるほどなとは思いましたが、今そのことに対してやるつもりはないとの意見を述べました。","respondent":"松澤議長","answer":"何と言ったらいいのでしょうか、答えは一つだと考えています。それが全てです。","id":"exchange-021"},{"speaker":"石田（し）委員","kind":"提案","question":"なので提案をさせていただきましたが、一度お辞めになって新たに信任を問うべきではないか。もし何かあれば議長からご発言いただくものと思いますとの意見を述べました。","respondent":"松澤議長","answer":"その報道の仕方を注視していきたいと思いますし、私はこれはいたし方ないということでしっかりと対応してまいりたいと思っておるところです。議長不信任動議を出されましたけれども、本当にこれが議長不信任に当たるのだろうかということを…","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"意見","question":"その不信任の理由がどうのこうのだったというふうに言われておりますが、一日も早くその解決に向けて努力するというのが必要ではないかと思います。私は何度もこの間そういった取り組みをしてほしいとお願いをしている中で、何のアクションも見られないと…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"ただ、求心力ですとか政治判断というのはやはり求められると思うのですね。要望して終わります。","respondent":"久保田区議会事務局長","answer":"日程の第３０の第４４号議案、一般会計補正予算につきまして副区長から説明がありまして、総合審査は総務委員会に付託する予定です。終了時間は午後３時１０分を予定しております。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":25045,"voices":96}},{"id":"h30-20180629-10","meetingId":"h30-cm06","date":"2018年6月29日","dateIso":"2018-06-29","committee":"議会運営委員会","time":"午前 ９時３０分～午後 １時２４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"それから皆さんからお話を伺うと、いろいろな意見をお持ちの方がたくさんいらっしゃるようにも伺えます。全員でというところを皆さんにご意見を伺って、ぜひそういう打開に向けた形をとっていただければと思って、提案をしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"提案","question":"我々としても、第２回定例会、基本的には副議長進行でお願いしたいと思います。今ご提案があった全員協議会ですが、これは議長にお願いしますが、ぜひ速やかに全員協議会の招集をかけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"石田秀男委員の提案ですけれども、申し合わせ事項のところでも、議長がどう考えられるのかということをお聞かせほしいと求めました。副議長のもとで行うということに対しても、議長がどう考えられているかということによると思いますので、そこの考え方を伺いたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いや、昨日の時点での説明が必要だったのではないかということが１点です。私たちも質問をつくりながら、議会を開かないというところは本当に問題だと感じておりますので、そこのことについても申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"これは議長が決めることだと思いますので、議長のご意見を伺いたいと思いますし、私どもとしては別にこれを遮る必要はないのかなとは思っております。これについても議長のご判断だと思いますので、ご判断はお任せしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"渡部委員長","kind":"質問・要望","question":"報告できても、途中お声がけが１回もなかったということに関しては、率直におわび申し上げたいと思います。話を一通り伺った中で、全員協議会の開催を議長に求めてまいりますが、いかがか尋ねました。","respondent":"松澤議長","answer":"それが否決になったのに、また同じことの繰り返しで出されているということに対して、まさに遺憾に思っています。今、全員協議会というお話がありましたけれども、全員協議会を開くのはまだ早いのかなと思っているところです。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"提案","question":"いろいろな方々のご意見を伺って、我々も不信任動議を出すときに、今まで不信任動議が出された議会についてネットで資料を取り寄せました。我々は少しでも早く打開をして正常化をしようと思って提案させていただいているので、そこら辺をもう一度、改めてお伺いできればと思いますとの意見を述べまし…","respondent":"松澤議長","answer":"自民党・子ども未来は、議長が辞めなければ開会できないというお話やに私は受け取りました。議長を辞任する気はございませんので、進まないという中で、その中で何とか議会を開けないかというのが打開策のお話だと思っているところです。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"提案","question":"このままいくと第２回定例会がどうなるのかわからない状況の中で、一般質問、そういった提案を今しています。結論が出たのが、昨日もずっと提案をさせていただいていたので、その点についても再度要望させてほしいと求めました。","respondent":"松澤議長","answer":"会議に出ていただくようにお頼みにまいりました。終わってから全員協議会を開くなりというのが手順ではないかなと私としては思っているところですので、今すぐ全員協議会をという考えはございません。","id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはり再開をする前に全員協議会等を開いて、皆さんの意見交換の場をぜひ設けていただいて、正常化に向けての取組みをやるべきなのかなと。議会を開くために全員協議会をと我々は要望しているので、何らかの形で全員集まる場を設けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"今ご提案されている２つの会派が、お互いの言い分を聞いて、打開の歩み寄りがある可能性もあるのかなと考えております。私どもとしては、私どもは別に開催を求めているわけではございませんが、逆に議長のお立場が悪くなるのではないかなという感想を持っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"最後に１点だけ議長にお伺いしますが、我々は今この場でも主に２点要望させていただきました。これはなぜ要望したかというと、議会を開催するためにどういったことができるのかといった意味で要望させていただきましたが、説明を求めました。","respondent":"松澤議長","answer":"大変にたくさんの議案がありますので、何としても開かせていただいて、皆さん方のご協力を得たいと思います。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"提案","question":"ではどうされるのですかという質問に対しても、お答えが「出ていただければ」というだけでは、議論にならないですよね。先ほど鈴木ひろ子委員もいろいろな思いがおありでしょうから、ではその後どういう形をとるかという話まで、議運の委員長に提案しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にとても重い〔「議決もそうだよ」と呼ぶ者あり〕ものですから、やはり出席して本会議を開催するというのは、議員としての義務だと思うのですね。今回、そういう届出はあったのかということについてもお聞かせいただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"〔「違う違う。まだ開会してないのだから」と呼ぶ者あり〕との意見を述べました。","respondent":"久保田区議会事務局長","answer":"すみません、私の説明不足で。時間を追って説明しますと、１時の段階で本会議を開こうとして、出席も欠席もないということです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１時から始まるということで決まっていた本会議に、その場に来ていないというところで、それに対して、何の届出もなく本会議に来ていないということはあり得るのか尋ねました。","respondent":"久保田区議会事務局長、松澤議長","answer":"例えば予算特別委員会などで、１０時に開会しますけれども、５分とか１０分とか少しおくれて来られる方がいらっしゃいますよね。それと近いということではないとは思うのですけれども、本会議が成立した段階で出席をしていれば… オブザーバーだから発言できないというふうにしては、議長がここに出ている意味がありませんので、やはりこれは議長軽視というのでしょうか。その点についてもお答えをいただきたいと思います。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議長は今のこの状況を打開するためにはどういう考えがおありなのですかということも伺いました。そうです」と呼ぶ者あり〕 ですから、だから、では議運として諮ってくださいということをお願いしている。","respondent":"松澤議長","answer":"その中で、それを縛るようなことを議運で皆さんで決めましょうなんていうことは、とんでもないことだと私は思っているところです。そんな意味でも、議長の権限を縛ることを話し合うのだというような会議を開くのは、私は反対です。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"提案","question":"委員長の提案が幾つかあったのですけれども、私は今の議長の発言はとても重いと思うのです。結論でいうと第１０８条で示されているといった意味においては、議長の権限を超えて、ここで決めることは許されないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは議長の権限として本会議を取り仕切るということになっているわけですから、その権限を議運で決めることはできないということが１つです。それと、１９人の賛成で可決されたことは事実ですけれども、議長の任期は議員の任期によるという地方自治法に基づいての法律があるわけですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"ではどうしたらいいのですかということを今やっていこうとしているわけでありまして、そんなのは我々だってわかっていて、もちろん議長権限ですから。打開をするために全員協議会もどうですかという話をしているわけでありまして、では、１回そういう場を設けてくださいと言っているだけであるので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それを決めて議長に申し入れていくということは、やり方としても反対だし、おかしいと思います。決をとることもおかしいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"一方的な発言も伺いました。だから、歩み寄りがないから進まないという話をしているわけですから、それで、ご提案についても、これは可能だとは思うのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"ただ第２回定例会を何とかして開催をしたいという思いから、こういうことを議運で決定されるということであるならば、それは賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"申し合わせ事項ですとか地方自治法、議員必携など、これまで確認されてきたルールに基づいて打開することが大事だと考えています。議運として、副議長に運営を任せるよう、議長に要請することに対しては、共産党としては反対です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":18321,"voices":72}}]);
